// Alarm for the cross-tenant leak (2026-08-02). Every time a CDR arrives
// claiming to belong to one company while the PBX's own marker on the call says
// another, the claim is dropped and it is logged HERE. Silence on this line is
// the healthy state; anything appearing on it is a would-be leak that was
// caught. See resolveCdrTenant for the full incident note.
setTenantClaimRejectionHandler((r) => {
  app.log.error(
    {
      event: "cdr_tenant_claim_rejected_cross_tenant",
      claimedTenantId: r.claimedTenantId,
      claimedCode: r.claimedCode,
      observedCode: r.observedCode,
      dcontexts: r.dcontexts?.slice(0, 6),
      channels: r.channels?.slice(0, 6),
    },
    "cdr-ingest: REJECTED cross-tenant claim — PBX marker disagrees with claimed tenant",
  );
});
app.register(formbody);

app.setErrorHandler((error, req, reply) => {
  const status = Number((error as { statusCode?: number }).statusCode) || 500;
  if (status >= 500) {
    // Unexpected failure (e.g. an ORM error thrown mid-handler). The raw
    // message can contain schema/internal details and the portal renders the
    // "message" field verbatim in customer-facing dialogs, so clients only
    // ever get a generic body — never gate this on NODE_ENV (the api
    // container does not set it).
    app.log.error({ err: error, status, method: req.method, url: req.url }, "request_failed");
    return reply.status(500).send({
      error: "internal_error",
      message: "Something went wrong on our end. Try again.",
    });
  }
  // 4xx thrown by Fastify itself (schema validation, rate limit, bad JWT)
  // keeps its message. Routes that shape their own reply.code(...).send(...)
  // responses never reach this handler.
  return reply.status(status).send({ error: String((error as Error).message || "internal_error") });
});
