// ── Admin alert email ────────────────────────────────────────────────────────
// Central channel for everything an operator must know about this server:
// wake-health, PBX sync failures, API restarts. Rides the existing EmailJob
// queue (SendGrid/SMTP). Override recipient with env ADMIN_ALERT_EMAIL.
const ADMIN_ALERT_EMAIL = (process.env.ADMIN_ALERT_EMAIL || "tod10950@gmail.com").trim();
const ADMIN_ALERT_TENANT_ID = "connect-admin-tenant-v1";
const adminAlertLastSentAt = new Map<string, number>();
function escapeAlertHtml(v: string): string {
  return v.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
async function sendAdminAlert(key: string, subject: string, lines: string[], minIntervalMs = 6 * 3600_000): Promise<void> {
  try {
    if (!ADMIN_ALERT_EMAIL) return;
    const now = Date.now();
    // Fast path only. The authority is the database read below: this process
    // restarted 56 times on 2026-08-06, and every restart emptied this map and
    // re-armed every alert — which is how a 6h cooldown still sent one message
    // every 25 minutes and burned the mailbox's whole daily allowance.
    if (now - (adminAlertLastSentAt.get(key) ?? 0) < minIntervalMs) return;

    const fullSubject = `[Connect Alert] ${subject}`;
    const windowStart = new Date(now - ADMIN_ALERT_DAILY_WINDOW_MS);
    // The subject is what survives in the DB, so it carries the alert's
    // identity across restarts. It tracks `key` closely in practice; where it
    // drifts (a subject with a changing count), the daily cap still holds.
    const [previous, sentLast24h] = await Promise.all([
      db.emailJob.findFirst({
        where: { type: "ADMIN_ALERT", subject: fullSubject, createdAt: { gte: windowStart } },
        orderBy: { createdAt: "desc" },
        select: { createdAt: true },
      }),
      db.emailJob.count({ where: { type: "ADMIN_ALERT", createdAt: { gte: windowStart } } }),
    ]);

    const decision = decideAdminAlert({
      now,
      lastSentAtMs: previous ? previous.createdAt.getTime() : null,
      cooldownMs: minIntervalMs,
      sentLast24h,
    });
    if (!decision.send) {
      adminAlertLastSentAt.set(key, now);
      app.log.info({ adminAlert: true, key, subject, suppressed: decision.reason, sentLast24h }, "[ADMIN_ALERT] suppressed");
      return;
    }

    adminAlertLastSentAt.set(key, now);
    const textBody = lines.join("\n");
    const htmlBody = `<div style="font-family:monospace;white-space:pre-wrap">${lines.map(escapeAlertHtml).join("<br/>")}</div>`;
    await queueEmailJob({ tenantId: ADMIN_ALERT_TENANT_ID, type: "ADMIN_ALERT", toEmail: ADMIN_ALERT_EMAIL, subject: `[Connect Alert] ${subject}`, htmlBody, textBody });
    app.log.info({ adminAlert: true, key, subject }, "[ADMIN_ALERT] queued");
  } catch (e: any) {
    app.log.warn({ adminAlert: true, key, err: String(e?.message || e).slice(0, 200) }, "[ADMIN_ALERT] queue failed");
  }
}

async function queueReceiptEmail(params: { tenantId: string; to: string; amountCents: number; periodEnd: Date; receiptId: string }) {
  const dollars = (params.amountCents / 100).toFixed(2);
  const due = params.periodEnd.toISOString().slice(0, 10);
  await queueEmailJob({
    tenantId: params.tenantId,
    type: "PAYMENT_SUCCEEDED",
    toEmail: params.to,
    subject: "Your Connect Communications payment receipt",
    htmlBody: `<p>Your payment of <strong>$${dollars}</strong> succeeded.</p><p>Next billing date: ${due}</p><p>Receipt ID: ${params.receiptId}</p>`,
    textBody: `Payment succeeded. Amount: $${dollars}. Next billing date: ${due}. Receipt ID: ${params.receiptId}`
  });
}

