function hasVitalPbxPermission(user: JwtUser, permission: VitalPbxPermission): boolean {
  const role = (user.role || "USER") as StaffRole;
  const set = VITALPBX_ROLE_PERMISSIONS[role] || VITALPBX_ROLE_PERMISSIONS.USER;
  return !!set?.has(permission);
}

type VitalResourceAction = "view" | "create" | "update" | "delete";
type VitalResourcePermissionName =
  | "extensions"
  | "trunks"
  | "ring-groups"
  | "queues"
  | "ivr"
  | "routes"
  | "tenants"
  | "users"
  | "roles"
  | "cdr"
  | "devices"
  | "device-profiles"
  | "destinations"
  | "classes-of-services"
  | "conferences"
  | "phonebooks"
  | "route-selections"
  | "account-codes"
  | "authorization-codes"
  | "customer-codes"
  | "ai-api-keys"
  | "sms"
  | "whatsapp"
  | "virtual-faxes"
  | "voicemail"
  | "parking-lots";

function canAccessVitalResourceAction(user: JwtUser, resource: VitalResourcePermissionName, action: VitalResourceAction): boolean {
  const permissionFor = (r: VitalResourcePermissionName, a: VitalResourceAction): VitalPbxPermission | null => {
    if (r === "extensions") {
      if (a === "view") return "vitalpbx.extensions.view";
      if (a === "create") return "vitalpbx.extensions.create";
      if (a === "update") return "vitalpbx.extensions.update";
      return "vitalpbx.extensions.delete";
    }
    if (r === "routes") return a === "view" ? "vitalpbx.outboundRoutes.view" : a === "create" ? "vitalpbx.outboundRoutes.create" : a === "update" ? "vitalpbx.outboundRoutes.update" : "vitalpbx.outboundRoutes.delete";
    if (r === "ivr") return a === "view" ? "vitalpbx.ivr.view" : a === "create" ? "vitalpbx.ivr.create" : a === "update" ? "vitalpbx.ivr.update" : "vitalpbx.ivr.delete";
    if (r === "ring-groups") return a === "view" ? "vitalpbx.ringGroups.view" : a === "create" ? "vitalpbx.ringGroups.create" : a === "update" ? "vitalpbx.ringGroups.update" : "vitalpbx.ringGroups.delete";
    if (r === "queues") return a === "view" ? "vitalpbx.queues.view" : a === "create" ? "vitalpbx.queues.create" : a === "update" ? "vitalpbx.queues.update" : "vitalpbx.queues.delete";
    if (r === "cdr") return a === "view" ? "vitalpbx.cdr.view" : null;
    if (r === "voicemail") return a === "view" ? "vitalpbx.voicemail.view" : a === "delete" ? "vitalpbx.voicemail.delete" : "vitalpbx.voicemail.updateSettings";
    if (r === "account-codes") return a === "view" ? "vitalpbx.accountCodes.view" : null;
    if (r === "authorization-codes") return a === "view" ? "vitalpbx.authorizationCodes.view" : a === "create" ? "vitalpbx.authorizationCodes.create" : a === "update" ? "vitalpbx.authorizationCodes.update" : "vitalpbx.authorizationCodes.delete";
    if (r === "customer-codes") return a === "view" ? "vitalpbx.customerCodes.view" : a === "create" ? "vitalpbx.customerCodes.create" : a === "update" ? "vitalpbx.customerCodes.update" : "vitalpbx.customerCodes.delete";
    if (r === "ai-api-keys") return a === "view" ? "vitalpbx.aiApiKeys.view" : a === "create" ? "vitalpbx.aiApiKeys.create" : a === "update" ? "vitalpbx.aiApiKeys.update" : "vitalpbx.aiApiKeys.delete";
    if (r === "tenants") return a === "view" ? "vitalpbx.tenants.view" : a === "create" ? "vitalpbx.tenants.create" : a === "update" ? "vitalpbx.tenants.update" : "vitalpbx.tenants.delete";
    if (r === "trunks" || r === "users" || r === "roles" || r === "devices" || r === "device-profiles" || r === "destinations" || r === "classes-of-services" || r === "conferences" || r === "phonebooks" || r === "route-selections" || r === "parking-lots" || r === "virtual-faxes" || r === "sms" || r === "whatsapp") {
      return a === "view" ? "vitalpbx.extensions.view" : "vitalpbx.extensions.update";
    }
    return null;
  };
  const p = permissionFor(resource, action);
  if (!p) return false;
  return hasVitalPbxPermission(user, p);
}

async function requirePermission(req: any, reply: any, checker: (user: JwtUser) => boolean): Promise<JwtUser | null> {
  const user = getUser(req);
  if (!checker(user)) {
    reply.status(403).send({ error: "forbidden" });
    return null;
  }
  return user;
}

async function requireAdmin(req: any, reply: any): Promise<JwtUser | null> {
  return requirePermission(req, reply, (user) => isRole(user, ["ADMIN", "TENANT_ADMIN", "SUPER_ADMIN"]));
}

/**
 * Additive-OR gate: allow when the existing role check passes OR when the user
 * effectively holds the given portal permission key (e.g. via an authoritative
 * custom role). Sends 403 and returns null otherwise. Never narrows existing
 * role-based access — only widens it to custom-role grantees.
 */
async function requireRoleOrPortalPermission(
  req: any,
  reply: any,
  checker: (user: JwtUser) => boolean,
  key: string,
): Promise<JwtUser | null> {
  const user = getUser(req);
  const allowed = decideActionGate({
    roleAllowed: checker(user),
    hasKey: await userHasActionPermission(user, key),
  });
  if (!allowed) {
    reply.status(403).send({ error: "forbidden" });
    return null;
  }
  return user;
}

/** Additive-OR convenience: tenant/admin role OR the given portal permission key. */
async function requireAdminOrPortalPermission(req: any, reply: any, key: string): Promise<JwtUser | null> {
  return requireRoleOrPortalPermission(
    req,
    reply,
    (user) => isRole(user, ["ADMIN", "TENANT_ADMIN", "SUPER_ADMIN"]),
    key,
  );
}

/**
 * Authoritative permission gate: allow ONLY when the user effectively holds the
 * key (no legacy role fallback). For custom-role users this is exactly their
 * role's permissions; for plain users it follows their bucket snapshot. Use for
 * actions where the editor toggle must be fully authoritative (e.g. contacts).
 * SUPER_ADMIN passes because its bucket includes every key.
 */
async function requirePortalActionPermission(req: any, reply: any, key: string): Promise<JwtUser | null> {
  return requireRoleOrPortalPermission(req, reply, () => false, key);
}

async function requireSuperAdmin(req: any, reply: any): Promise<JwtUser | null> {
  return requirePermission(req, reply, canAccessAdminSbc);
}


function maskHostOnly(value: unknown): string | null {
  const raw = String(value || "").trim();
  if (!raw) return null;
  try {
    if (raw.includes("://")) return new URL(raw).host.toLowerCase();
    const host = raw.split("/")[0].trim().toLowerCase();
    return host || null;
  } catch {
    return null;
  }
}

function maskHostLabel(value: string): string {
  const normalized = String(value || "").trim().toLowerCase();
  if (!normalized) return "[unset]";
  return maskValue(normalized, 2, 2) || "[hidden]";
}

function normalizeVoiceRegState(v: unknown): "IDLE" | "REGISTERING" | "REGISTERED" | "FAILED" {
  const x = String(v || "").toLowerCase();
  if (x.includes("registering")) return "REGISTERING";
  if (x.includes("registered")) return "REGISTERED";
  if (x.includes("fail")) return "FAILED";
  return "IDLE";
}

function normalizeVoiceCallState(v: unknown): "IDLE" | "DIALING" | "RINGING" | "CONNECTED" | "ENDED" {
  const x = String(v || "").toLowerCase();
  if (x.includes("dial")) return "DIALING";
  if (x.includes("ring")) return "RINGING";
  if (x.includes("connect")) return "CONNECTED";
  if (x.includes("end") || x.includes("term")) return "ENDED";
  return "IDLE";
}

function sanitizeDiagPayload(input: any): any {
  const blocked = new Set(["password", "sipPassword", "authorization", "auth", "token", "secret", "sdp", "headers"]);
  function walk(v: any): any {
    if (v === null || v === undefined) return v;
    if (Array.isArray(v)) return v.slice(0, 50).map((x) => walk(x));
    if (typeof v === "object") {
      const out: any = {};
      for (const [k, val] of Object.entries(v)) {
        const key = String(k);
        if (blocked.has(key) || key.toLowerCase().includes("password") || key.toLowerCase().includes("secret")) {
          out[key] = "[REDACTED]";
          continue;
        }
        out[key] = walk(val);
      }
      return out;
    }
    if (typeof v === "string") return v.length > 512 ? `${v.slice(0, 512)}...` : v;
    return v;
  }
  return walk(input || {});
}

function checkVoiceDiagHeartbeatLimit(sessionId: string): boolean {
  const now = Date.now();
  const last = voiceDiagHeartbeatLimiter.get(sessionId) || 0;
  if (now - last < 60_000) return false;
  voiceDiagHeartbeatLimiter.set(sessionId, now);
  return true;
}

function checkVoiceDiagEventLimit(sessionId: string, max = 60, windowMs = 60_000): boolean {
  const now = Date.now();
  const arr = (voiceDiagEventLimiter.get(sessionId) || []).filter((ts) => now - ts < windowMs);
  if (arr.length >= max) {
    voiceDiagEventLimiter.set(sessionId, arr);
    return false;
  }
  arr.push(now);
  voiceDiagEventLimiter.set(sessionId, arr);
  return true;
}


function maskUsername(value: string | null | undefined): string | null {
  if (!value) return null;
  const v = String(value);
  if (v.length <= 4) return `${v[0] || "*"}***`;
  return `${v.slice(0, 2)}***${v.slice(-2)}`;
}

function normalizeTurnUrls(input: unknown): string[] {
  if (!Array.isArray(input)) return [];
  return input.map((x) => String(x || "").trim()).filter((x) => x.length > 0);
}

function validateTurnUrls(urls: string[]): { ok: boolean; error?: string } {
  if (!urls.length) return { ok: false, error: "TURN_URLS_REQUIRED" };
  for (const u of urls) {
    const x = u.toLowerCase();
    if (!x.startsWith("turn:") && !x.startsWith("turns:")) return { ok: false, error: "TURN_URL_MUST_USE_TURN_SCHEME" };
  }
  return { ok: true };
}

function buildTurnConfigPublicView(cfg: any) {
  const urls = normalizeTurnUrls(cfg?.urls || []).map((u) => maskHostOnly(u) || "masked");
  return {
    scope: cfg?.scope || "GLOBAL",
    tenantId: cfg?.tenantId || null,
    urls,
    username: maskUsername(cfg?.username || null),
    hasCredential: !!cfg?.credentialEncrypted,
    updatedAt: cfg?.updatedAt || null
  };
}

function signTurnValidationToken(input: { jobId: string; tokenId: string; tenantId: string; userId: string; expMs: number }): string {
  const payload = Buffer.from(JSON.stringify(input)).toString("base64url");
  const sig = createHmac("sha256", turnValidationTokenSecret).update(payload).digest("base64url");
  return `${payload}.${sig}`;
}

function verifyTurnValidationToken(token: string): null | { jobId: string; tokenId: string; tenantId: string; userId: string; expMs: number } {
  const t = String(token || "").trim();
  const idx = t.lastIndexOf(".");
  if (idx <= 0) return null;
  const payload = t.slice(0, idx);
  const sig = t.slice(idx + 1);
  const expected = createHmac("sha256", turnValidationTokenSecret).update(payload).digest();
  const given = Buffer.from(sig, "base64url");
  if (given.length !== expected.length) return null;
  if (!timingSafeEqual(expected, given)) return null;
  try {
    const parsed = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
    if (!parsed?.jobId || !parsed?.tokenId || !parsed?.tenantId || !parsed?.userId || !parsed?.expMs) return null;
    if (Number(parsed.expMs) < Date.now()) return null;
    return {
      jobId: String(parsed.jobId),
      tokenId: String(parsed.tokenId),
      tenantId: String(parsed.tenantId),
      userId: String(parsed.userId),
      expMs: Number(parsed.expMs)
    };
  } catch {
    return null;
  }
}

function signMediaTestToken(input: { runId: string; tokenId: string; tenantId: string; userId: string; expMs: number }): string {
  const payload = Buffer.from(JSON.stringify(input)).toString("base64url");
  const sig = createHmac("sha256", mediaTestTokenSecret).update(payload).digest("base64url");
  return `${payload}.${sig}`;
}

function verifyMediaTestToken(token: string): null | { runId: string; tokenId: string; tenantId: string; userId: string; expMs: number } {
  const t = String(token || "").trim();
  const idx = t.lastIndexOf(".");
  if (idx <= 0) return null;
  const payload = t.slice(0, idx);
  const sig = t.slice(idx + 1);
  const expected = createHmac("sha256", mediaTestTokenSecret).update(payload).digest();
  const given = Buffer.from(sig, "base64url");
  if (given.length != expected.length) return null;
  if (!timingSafeEqual(expected, given)) return null;
  try {
    const parsed = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
    if (!parsed?.runId || !parsed?.tokenId || !parsed?.tenantId || !parsed?.userId || !parsed?.expMs) return null;
    if (Number(parsed.expMs) < Date.now()) return null;
    return {
      runId: String(parsed.runId),
      tokenId: String(parsed.tokenId),
      tenantId: String(parsed.tenantId),
      userId: String(parsed.userId),
      expMs: Number(parsed.expMs)
    };
  } catch {
    return null;
  }
}


function hashToken(value: string): string {
  return createHash("sha256").update(String(value || "")).digest("hex");
}

const INVITE_TOKEN_HOURS = 72;
const RESET_TOKEN_MINUTES = 60;
const USER_MANAGEMENT_ROLES = [
  "SUPER_ADMIN",
  "TENANT_ADMIN",
  "MANAGER",
  "USER",
  "EXTENSION_USER",
  "BILLING_ADMIN",
  "READ_ONLY",
  "ADMIN",
  "BILLING",
] as const;

type UserManagementRole = typeof USER_MANAGEMENT_ROLES[number];

function normalizeEmail(email: string): string {
  return String(email || "").trim().toLowerCase();
}

function displayNameForUser(user: { firstName?: string | null; lastName?: string | null; displayName?: string | null; email?: string | null }): string {
  const direct = String(user.displayName || "").trim();
  if (direct) return direct;
  const joined = [user.firstName, user.lastName].map((v) => String(v || "").trim()).filter(Boolean).join(" ");
  if (joined) return joined;
  return String(user.email || "User").split("@")[0] || "User";
}

function portalPublicUrl(pathname: string): string {
  const origin = String(process.env.PORTAL_PUBLIC_URL || process.env.CONNECT_APP_URL || process.env.APP_PUBLIC_URL || "https://app.connectcomunications.com").replace(/\/$/, "");
  return `${origin}${pathname.startsWith("/") ? pathname : `/${pathname}`}`;
}

function generatePasswordToken(): string {
  return `cp_${randomBytes(32).toString("base64url")}`;
}

function passwordScore(password: string): number {
  let score = 0;
  if (password.length >= 10) score++;
  if (/[a-z]/.test(password) && /[A-Z]/.test(password)) score++;
  if (/\d/.test(password)) score++;
  if (/[^A-Za-z0-9]/.test(password)) score++;
  return score;
}

function validateNewPassword(password: string): string | null {
  if (password.length < 10) return "PASSWORD_TOO_SHORT";
  if (passwordScore(password) < 3) return "PASSWORD_TOO_WEAK";
  return null;
}

function canManageUsers(user: JwtUser): boolean {
  return isRole(user, ["SUPER_ADMIN", "TENANT_ADMIN", "ADMIN"]);
}

function canAssignRole(actor: JwtUser, role: UserManagementRole): boolean {
  if (actor.role === "SUPER_ADMIN") return true;
  return role !== "SUPER_ADMIN";
}

function roleLabel(role: string): string {
  if (role === "ADMIN") return "TENANT_ADMIN";
  if (role === "BILLING") return "BILLING_ADMIN";
  if (role === "EXTENSION_USER") return "USER";
  return role;
}

function normalizeTenantLookupValue(value: string): string {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/^vpbx:/, "")
    .replace(/[_\s-]+/g, "_")
    .replace(/[^a-z0-9_]/g, "");
}

/**
 * Connect tenant id for admin-only actions that must never use SUPER_ADMIN's
 * ambiguous "first tenant" fallback. Requires an explicit workspace context
 * for super-admins (x-tenant-context or vpbx: slug).
 */
async function resolveConnectTenantIdForAdminExtensionPairing(
  req: any,
  admin: JwtUser
): Promise<{ tenantId: string } | { error: string; status: number }> {
  if (admin.role !== "SUPER_ADMIN") {
    return { tenantId: admin.tenantId };
  }
  const raw = String((req.headers as any)["x-tenant-context"] || "").trim();
  if (!raw || raw === "local") return { error: "TENANT_CONTEXT_REQUIRED", status: 400 };

  if (raw.startsWith("vpbx:")) {
    const slug = raw.slice(5).trim();
    const normalized = normalizeTenantLookupValue(slug);

    // Try the standard resolver first (prefers LINKED links). resolveManagedTenant never
    // throws for SUPER_ADMIN — it falls back to the first tenant alphabetically when the
    // slug has no LINKED link match. Verify the returned tenant name actually matches the
    // slug so we don't silently use the wrong tenant.
    try {
      const tenantId = await resolveManagedTenant(admin, raw);
      const t = await db.tenant.findUnique({ where: { id: tenantId }, select: { id: true, name: true } });
      if (t && normalizeTenantLookupValue(t.name) === normalized) {
        return { tenantId };
      }
    } catch {
      // fall through
    }

    // Broader fallback: match against any TenantPbxLink regardless of status.
    // This covers tenants whose link is in ERROR/PENDING state — the link status
    // only governs PBX connectivity, not whether we can identify the tenant.
    const allLinks = await db.tenantPbxLink.findMany({
      include: { tenant: { select: { id: true, name: true } } },
      take: 500,
    });
    const matchedLink = allLinks.find((link) => {
      const candidates = [link.pbxTenantId, link.pbxTenantCode, link.tenant?.name]
        .map((v) => normalizeTenantLookupValue(String(v || "")));
      return candidates.includes(normalized);
    });
    if (matchedLink) return { tenantId: matchedLink.tenantId };

    return { error: "TENANT_NOT_FOUND", status: 404 };
  }

  const row = await db.tenant.findUnique({ where: { id: raw }, select: { id: true } });
  if (!row) return { error: "TENANT_NOT_FOUND", status: 404 };
  return { tenantId: row.id };
}

async function resolveManagedTenant(actor: JwtUser, requestedTenantId?: string | null): Promise<string> {
  if (actor.role === "SUPER_ADMIN") {
    const rawTenantId = String(requestedTenantId || actor.tenantId || "").trim();
    if (rawTenantId && !rawTenantId.startsWith("vpbx:")) {
      const tenant = await db.tenant.findUnique({ where: { id: rawTenantId }, select: { id: true } });
      if (tenant) return tenant.id;
    }

    if (rawTenantId.startsWith("vpbx:")) {
      const slug = rawTenantId.slice(5).trim();
      const normalized = normalizeTenantLookupValue(slug);
      const links = await db.tenantPbxLink.findMany({
        where: { status: "LINKED" },
        include: { tenant: { select: { id: true, name: true } } },
        take: 500,
      });
      const direct = links.find((link) => {
        const candidates = [
          link.pbxTenantId,
          link.pbxTenantCode,
          link.tenant?.name,
        ].map((v) => normalizeTenantLookupValue(String(v || "")));
        return candidates.includes(normalized);
      });
      if (direct) return direct.tenantId;

      const directory = await db.pbxTenantDirectory.findFirst({
        where: {
          OR: [
            { tenantSlug: slug },
            { tenantCode: slug },
            { vitalTenantId: slug },
            { tenantSlug: normalized },
            { tenantCode: normalized },
          ],
        },
      }).catch(() => null);
      if (directory) {
        const byDirectory = links.find((link) => {
          if (link.pbxInstanceId !== directory.pbxInstanceId) return false;
          return [link.pbxTenantId, link.pbxTenantCode]
            .map((v) => normalizeTenantLookupValue(String(v || "")))
            .some((v) => v === normalizeTenantLookupValue(directory.vitalTenantId) || v === normalizeTenantLookupValue(directory.tenantCode));
        });
        if (byDirectory) return byDirectory.tenantId;

        // PBX tenant exists in directory but has no Connect tenant yet.
        // Auto-provision a real Tenant + TenantPbxLink so the caller can
        // immediately create users, extensions, etc. for this tenant.
        const displayName =
          (directory as any).displayName ||
          String((directory as any).tenantSlug || "").replace(/[_-]/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase()) ||
          `PBX Tenant ${directory.vitalTenantId}`;
        const provisioned = await db.$transaction(async (tx) => {
          const t = await tx.tenant.create({
            data: { name: displayName, kind: "CUSTOMER" as any, isApproved: true },
          });
          await (tx as any).tenantPbxLink.create({
            data: {
              tenantId: t.id,
              pbxInstanceId: directory.pbxInstanceId,
              pbxTenantId: directory.vitalTenantId,
              pbxTenantCode: (directory as any).tenantCode ?? null,
              status: "LINKED",
            },
          });
          return t;
        });
        return provisioned.id;
      }
    }

    const fallback = await db.tenant.findFirst({ orderBy: { name: "asc" }, select: { id: true } });
    if (!fallback) throw new Error("TENANT_REQUIRED");
    return fallback.id;
  }
  return actor.tenantId;
}

function formatAdminUser(row: any) {
  const extension = row.ownedExtensions?.[0] || null;
  const token = row.passwordTokens?.[0] || null;
  return {
    id: row.id,
    tenantId: row.tenantId,
    tenantName: row.tenant?.name || null,
    email: row.email,
    firstName: row.firstName || "",
    lastName: row.lastName || "",
    displayName: displayNameForUser(row),
    phone: row.phone || "",
    title: row.title || "",
    department: row.department || "",
    notes: row.notes || "",
    role: row.role,
    roleLabel: roleLabel(row.role),
    // Custom roles are additive on top of the platform role bucket. The list
    // handler attaches __customRoles (batched); other callers default to [].
    customRoles: Array.isArray(row.__customRoles)
      ? row.__customRoles.map((c: any) => ({ id: c.id, name: c.name }))
      : [],
    status: row.status || "ACTIVE",
    emailVerifiedAt: row.emailVerifiedAt || null,
    lastLoginAt: row.lastLoginAt || null,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt || row.createdAt,
    extension: extension
      ? { id: extension.id, extNumber: extension.extNumber, displayName: extension.displayName, status: extension.status, pbxUserEmail: extension.pbxUserEmail || null }
      : null,
    invite: token ? { id: token.id, type: token.type, expiresAt: token.expiresAt, usedAt: token.usedAt, createdAt: token.createdAt } : null,
  };
}

async function createUserPasswordToken(params: {
  userId: string;
  type: "INVITE" | "PASSWORD_RESET";
  ttlMs: number;
  createdBy?: string | null;
  ipAddress?: string | null;
  userAgent?: string | null;
}): Promise<{ token: string; expiresAt: Date }> {
  const token = generatePasswordToken();
  const expiresAt = new Date(Date.now() + params.ttlMs);
  await db.userPasswordToken.create({
    data: {
      userId: params.userId,
      tokenHash: hashToken(token),
      type: params.type,
      expiresAt,
      createdBy: params.createdBy || null,
      ipAddress: params.ipAddress || null,
      userAgent: params.userAgent || null,
    } as any,
  });
  return { token, expiresAt };
}

