const signupSchema = z.object({ tenantName: z.string().min(2), email: z.string().email(), password: z.string().min(8) });

/**
 * Production smoke-tenant firewall.
 *
 * CI smoke tests historically called /auth/signup against the production API
 * with names like "Billing Smoke Tenant", "Admin Tenant 1772002300",
 * "PBX Smoke 1771998952", "Verify Tenant 1771907715", "dbg 1772514785",
 * "Tenant Smoke 1771938273", "v0.7 Smoke", "'X Tenant'", etc. — creating
 * hundreds of garbage tenants that polluted the admin dropdowns.
 *
 * Block all of them at the edge regardless of who's calling. Real customers
 * never name their workspace "Billing Smoke Tenant" or "Admin Tenant 177...".
 */
const SMOKE_TENANT_NAME_PATTERNS: RegExp[] = [
  /\bsmoke\b/i,
  /\bdbg\b/i,
  /\bvpbx\s+(perm|header)\b/i,
  /\bverify\s+tenant\b/i,
  /\badmin\s+tenant\b/i,
  /^tenant\s+\d{6,}\b/i,
  /\bv[0-9]+\.[0-9]+\b.*smoke/i,
  /^"?'?x\s+tenant'?"?$/i,
  /\bconnect\s+admin\s+\d{6,}\b/i,
  /\bsbc\s+(switch|remote|functional|rollout)\b/i,
];
function looksLikeSmokeTenantName(name: string): boolean {
  const v = (name || "").trim();
  if (!v) return false;
  return SMOKE_TENANT_NAME_PATTERNS.some((re) => re.test(v));
}

app.post("/auth/signup", async (req, reply) => {
  const input = signupSchema.parse(req.body);
  const ip = String((req.headers["x-forwarded-for"] as string | undefined) || req.ip || "unknown").split(",")[0].trim();
  if (!checkBillingRateLimit(`signup:${ip}`, 5, 60 * 60 * 1000)) {
    app.log.warn({ ip, endpoint: "/auth/signup" }, "rate_limit_signup");
    return reply.status(429).send({ error: "RATE_LIMITED" });
  }
  if (looksLikeSmokeTenantName(input.tenantName)) {
    app.log.warn(
      { ip, tenantName: input.tenantName, email: input.email, endpoint: "/auth/signup" },
      "rejected_smoke_tenant_signup"
    );
    return reply.status(400).send({
      error: "TENANT_NAME_RESERVED",
      message: "This workspace name is reserved for internal testing.",
    });
  }
  const tenant = await db.tenant.create({
    data: {
      name: input.tenantName,
      isApproved: false,
      dailySmsCap: 100,
      perSecondRate: 1.0,
      firstCampaignRequiresApproval: true,
      smsSendMode: "TEST",
      dailySmsLimit: DEFAULT_DAILY_LIMIT,
      hourlySmsLimit: DEFAULT_HOURLY_LIMIT,
      perSecondRateLimit: DEFAULT_PER_SECOND,
      maxCampaignSize: DEFAULT_MAX_CAMPAIGN,
      smsSuspended: false,
      smsRoutingMode: "FAILOVER",
      smsPrimaryProvider: "TWILIO",
      smsSecondaryProvider: "VOIPMS",
      numberPurchaseEnabled: true
    }
  });

  const passwordHash = await bcrypt.hash(input.password, 10);
  const normalizedEmail = input.email.toLowerCase();
  const role = normalizedEmail.startsWith("support") && normalizedEmail.endsWith("@connectcomunications.com") ? "ADMIN" : "USER";
  const user = await db.user.create({
    data: {
      tenantId: tenant.id,
      email: normalizedEmail,
      passwordHash,
      role,
      status: "ACTIVE" as any,
      displayName: normalizedEmail.split("@")[0],
      emailVerifiedAt: new Date(),
    } as any,
  });

  await audit({ tenantId: tenant.id, actorUserId: user.id, action: "TENANT_SIGNUP_CREATED", entityType: "Tenant", entityId: tenant.id });
  const token = await reply.jwtSign({ sub: user.id, tenantId: tenant.id, email: user.email, role: user.role, name: displayNameForUser(user as any) });
  return { token, user: { id: user.id, email: user.email, role: user.role }, tenant: { id: tenant.id, name: tenant.name } };
});

app.post("/auth/login", async (req, reply) => {
  const input = z.object({ email: z.string().email(), password: z.string().min(8) }).parse(req.body);
  const emailKey = input.email.toLowerCase();
  const loginRateLimitEnabled = process.env.NODE_ENV === "production"
    || (process.env.LOGIN_RATE_LIMIT_DEV || "").toLowerCase() === "1";
  if (
    loginRateLimitEnabled
    && !checkBillingRateLimit(`login:${emailKey}`, 10, 15 * 60 * 1000)
  ) {
    app.log.warn({ email: emailKey, ip: req.ip, endpoint: "/auth/login" }, "rate_limit_login");
    loginFailuresTotal.labels("rate_limit").inc();
    return reply.status(429).send({ error: "RATE_LIMITED" });
  }
  // Primary lookup against the canonical (lowercased) form; fall back to a
  // case-insensitive match so a user imported with mixed-case email (e.g.
  // "Relaxtires@gmail.com" from VitalPBX sync) is not permanently locked out
  // if a future write-path regression lets a non-normalized email through.
  let user = await db.user.findUnique({ where: { email: emailKey } });
  if (!user) {
    user = await db.user.findFirst({ where: { email: { equals: emailKey, mode: "insensitive" } } });
    if (user && user.email !== emailKey) {
      app.log.warn(
        { userId: user.id, storedEmail: user.email, loginEmail: emailKey },
        "auth_login_email_case_mismatch",
      );
    }
  }
  if (!user) {
    loginFailuresTotal.labels("not_found").inc();
    return reply.status(401).send({ error: "invalid_credentials" });
  }
  if ((user as any).status === "DISABLED") {
    loginFailuresTotal.labels("bad_password").inc();
    return reply.status(403).send({ error: "account_disabled" });
  }
  if (!(await bcrypt.compare(input.password, user.passwordHash))) {
    loginFailuresTotal.labels("bad_password").inc();
    return reply.status(401).send({ error: "invalid_credentials" });
  }
  loginSuccessTotal.inc();
  await db.user.update({ where: { id: user.id }, data: { lastLoginAt: new Date(), status: "ACTIVE" as any } as any }).catch(() => undefined);
  const token = await reply.jwtSign({
    sub: user.id,
    tenantId: user.tenantId,
    email: user.email,
    role: user.role,
    name: displayNameForUser(user as any),
  });
  const portalPermissionSet = await resolvePortalPermissionsWithCrmUserAccess(
    user.role,
    user.id,
    user.tenantId,
  );
  return {
    token,
    ...(portalPermissionSet ? { portalPermissionSet } : {}),
  };
});

app.get("/auth/invite/validate", async (req, reply) => {
  const query = z.object({ token: z.string().min(20) }).parse(req.query || {});
  const row = await db.userPasswordToken.findUnique({
    where: { tokenHash: hashToken(query.token) },
    include: { user: { include: { tenant: { select: { name: true } }, ownedExtensions: { take: 1 } } } },
  } as any) as any;
  const now = new Date();
  if (!row || row.type !== "INVITE" || row.usedAt || row.expiresAt < now || row.user?.status === "DISABLED") {
    return reply.status(400).send({ error: "TOKEN_INVALID_OR_EXPIRED" });
  }
  return {
    ok: true,
    email: row.user.email,
    name: displayNameForUser(row.user),
    tenantName: row.user.tenant?.name || "",
    extension: row.user.ownedExtensions?.[0]?.extNumber || null,
    expiresAt: row.expiresAt,
  };
});

app.post("/auth/invite/accept", async (req, reply) => {
  const input = z.object({ token: z.string().min(20), password: z.string().min(1), confirmPassword: z.string().min(1) }).parse(req.body || {});
  if (input.password !== input.confirmPassword) return reply.status(400).send({ error: "PASSWORD_MISMATCH" });
  const passwordError = validateNewPassword(input.password);
  if (passwordError) return reply.status(400).send({ error: passwordError });
  const now = new Date();
  const row = await db.userPasswordToken.findUnique({ where: { tokenHash: hashToken(input.token) }, include: { user: true } } as any) as any;
  if (!row || row.type !== "INVITE" || row.usedAt || row.expiresAt < now || row.user?.status === "DISABLED") {
    return reply.status(400).send({ error: "TOKEN_INVALID_OR_EXPIRED" });
  }
  const passwordHash = await bcrypt.hash(input.password, 10);
  const updated = await db.$transaction(async (tx) => {
    const consumed = await tx.userPasswordToken.updateMany({ where: { id: row.id, usedAt: null, expiresAt: { gte: now } }, data: { usedAt: now } });
    if (consumed.count === 0) throw new Error("TOKEN_INVALID_OR_EXPIRED");
    return tx.user.update({ where: { id: row.userId }, data: { passwordHash, status: "ACTIVE" as any, emailVerifiedAt: now, forcePasswordReset: false } as any });
  });
  await audit({ tenantId: updated.tenantId, actorUserId: updated.id, targetUserId: updated.id, action: "USER_INVITE_ACCEPTED", entityType: "User", entityId: updated.id });
  // Send "account is ready" confirmation email — fire and forget, must not block login
  try {
    const [tenantRow, extRow] = await Promise.all([
      db.tenant.findUnique({ where: { id: updated.tenantId }, select: { name: true } }),
      (db.extension as any).findFirst({ where: { userId: updated.id }, select: { extNumber: true }, orderBy: { createdAt: "asc" } }),
    ]);
    await queuePasswordCreatedEmail({
      user: updated,
      tenantName: (tenantRow as any)?.name || "",
      extensionNumber: (extRow as any)?.extNumber || null,
    });
  } catch {
    // confirmation email failure must never block the accept response
  }
  return { ok: true };
});

app.post("/auth/password/forgot", async (req) => {
  const input = z.object({ email: z.string().email() }).parse(req.body || {});
  const email = normalizeEmail(input.email);
  if (!checkBillingRateLimit(`forgot-password:${email}`, 5, 60 * 60 * 1000)) return { ok: true };
  // Mirror /auth/login: prefer the unique-index lookup, fall back to a
  // case-insensitive scan so legacy mixed-case rows still receive their
  // reset email instead of silently no-op-ing.
  let user = await db.user.findUnique({ where: { email } });
  if (!user) {
    user = await db.user.findFirst({ where: { email: { equals: email, mode: "insensitive" } } });
  }
  if (user && (user as any).status !== "DISABLED") {
    const { token } = await createUserPasswordToken({ userId: user.id, type: "PASSWORD_RESET", ttlMs: RESET_TOKEN_MINUTES * 60 * 1000, ipAddress: req.ip, userAgent: String(req.headers["user-agent"] || "") });
    await queuePasswordResetEmail({ user, token });
    await audit({ tenantId: user.tenantId, targetUserId: user.id, action: "PASSWORD_RESET_REQUESTED", entityType: "User", entityId: user.id, metadata: { selfService: true } });
  }
  return { ok: true };
});

app.get("/auth/password/reset/validate", async (req, reply) => {
  const query = z.object({ token: z.string().min(20) }).parse(req.query || {});
  const row = await db.userPasswordToken.findUnique({ where: { tokenHash: hashToken(query.token) }, include: { user: true } } as any) as any;
  const now = new Date();
  if (!row || row.type !== "PASSWORD_RESET" || row.usedAt || row.expiresAt < now || row.user?.status === "DISABLED") {
    return reply.status(400).send({ error: "TOKEN_INVALID_OR_EXPIRED" });
  }
  return { ok: true, email: row.user.email, name: displayNameForUser(row.user), expiresAt: row.expiresAt };
});

app.post("/auth/password/reset", async (req, reply) => {
  const input = z.object({ token: z.string().min(20), password: z.string().min(1), confirmPassword: z.string().min(1) }).parse(req.body || {});
  if (input.password !== input.confirmPassword) return reply.status(400).send({ error: "PASSWORD_MISMATCH" });
  const passwordError = validateNewPassword(input.password);
  if (passwordError) return reply.status(400).send({ error: passwordError });
  const now = new Date();
  const row = await db.userPasswordToken.findUnique({ where: { tokenHash: hashToken(input.token) }, include: { user: true } } as any) as any;
  if (!row || row.type !== "PASSWORD_RESET" || row.usedAt || row.expiresAt < now || row.user?.status === "DISABLED") {
    return reply.status(400).send({ error: "TOKEN_INVALID_OR_EXPIRED" });
  }
  const passwordHash = await bcrypt.hash(input.password, 10);
  const updated = await db.$transaction(async (tx) => {
    const consumed = await tx.userPasswordToken.updateMany({ where: { id: row.id, usedAt: null, expiresAt: { gte: now } }, data: { usedAt: now } });
    if (consumed.count === 0) throw new Error("TOKEN_INVALID_OR_EXPIRED");
    return tx.user.update({ where: { id: row.userId }, data: { passwordHash, status: "ACTIVE" as any, forcePasswordReset: false } as any });
  });
  await audit({ tenantId: updated.tenantId, actorUserId: updated.id, targetUserId: updated.id, action: "PASSWORD_RESET_COMPLETED", entityType: "User", entityId: updated.id });
  const template = passwordChangedEmail({ userName: displayNameForUser(updated as any) });
  await queueEmailJob({ tenantId: updated.tenantId, type: "PASSWORD_CHANGED", toEmail: updated.email, subject: template.subject, htmlBody: template.html, textBody: template.text }).catch(() => undefined);
  return { ok: true };
});

// Unauthenticated — used by mobile app to log in AND provision via QR scan in one step.
// The QR code contains a short-lived HMAC-signed token issued by POST /voice/mobile-provisioning/token.
// Returns a full mobile session JWT + SIP provisioning bundle, eliminating the need for
// the mobile app to already be authenticated before provisioning.
app.post("/auth/mobile-qr-exchange", async (req, reply) => {
  const input = z.object({
    token: z.string().min(12),
    deviceInfo: z.object({
      platform: z.enum(["IOS", "ANDROID"]).optional(),
      deviceName: z.string().max(128).optional(),
      expoPushToken: z.string().optional(),
      voipPushToken: z.string().optional(),
    }).optional(),
  }).parse(req.body || {});

  // Rate-limit by token hash to prevent brute-force without leaking the token
  const tokenHash = hashToken(input.token);
  if (!checkBillingRateLimit(`qr-exchange:${tokenHash.slice(0, 16)}`, 5, 60 * 1000)) {
    return reply.status(429).send({ error: "RATE_LIMITED" });
  }

  // Verify HMAC signature and expiry embedded in the token
  const verified = verifyMobileProvisioningToken(input.token);
  if (!verified) return reply.status(400).send({ error: "TOKEN_INVALID" });

  // Fetch the stored token record
  const tokenRow = await db.mobileProvisioningToken.findFirst({
    where: { tokenHash, tenantId: verified.tenantId, userId: verified.userId }
  });
  if (!tokenRow) return reply.status(400).send({ error: "TOKEN_INVALID" });
  if (tokenRow.usedAt) return reply.status(400).send({ error: "TOKEN_ALREADY_USED" });

  const now = new Date();
  if (tokenRow.expiresAt < now) return reply.status(400).send({ error: "TOKEN_EXPIRED" });

  // Atomically consume the token (race-safe)
  const consume = await db.mobileProvisioningToken.updateMany({
    where: { id: tokenRow.id, usedAt: null, expiresAt: { gte: now } },
    data: { usedAt: now }
  });
  if (consume.count === 0) {
    const latest = await db.mobileProvisioningToken.findUnique({ where: { id: tokenRow.id } });
    if (latest?.usedAt) return reply.status(400).send({ error: "TOKEN_ALREADY_USED" });
    return reply.status(400).send({ error: "TOKEN_EXPIRED" });
  }

  // Load user from DB to build a proper JwtUser for provisioning
  const dbUser = await db.user.findUnique({ where: { id: verified.userId } });
  if (!dbUser || dbUser.tenantId !== verified.tenantId) {
    return reply.status(400).send({ error: "USER_NOT_FOUND" });
  }
  const jwtUser: JwtUser = { sub: dbUser.id, tenantId: dbUser.tenantId, email: dbUser.email, role: dbUser.role };

  // Issue SIP provisioning (resets SIP password on PBX, returns credentials)
  let out: { sipPassword: string; provisioning: any; pbxExtensionLinkId: string };
  try {
    out = await issueOneTimeProvisioningForUser(jwtUser);
  } catch (e: any) {
    const code = String(e?.message || "VOICE_PROVISIONING_FAILED");
    return reply.status(code === "EXTENSION_NOT_ASSIGNED" ? 404 : 400).send({ error: code });
  }

  // Sign a full mobile session token (same shape as /auth/login)
  const sessionToken = await reply.jwtSign({ sub: dbUser.id, tenantId: dbUser.tenantId, email: dbUser.email, role: dbUser.role });

  // Upsert MobileDevice if push token provided (device can also register later via /mobile/devices/register)
  let deviceId: string | null = null;
  if (input.deviceInfo?.expoPushToken && input.deviceInfo?.platform) {
    const device = await db.mobileDevice.upsert({
      where: { expoPushToken: input.deviceInfo.expoPushToken },
      create: {
        tenantId: dbUser.tenantId,
        userId: dbUser.id,
        platform: input.deviceInfo.platform,
        expoPushToken: input.deviceInfo.expoPushToken,
        voipPushToken: input.deviceInfo.voipPushToken ?? null,
        deviceName: input.deviceInfo.deviceName ?? null,
        lastSeenAt: now,
      },
      update: {
        userId: dbUser.id,
        tenantId: dbUser.tenantId,
        voipPushToken: input.deviceInfo.voipPushToken ?? undefined,
        deviceName: input.deviceInfo.deviceName ?? undefined,
        lastSeenAt: now,
      },
    });
    deviceId = device.id;
  }

  await audit({
    tenantId: dbUser.tenantId,
    actorUserId: dbUser.id,
    action: "MOBILE_QR_EXCHANGE",
    entityType: "MobileProvisioningToken",
    entityId: tokenRow.id,
  });

  return {
    sessionToken,
    sipPassword: out.sipPassword,
    provisioning: out.provisioning,
    deviceId,
    user: { id: dbUser.id, email: dbUser.email, role: dbUser.role },
  };
});

// TEMPORARY: short-lived SUPER_ADMIN JWT for read-only observation scripts (no DB / no user creation).
// Remove after PBX↔Connect observation. Gated by NODE_ENV=development or DEV_OBSERVE_TOKEN_SECRET.
app.post("/admin/dev/generate-observe-token", async (req, reply) => {
  if (!canIssueDevObserveJwt({ headers: req.headers as Record<string, unknown>, body: req.body })) {
    return reply.status(404).send({ error: "not_found" });
  }
  const input = z
    .object({
      expiresMinutes: z.number().int().min(5).max(120).optional(),
      secret: z.string().optional(),
    })
    .parse(req.body || {});
  const minutes = Math.min(120, Math.max(5, input.expiresMinutes ?? 90));
  const expiresInSeconds = minutes * 60;
  const token = await reply.jwtSign(
    {
      sub: "dev-observe-token",
      tenantId: "global",
      email: "observe@dev.internal",
      role: "SUPER_ADMIN",
    },
    { sign: { expiresIn: expiresInSeconds } },
  );
  return { token };
});

app.addHook("preHandler", async (req, reply) => {
  const path = req.url.split("?")[0];
  if (shouldSkipJwtVerification(path)) return;
  // Allow a JWT passed via `?token=` query param (used by <audio> / download <a>
  // tags where you can't set an Authorization header). Copy it to the header
  // BEFORE jwtVerify so the standard auth flow still runs.
  try {
    const hasAuthHeader = Boolean((req.headers as any).authorization);
    if (!hasAuthHeader) {
      const tokenParam = (req.query as Record<string, string | undefined>)?.token;
      if (tokenParam && typeof tokenParam === "string") {
        (req.headers as any).authorization = `Bearer ${tokenParam}`;
      }
    }
    const headerTenant = String((req.headers as any)["x-tenant-context"] || "").trim();
    if (!headerTenant) {
      const tenantContextParam = (req.query as Record<string, string | undefined>)?.tenantContext;
      if (tenantContextParam && typeof tenantContextParam === "string") {
        (req.headers as any)["x-tenant-context"] = tenantContextParam;
      }
    }
  } catch {
    /* ignore — jwtVerify below will handle missing/bad token */
  }
  try {
    await req.jwtVerify();
  } catch {
    return reply.status(401).send({ error: "unauthorized" });
  }
  // SUPER_ADMIN VitalPBX tenant context override.
  // When the frontend sends x-tenant-context: vpbx:{slug}, the backend bypasses the
  // tenantPbxLink lookup and scopes PBX API calls directly to that VitalPBX tenant.
  const user = req.user as JwtUser;
  if (user?.role === "SUPER_ADMIN") {
    const ctx = String((req.headers as any)["x-tenant-context"] || "").trim();
    if (ctx.startsWith("vpbx:")) {
      (req as any).pbxTenantOverride = ctx.slice(5); // e.g., "a_plus_center"
    }
  }
  const portalPermission = portalApiPermissionForPath(path);
  if (portalPermission && !(await hasEffectivePortalPermission(user, portalPermission))) {
    return reply.status(403).send({ error: "forbidden", permission: portalPermission });
  }
});

app.get("/me", async (req, reply) => {
  const user = getUser(req);
  const row = await db.user.findUnique({
    where: { id: user.sub },
    select: {
      role: true,
      firstName: true,
      lastName: true,
      displayName: true,
      email: true,
      status: true,
      lastLoginAt: true,
      avatarUrl: true,
      ownedExtensions: {
        where: { status: "ACTIVE" },
        orderBy: { createdAt: "asc" },
        take: 1,
        select: { id: true, extNumber: true, displayName: true, status: true },
      },
    } as any,
  }).catch(() => null);
  const effectiveRole = row?.role ?? user.role;
  let refreshedToken: string | undefined;
  if (row?.role && String(row.role) !== String(user.role)) {
    refreshedToken = await reply.jwtSign({
      sub: user.sub,
      tenantId: user.tenantId,
      email: user.email,
      role: row.role,
      name: displayNameForUser(row as any),
    });
  }
  const portalPermissionSet = await resolvePortalPermissionsWithCrmUserAccess(
    effectiveRole,
    user.sub,
    user.tenantId,
  );

  // Resolve tenant display name so the portal can build its tenant object for
  // regular (non-super-admin) users. Without this, AppProvider falls back to
  // "My Workspace" and downstream client-side filters that compare tenant name
  // (team directory, live calls) drop everything as non-matching.
  const tenantRow = user.tenantId
    ? await db.tenant.findUnique({ where: { id: user.tenantId }, select: { id: true, name: true } }).catch(() => null)
    : null;
  const extension = (row as any)?.ownedExtensions?.[0] || null;
  return {
    id: user.sub,
    tenantId: user.tenantId,
    tenantName: tenantRow?.name ?? null,
    email: user.email,
    role: effectiveRole,
    name: row ? displayNameForUser(row as any) : user.email,
    extension: extension
      ? {
          id: extension.id,
          number: extension.extNumber,
          displayName: extension.displayName,
          status: extension.status,
        }
      : null,
    status: (row as any)?.status || "ACTIVE",
    lastLoginAt: (row as any)?.lastLoginAt || null,
    avatarUrl: (row as any)?.avatarUrl ?? null,
    ...(refreshedToken ? { token: refreshedToken } : {}),
    ...(portalPermissionSet ? { portalPermissionSet } : {}),
  };
});

// ─── Logged-in user profile photo ────────────────────────────────────────────
function userAvatarRoot(): string {
  return process.env.USER_AVATAR_STORAGE_DIR || path.join(process.cwd(), "data", "user-avatars");
}

app.get("/me/avatar", async (req, reply) => {
  const authUser = await requirePermission(req, reply, () => true);
  if (!authUser) return;
  const row = await db.user.findUnique({ where: { id: authUser.sub }, select: { avatarStorageKey: true } as any }).catch(() => null);
  if (!(row as any)?.avatarStorageKey) return reply.code(404).send({ error: "not_found" });
  try {
    const filePath = path.join(userAvatarRoot(), (row as any).avatarStorageKey);
    const bytes = await fsp.readFile(filePath);
    const ext = path.extname(filePath).toLowerCase();
    reply.header("content-type", ext === ".png" ? "image/png" : ext === ".webp" ? "image/webp" : "image/jpeg");
    reply.header("cache-control", "private, max-age=3600");
    return reply.send(bytes);
  } catch {
    return reply.code(404).send({ error: "not_found" });
  }
});

app.post("/me/avatar", async (req, reply) => {
  const authUser = await requirePermission(req, reply, () => true);
  if (!authUser) return;
  if (!(req as any).isMultipart?.()) return reply.code(400).send({ error: "multipart_required" });
  const part = await (req as any).file();
  if (!part) return reply.code(400).send({ error: "file_required" });
  const mime = String(part.mimetype || "");
  if (!["image/jpeg", "image/png", "image/webp"].includes(mime))
    return reply.code(400).send({ error: "unsupported_image_type" });
  const chunks: Buffer[] = [];
  for await (const chunk of part.file) chunks.push(Buffer.from(chunk));
  const bytes = Buffer.concat(chunks);
  if (bytes.length > 2 * 1024 * 1024) return reply.code(413).send({ error: "file_too_large" });
  const ext = mime === "image/png" ? ".png" : mime === "image/webp" ? ".webp" : ".jpg";
  const sha = createHash("sha256").update(bytes).digest("hex").slice(0, 24);
  const storageKey = `${authUser.sub}-${sha}${ext}`;
  const filePath = path.join(userAvatarRoot(), storageKey);
  await fsp.mkdir(userAvatarRoot(), { recursive: true });
  await fsp.writeFile(filePath, bytes);
  const existing = await db.user.findUnique({ where: { id: authUser.sub }, select: { avatarStorageKey: true } as any }).catch(() => null);
  if ((existing as any)?.avatarStorageKey && (existing as any).avatarStorageKey !== storageKey) {
    await fsp.unlink(path.join(userAvatarRoot(), (existing as any).avatarStorageKey)).catch(() => {});
  }
  const avatarUrl = `/api/me/avatar?v=${sha}`;
  await (db.user as any).update({ where: { id: authUser.sub }, data: { avatarStorageKey: storageKey, avatarUrl } });
  return reply.send({ ok: true, avatarUrl });
});

app.delete("/me/avatar", async (req, reply) => {
  const authUser = await requirePermission(req, reply, () => true);
  if (!authUser) return;
  const row = await db.user.findUnique({ where: { id: authUser.sub }, select: { avatarStorageKey: true } as any }).catch(() => null);
  if ((row as any)?.avatarStorageKey) {
    await fsp.unlink(path.join(userAvatarRoot(), (row as any).avatarStorageKey)).catch(() => {});
  }
  await (db.user as any).update({ where: { id: authUser.sub }, data: { avatarStorageKey: null, avatarUrl: null } });
  return reply.send({ ok: true });
});

app.get("/admin/users", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const query = z.object({ tenantId: z.string().optional(), search: z.string().optional(), role: z.string().optional(), status: z.string().optional() }).parse(req.query || {});

  // Super admins can send tenantId="" or omit it entirely to view all customer tenants at once.
  const allTenants = admin.role === "SUPER_ADMIN" && (!query.tenantId || query.tenantId === "ALL" || query.tenantId === "");

  let tenantId: string | null = null;
  if (!allTenants) {
    const resolved = await resolveManagedTenant(admin, query.tenantId).catch((e) => {
      const err = String((e as Error).message || "TENANT_NOT_FOUND");
      reply.status(err === "TENANT_REQUIRED" ? 400 : 404).send({ error: err });
      return null;
    });
    if (reply.sent) return;
    tenantId = resolved as string;
  }

  const where: any = allTenants
    ? { tenant: { kind: "CUSTOMER" as any, isApproved: true } }
    : { tenantId };

  if (query.role && query.role !== "all") {
    const roleUpper = String(query.role).toUpperCase();
    if (roleUpper === "END_USER") {
      where.role = { in: ["USER", "EXTENSION_USER", "READ_ONLY"] };
    } else if (roleUpper === "TENANT_ADMIN") {
      where.role = { in: ["TENANT_ADMIN", "ADMIN", "MANAGER", "BILLING", "BILLING_ADMIN", "MESSAGING", "SUPPORT"] };
    } else if (roleUpper === "SUPER_ADMIN") {
      where.role = "SUPER_ADMIN";
    } else {
      where.role = query.role;
    }
  }
  if (query.status && query.status !== "all") where.status = query.status;
  const search = String(query.search || "").trim();
  if (search) {
    where.OR = [
      { email: { contains: search, mode: "insensitive" } },
      { firstName: { contains: search, mode: "insensitive" } },
      { lastName: { contains: search, mode: "insensitive" } },
      { displayName: { contains: search, mode: "insensitive" } },
      { phone: { contains: search, mode: "insensitive" } },
      { ownedExtensions: { some: { extNumber: { contains: search, mode: "insensitive" } } } },
    ];
  }
  const [users, tenants] = await Promise.all([
    db.user.findMany({
      where,
    orderBy: { createdAt: "desc" },
      include: {
        tenant: { select: { id: true, name: true } },
        ownedExtensions: { take: 1, select: { id: true, extNumber: true, displayName: true, status: true, pbxUserEmail: true } },
        passwordTokens: { where: { type: "INVITE" as any, usedAt: null }, orderBy: { createdAt: "desc" }, take: 1 },
      } as any,
      take: 500,
    }),
    admin.role === "SUPER_ADMIN"
      ? db.tenant.findMany({
          where: {
            kind: "CUSTOMER" as any,
            isApproved: true,
            // Hard blocklist: strip any smoke / lab / admin-timestamped tenant
            // names that may have been mis-flagged as CUSTOMER+approved.
            NOT: [
              { name: { contains: "smoke", mode: "insensitive" } },
              { name: { contains: "dbg ", mode: "insensitive" } },
              { name: { contains: "vpbx ", mode: "insensitive" } },
              { name: { contains: "verify tenant", mode: "insensitive" } },
              { name: { contains: "admin tenant", mode: "insensitive" } },
              { name: { startsWith: "Tenant ", mode: "insensitive" } },
              { name: { startsWith: "Connect Admin ", mode: "insensitive" } },
              { name: { contains: "X Tenant", mode: "insensitive" } },
            ],
          },
          orderBy: { name: "asc" },
          select: { id: true, name: true, isApproved: true },
        })
      : db.tenant.findMany({ where: { id: admin.tenantId }, select: { id: true, name: true, isApproved: true } }),
  ]);
  // Only load extensions for single-tenant view (not useful in all-tenants mode)
  const extensions = allTenants ? [] : await db.extension.findMany({
    where: { tenantId: tenantId!, status: { not: "DELETED" } },
    orderBy: { extNumber: "asc" },
    select: { id: true, extNumber: true, displayName: true, pbxUserEmail: true, ownerUserId: true, status: true },
    take: 1000,
  });
  // Batched custom-role assignments (additive on top of platform role). Stored
  // under the assigning admin's tenant, so we filter by userId only — matching
  // getEffectiveCustomRolePermissions, which is tenant-agnostic by design.
  const userIds = users.map((u: any) => u.id);
  const customRoleRows = userIds.length
    ? await db.userCustomRole.findMany({
        where: { userId: { in: userIds }, customRole: { active: true } },
        select: { userId: true, customRole: { select: { id: true, name: true } } },
      })
    : [];
  const customRolesByUser = new Map<string, Array<{ id: string; name: string }>>();
  for (const r of customRoleRows as any[]) {
    if (!r.customRole) continue;
    const list = customRolesByUser.get(r.userId) ?? [];
    list.push({ id: r.customRole.id, name: r.customRole.name });
    customRolesByUser.set(r.userId, list);
  }
  return {
    users: users.map((u: any) => formatAdminUser({ ...u, __customRoles: customRolesByUser.get(u.id) ?? [] })),
    tenants: tenants.map((t) => ({ id: t.id, name: t.name, status: t.isApproved === false ? "SUSPENDED" : "ACTIVE" })),
    extensions,
    roles: USER_MANAGEMENT_ROLES,
    tenantId: allTenants ? "ALL" : tenantId,
  };
});

app.get("/admin/users/extension-prefill", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const query = z.object({ tenantId: z.string().optional(), extensionId: z.string().min(1) }).parse(req.query || {});
  const tenantId = await resolveManagedTenant(admin, query.tenantId).catch(() => null);
  if (!tenantId) return reply.status(404).send({ error: "tenant_not_found" });
  const extension = await db.extension.findFirst({
    where: { id: query.extensionId, tenantId },
    include: { ownerUser: { select: { id: true, email: true, displayName: true, status: true } } },
  } as any) as any;
  if (!extension) return reply.status(404).send({ error: "extension_not_found" });
  const parts = String(extension.displayName || "").trim().split(/\s+/).filter(Boolean);
  return {
    extension: { id: extension.id, tenantId: extension.tenantId, extNumber: extension.extNumber, displayName: extension.displayName, email: extension.pbxUserEmail || "", ownerUser: extension.ownerUser || null },
    prefill: { firstName: parts[0] || "", lastName: parts.length > 1 ? parts.slice(1).join(" ") : "", displayName: extension.displayName || "", email: extension.pbxUserEmail || "", phone: extension.extNumber || "", extensionNumber: extension.extNumber },
    warning: extension.ownerUserId ? "extension_already_assigned" : null,
  };
});

app.post("/admin/users", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  if (!checkBillingRateLimit(`user-create:${admin.sub}`, 30, 60 * 60 * 1000)) return reply.status(429).send({ error: "RATE_LIMITED" });
  const input = z.object({
    tenantId: z.string().optional(),
    extensionId: z.string().min(1),
    role: z.string().min(1),
    email: z.string().email(),
    firstName: z.string().min(1).max(80),
    lastName: z.string().min(1).max(80),
    displayName: z.string().max(160).optional(),
    phone: z.string().max(80).optional(),
    title: z.string().max(120).optional(),
    department: z.string().max(120).optional(),
    notes: z.string().max(2000).optional(),
    active: z.boolean().optional(),
    sendInvite: z.boolean().default(true),
  }).parse(req.body || {});
  const incomingRoleRaw = String(input.role || "").toUpperCase();
  const isPortalBucket = (PORTAL_ROLE_BUCKETS as readonly string[]).includes(incomingRoleRaw);
  if (isPortalBucket) {
    if (!canAssignPortalBucket(admin.role, incomingRoleRaw as PortalRoleBucket)) return reply.status(403).send({ error: "forbidden" });
  } else {
    if (!(USER_MANAGEMENT_ROLES as readonly string[]).includes(incomingRoleRaw)) return reply.status(400).send({ error: "invalid_role" });
    if (!canAssignRole(admin, incomingRoleRaw as UserManagementRole)) return reply.status(403).send({ error: "forbidden" });
  }
  const effectiveDbRole = isPortalBucket ? dbRoleFromPortalBucket(incomingRoleRaw as PortalRoleBucket) : incomingRoleRaw;
  const tenantId = await resolveManagedTenant(admin, input.tenantId).catch(() => null);
  if (!tenantId) return reply.status(404).send({ error: "tenant_not_found" });
  const extension = await db.extension.findFirst({ where: { id: input.extensionId, tenantId }, include: { tenant: { select: { name: true } }, pbxLink: true } as any }) as any;
  if (!extension) return reply.status(404).send({ error: "extension_not_found" });
  if (extension.ownerUserId) return reply.status(409).send({ error: "extension_already_assigned" });
  const email = normalizeEmail(input.email);
  const existing = await db.user.findUnique({ where: { email } });
  if (existing) return reply.status(409).send({ error: "email_already_exists" });
  const passwordHash = await bcrypt.hash(`invited:${randomBytes(24).toString("hex")}`, 10);
  const status = input.active === false ? "DISABLED" : input.sendInvite ? "INVITED" : "ACTIVE";
  const created = await db.$transaction(async (tx) => {
    const user = await tx.user.create({
      data: {
        tenantId,
        email,
        passwordHash,
        role: effectiveDbRole as any,
        status: status as any,
        firstName: input.firstName.trim(),
        lastName: input.lastName.trim(),
        displayName: input.displayName?.trim() || `${input.firstName.trim()} ${input.lastName.trim()}`.trim(),
        phone: input.phone?.trim() || null,
        title: input.title?.trim() || null,
        department: input.department?.trim() || null,
        notes: input.notes?.trim() || null,
        forcePasswordReset: input.sendInvite,
      } as any,
    });
    await tx.extension.update({ where: { id: extension.id }, data: { ownerUserId: user.id } });
    // Lazy auto-provisioning snapshot. If the PBX sync previously populated an
    // encrypted SIP password on the link, mark it PROVISIONED from PBX_EXISTING
    // so the portal softphone can register on first login. If not, stay PENDING
    // and let the admin click "Regenerate" explicitly (avoids surprise resets
    // that would log desk phones out).
    if (extension.pbxLink) {
      const hasPassword = !!extension.pbxLink.sipPasswordEncrypted;
      await tx.pbxExtensionLink.update({
        where: { id: extension.pbxLink.id },
        data: {
          provisionStatus: (hasPassword ? "PROVISIONED" : "PENDING") as any,
          provisionSource: (hasPassword ? "PBX_EXISTING" : null) as any,
          lastProvisionedAt: hasPassword ? new Date() : null,
        } as any,
      });
    }
    return user;
  });
  let inviteSent = false;
  if (input.sendInvite && status !== "DISABLED") {
    const { token } = await createUserPasswordToken({ userId: created.id, type: "INVITE", ttlMs: INVITE_TOKEN_HOURS * 60 * 60 * 1000, createdBy: admin.sub, ipAddress: req.ip, userAgent: String(req.headers["user-agent"] || "") });
    await queueUserWelcomeEmail({ user: created, tenantName: extension.tenant.name, extensionNumber: extension.extNumber, token });
    inviteSent = true;
  }
  await audit({
    tenantId,
    actorUserId: admin.sub,
    targetUserId: created.id,
    action: "USER_CREATED",
    entityType: "User",
    entityId: created.id,
    metadata: {
      role: effectiveDbRole,
      portalBucket: isPortalBucket ? incomingRoleRaw : undefined,
      extensionId: extension.id,
      pbxExtensionLinkId: extension.pbxLink?.id || null,
      provisioned: !!extension.pbxLink?.sipPasswordEncrypted,
      inviteSent,
    },
  });
  // Fire-and-forget PBX sync so SIP/WebRTC credentials are populated immediately
  // without delaying the user-creation response.
  setImmediate(async () => {
    try {
      const tpLink = await db.tenantPbxLink.findUnique({
        where: { tenantId },
        include: { pbxInstance: true },
      });
      if (!tpLink) return;
      const auth = decryptJson<{ token: string; secret?: string }>(tpLink.pbxInstance.apiAuthEncrypted);
      const vital = getVitalPbxClient({ baseUrl: tpLink.pbxInstance.baseUrl, token: auth.token, secret: auth.secret });
      const vitalTenantId = tpLink.pbxTenantId || undefined;
      await syncExtensionsFromPbx(db, tpLink.pbxInstanceId, vital, {
        ...(vitalTenantId ? { vitalTenantId } : {}),
      });
    } catch {
      // sync failure is non-fatal — admin can click "Re-sync credentials" in the user panel
    }
  });
  return { ok: true, user: formatAdminUser({ ...created, tenant: { id: tenantId, name: extension.tenant.name }, ownedExtensions: [extension], passwordTokens: [] }), inviteSent };
});

app.get("/admin/users/:id", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const row = await db.user.findFirst({
    where: admin.role === "SUPER_ADMIN" ? { id } : { id, tenantId: admin.tenantId },
    include: { tenant: { select: { id: true, name: true } }, ownedExtensions: { take: 1 }, passwordTokens: { orderBy: { createdAt: "desc" }, take: 10 } } as any,
  });
  if (!row) return reply.status(404).send({ error: "user_not_found" });
  return { user: formatAdminUser(row), tokens: (row as any).passwordTokens || [] };
});

const outboundRouteInputSchema = z.object({
  tenantId: z.string().optional(),
  name: z.string().trim().min(1).max(120),
  prefix: z.string().trim().max(8).optional().nullable(),
  callerIdName: z.string().trim().max(120).optional().nullable(),
  callerIdNumber: z.string().trim().max(40).optional().nullable(),
  description: z.string().trim().max(500).optional().nullable(),
  isActive: z.boolean().optional(),
  sortOrder: z.number().int().min(0).max(100000).optional(),
});

const outboundRoutePatchSchema = outboundRouteInputSchema.partial().extend({
  tenantId: z.string().optional(),
});

const outboundRouteAssignmentSchema = z.object({
  routes: z.array(z.object({
    outboundRouteId: z.string().min(1),
    enabled: z.boolean().optional(),
    isDefault: z.boolean().optional(),
  })).max(100),
});

const outboundRouteDialResolveSchema = z.object({
  number: z.string().trim().min(1).max(80),
  outboundRouteId: z.string().trim().min(1).optional().nullable(),
});

function cleanOutboundPrefix(value: string | null | undefined): string | null {
  const prefix = String(value ?? "").trim();
  if (!prefix) return null;
  if (!/^\d{1,8}$/.test(prefix)) throw new Error("invalid_prefix");
  return prefix;
}

function cleanOptionalText(value: string | null | undefined): string | null {
  const text = String(value ?? "").trim();
  return text || null;
}

function cleanCallerIdNumber(value: string | null | undefined): string | null {
  const text = cleanOptionalText(value);
  if (!text) return null;
  if (!/^[+()\-\s.\d]{3,40}$/.test(text)) throw new Error("invalid_caller_id_number");
  return text;
}

function formatOutboundRoute(row: any, permission?: any) {
  const prefix = row.prefix || "";
  return {
    id: row.id,
    tenantId: row.tenantId,
    name: row.name,
    prefix,
    callerIdName: row.callerIdName || null,
    callerIdNumber: row.callerIdNumber || null,
    description: row.description || null,
    isActive: row.isActive !== false,
    sortOrder: row.sortOrder || 0,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    enabled: permission ? permission.enabled !== false : false,
    isDefault: permission ? permission.isDefault === true : false,
    label: prefix ? `${row.name} · ${prefix}` : `${row.name} · No prefix`,
  };
}

function formatPublicOutboundRoute(row: any, permission?: any) {
  return {
    id: row.id,
    name: row.name,
    callerIdName: row.callerIdName || null,
    callerIdNumber: row.callerIdNumber || null,
    isDefault: permission ? permission.isDefault === true : false,
    label: row.name,
  };
}

function normalizeOutboundDialTarget(value: string): string {
  const trimmed = String(value || "").trim();
  if (trimmed.includes("@")) return trimmed;
  return trimmed.replace(/[()\-\s.]/g, "");
}

function isEmergencyOutboundDialTarget(value: string): boolean {
  const digits = value.replace(/\D/g, "");
  return digits === "911" || digits === "9911";
}

function applyInternalOutboundPrefix(number: string, prefix: string | null | undefined): { finalNumber: string; prefixApplied: boolean } {
  const normalized = normalizeOutboundDialTarget(number);
  const routePrefix = String(prefix || "").trim();
  if (!routePrefix || !/^\d{1,8}$/.test(routePrefix)) return { finalNumber: normalized, prefixApplied: false };
  if (!normalized || normalized.includes("@") || normalized.startsWith("*") || normalized.startsWith("#")) return { finalNumber: normalized, prefixApplied: false };
  if (isEmergencyOutboundDialTarget(normalized)) return { finalNumber: normalized, prefixApplied: false };
  if (normalized.startsWith(routePrefix)) return { finalNumber: normalized, prefixApplied: false };
  return { finalNumber: `${routePrefix}${normalized}`, prefixApplied: true };
}

async function resolveAdminTargetUser(admin: JwtUser, userId: string): Promise<any | null> {
  return (db as any).user.findFirst({
    where: admin.role === "SUPER_ADMIN" ? { id: userId } : { id: userId, tenantId: admin.tenantId },
    select: { id: true, tenantId: true, email: true, role: true },
  });
}

app.get("/outbound-routes", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const query = z.object({ tenantId: z.string().optional() }).parse(req.query || {});
  const tenantId = await resolveManagedTenant(admin, query.tenantId).catch((e) => {
    const err = String((e as Error).message || "TENANT_NOT_FOUND");
    reply.status(err === "TENANT_REQUIRED" ? 400 : 404).send({ error: err });
    return null;
  });
  if (!tenantId || reply.sent) return;
  const routes = await (db as any).outboundRoute.findMany({
    where: { tenantId },
    orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
  });
  return { tenantId, routes: routes.map((r: any) => formatOutboundRoute(r)) };
});

app.post("/outbound-routes", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const input = outboundRouteInputSchema.parse(req.body || {});
  const tenantId = await resolveManagedTenant(admin, input.tenantId).catch((e) => {
    const err = String((e as Error).message || "TENANT_NOT_FOUND");
    reply.status(err === "TENANT_REQUIRED" ? 400 : 404).send({ error: err });
    return null;
  });
  if (!tenantId || reply.sent) return;
  let prefix: string | null;
  let callerIdNumber: string | null;
  try {
    prefix = cleanOutboundPrefix(input.prefix);
    callerIdNumber = cleanCallerIdNumber(input.callerIdNumber);
  } catch (e) {
    return reply.status(400).send({ error: String((e as Error).message || "invalid_outbound_route") });
  }
  const created = await (db as any).outboundRoute.create({
    data: {
      tenantId,
      name: input.name.trim(),
      prefix,
      callerIdName: cleanOptionalText(input.callerIdName),
      callerIdNumber,
      description: cleanOptionalText(input.description),
      isActive: input.isActive !== false,
      sortOrder: input.sortOrder ?? 0,
    },
  });
  await audit({
    tenantId,
    actorUserId: admin.sub,
    action: "OUTBOUND_ROUTE_CREATED",
    entityType: "OutboundRoute",
    entityId: created.id,
    metadata: { name: created.name, prefix: created.prefix || "" },
  });
  return { ok: true, route: formatOutboundRoute(created) };
});

app.patch("/outbound-routes/:id", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const input = outboundRoutePatchSchema.parse(req.body || {});
  const tenantId = await resolveManagedTenant(admin, input.tenantId).catch((e) => {
    const err = String((e as Error).message || "TENANT_NOT_FOUND");
    reply.status(err === "TENANT_REQUIRED" ? 400 : 404).send({ error: err });
    return null;
  });
  if (!tenantId || reply.sent) return;
  const current = await (db as any).outboundRoute.findFirst({ where: { id, tenantId } });
  if (!current) return reply.status(404).send({ error: "outbound_route_not_found" });
  const data: Record<string, unknown> = {};
  try {
    if (input.name !== undefined) data.name = input.name.trim();
    if (input.prefix !== undefined) data.prefix = cleanOutboundPrefix(input.prefix);
    if (input.callerIdName !== undefined) data.callerIdName = cleanOptionalText(input.callerIdName);
    if (input.callerIdNumber !== undefined) data.callerIdNumber = cleanCallerIdNumber(input.callerIdNumber);
    if (input.description !== undefined) data.description = cleanOptionalText(input.description);
  } catch (e) {
    return reply.status(400).send({ error: String((e as Error).message || "invalid_outbound_route") });
  }
  if (input.isActive !== undefined) data.isActive = input.isActive;
  if (input.sortOrder !== undefined) data.sortOrder = input.sortOrder;
  const updated = await (db as any).outboundRoute.update({ where: { id }, data });
  if (updated.isActive === false) {
    await (db as any).userOutboundRoutePermission.updateMany({
      where: { tenantId, outboundRouteId: id, isDefault: true },
      data: { isDefault: false },
    });
  }
  await audit({
    tenantId,
    actorUserId: admin.sub,
    action: "OUTBOUND_ROUTE_UPDATED",
    entityType: "OutboundRoute",
    entityId: updated.id,
    metadata: { fields: Object.keys(data), name: updated.name, prefix: updated.prefix || "" },
  });
  return { ok: true, route: formatOutboundRoute(updated) };
});

app.delete("/outbound-routes/:id", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const query = z.object({ tenantId: z.string().optional() }).parse(req.query || {});
  const tenantId = await resolveManagedTenant(admin, query.tenantId).catch((e) => {
    const err = String((e as Error).message || "TENANT_NOT_FOUND");
    reply.status(err === "TENANT_REQUIRED" ? 400 : 404).send({ error: err });
    return null;
  });
  if (!tenantId || reply.sent) return;
  const current = await (db as any).outboundRoute.findFirst({ where: { id, tenantId } });
  if (!current) return reply.status(404).send({ error: "outbound_route_not_found" });
  const permissionCount = await (db as any).userOutboundRoutePermission.count({ where: { tenantId, outboundRouteId: id } });
  if (permissionCount > 0) {
    const updated = await (db as any).outboundRoute.update({ where: { id }, data: { isActive: false } });
    await (db as any).userOutboundRoutePermission.updateMany({ where: { tenantId, outboundRouteId: id }, data: { enabled: false, isDefault: false } });
    await audit({ tenantId, actorUserId: admin.sub, action: "OUTBOUND_ROUTE_ARCHIVED", entityType: "OutboundRoute", entityId: id, metadata: { name: current.name, assignedUsers: permissionCount } });
    return { ok: true, archived: true, route: formatOutboundRoute(updated) };
  }
  await (db as any).outboundRoute.delete({ where: { id } });
  await audit({ tenantId, actorUserId: admin.sub, action: "OUTBOUND_ROUTE_DELETED", entityType: "OutboundRoute", entityId: id, metadata: { name: current.name } });
  return { ok: true, deleted: true };
});

app.get("/me/outbound-routes", async (req) => {
  const user = getUser(req);
  const rows = await (db as any).userOutboundRoutePermission.findMany({
    where: {
      tenantId: user.tenantId,
      userId: user.sub,
      enabled: true,
      outboundRoute: { isActive: true, tenantId: user.tenantId },
    },
    include: { outboundRoute: true },
    orderBy: [{ isDefault: "desc" }],
  });
  rows.sort((a: any, b: any) => {
    if (a.isDefault !== b.isDefault) return a.isDefault ? -1 : 1;
    const sortDelta = (a.outboundRoute?.sortOrder || 0) - (b.outboundRoute?.sortOrder || 0);
    if (sortDelta) return sortDelta;
    return String(a.outboundRoute?.name || "").localeCompare(String(b.outboundRoute?.name || ""));
  });
  return {
    tenantId: user.tenantId,
    routes: rows.map((p: any) => formatPublicOutboundRoute(p.outboundRoute, p)),
  };
});

app.post("/me/outbound-routes/resolve-dial", async (req, reply) => {
  const user = getUser(req);
  const input = outboundRouteDialResolveSchema.parse(req.body || {});
  const originalNumber = input.number.trim();
  const normalizedNumber = normalizeOutboundDialTarget(originalNumber);
  if (!normalizedNumber) return reply.status(400).send({ error: "invalid_number" });

  if (!input.outboundRouteId) {
    return {
      originalNumber,
      normalizedNumber,
      finalNumber: normalizedNumber,
      outboundRouteId: null,
      outboundRouteName: null,
      prefixApplied: false,
    };
  }

  const permission = await (db as any).userOutboundRoutePermission.findFirst({
    where: {
      tenantId: user.tenantId,
      userId: user.sub,
      outboundRouteId: input.outboundRouteId,
      enabled: true,
      outboundRoute: { tenantId: user.tenantId, isActive: true },
    },
    include: { outboundRoute: true },
  });
  if (!permission?.outboundRoute) {
    await audit({
      tenantId: user.tenantId,
      actorUserId: user.sub,
      action: "OUTBOUND_ROUTE_DIAL_DENIED",
      entityType: "OutboundRoute",
      entityId: input.outboundRouteId,
      metadata: { originalNumber, reason: "route_not_allowed" },
    });
    return reply.status(403).send({ error: "outbound_route_not_allowed" });
  }

  const resolved = applyInternalOutboundPrefix(normalizedNumber, permission.outboundRoute.prefix);
  await audit({
    tenantId: user.tenantId,
    actorUserId: user.sub,
    action: "OUTBOUND_ROUTE_DIAL_RESOLVED",
    entityType: "OutboundRoute",
    entityId: permission.outboundRoute.id,
    metadata: {
      routeName: permission.outboundRoute.name,
      originalNumber,
      normalizedNumber,
      finalNumber: resolved.finalNumber,
      prefixApplied: resolved.prefixApplied,
      emergencyBypass: isEmergencyOutboundDialTarget(normalizedNumber),
    },
  });
  return {
    originalNumber,
    normalizedNumber,
    finalNumber: resolved.finalNumber,
    outboundRouteId: permission.outboundRoute.id,
    outboundRouteName: permission.outboundRoute.name,
    prefixApplied: resolved.prefixApplied,
  };
});

app.get("/admin/users/:id/outbound-routes", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const target = await resolveAdminTargetUser(admin, id);
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  const [routes, permissions] = await Promise.all([
    (db as any).outboundRoute.findMany({
      where: { tenantId: target.tenantId },
      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
    }),
    (db as any).userOutboundRoutePermission.findMany({
      where: { tenantId: target.tenantId, userId: target.id },
    }),
  ]);
  const byRoute = new Map<string, any>(permissions.map((p: any) => [p.outboundRouteId, p]));
  return {
    tenantId: target.tenantId,
    userId: target.id,
    routes: routes.map((r: any) => formatOutboundRoute(r, byRoute.get(r.id))),
  };
});

app.put("/admin/users/:id/outbound-routes", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const input = outboundRouteAssignmentSchema.parse(req.body || {});
  const target = await resolveAdminTargetUser(admin, id);
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  const enabled = input.routes.filter((r) => r.enabled !== false);
  const routeIds = Array.from(new Set(enabled.map((r) => r.outboundRouteId)));
  const validRoutes = routeIds.length
    ? await (db as any).outboundRoute.findMany({ where: { id: { in: routeIds }, tenantId: target.tenantId, isActive: true }, select: { id: true } })
    : [];
  const validIds = new Set(validRoutes.map((r: any) => r.id));
  const invalidIds = routeIds.filter((routeId) => !validIds.has(routeId));
  if (invalidIds.length) return reply.status(400).send({ error: "invalid_outbound_route", routeIds: invalidIds });
  const requestedDefault = enabled.find((r) => r.isDefault === true)?.outboundRouteId || null;
  const defaultRouteId = requestedDefault && validIds.has(requestedDefault) ? requestedDefault : null;
  await (db as any).$transaction(async (tx: any) => {
    await tx.userOutboundRoutePermission.deleteMany({ where: { tenantId: target.tenantId, userId: target.id } });
    if (routeIds.length) {
      await tx.userOutboundRoutePermission.createMany({
        data: routeIds.map((routeId) => ({
          tenantId: target.tenantId,
          userId: target.id,
          outboundRouteId: routeId,
          enabled: true,
          isDefault: routeId === defaultRouteId,
        })),
      });
    }
  });
  await audit({
    tenantId: target.tenantId,
    actorUserId: admin.sub,
    targetUserId: target.id,
    action: "USER_OUTBOUND_ROUTES_UPDATED",
    entityType: "User",
    entityId: target.id,
    metadata: { routeIds, defaultRouteId },
  });
  return { ok: true, userId: target.id, tenantId: target.tenantId, routeIds, defaultRouteId };
});

// ═════════════════════════════════════════════════════════════════════════════
// Multi-tenant SIP accounts per user ("second phone line" in the dialer).
//
// A UserSipAccount row links a Connect user to an EXTRA extension — possibly in
// a different tenant — on top of the primary extension (Extension.ownerUserId,
// untouched). The portal WebRTC phone registers each ready account as its own
// SIP registration; the dialer dropdown mixes outbound-route prefixes and SIP
// accounts. Everything here is additive: users without accounts see no change.
// ═════════════════════════════════════════════════════════════════════════════

const MAX_SIP_ACCOUNTS_PER_USER = 5; // primary extension + up to 4 extra lines

function formatUserSipAccount(row: any) {
  const link = row.extension?.pbxLink || null;
  return {
    id: row.id,
    userId: row.userId,
    tenantId: row.tenantId,
    tenantName: row.tenant?.name || null,
    extensionId: row.extensionId,
    extNumber: row.extension?.extNumber || null,
    displayName: row.extension?.displayName || null,
    label: row.label || row.tenant?.name || null,
    sortOrder: row.sortOrder || 0,
    webrtcEnabled: !!link?.webrtcEnabled,
    hasSipPassword: !!link?.sipPasswordEncrypted,
    provisionStatus: link ? (link.provisionStatus || "PENDING") : "NOT_LINKED",
    endpointName: link?.pbxDeviceName || link?.pbxSipUsername || null,
    createdAt: row.createdAt,
  };
}

const userSipAccountInclude = {
  tenant: { select: { id: true, name: true } },
  extension: { include: { pbxLink: true } },
} as const;

async function loadUserSipAccount(userId: string, accountId: string): Promise<any | null> {
  return (db as any).userSipAccount.findFirst({
    where: { id: accountId, userId },
    include: userSipAccountInclude,
  });
}

// GET /admin/users/:id/sip-accounts — list a user's extra SIP accounts.
app.get("/admin/users/:id/sip-accounts", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const target = await resolveAdminTargetUser(admin, id);
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  const rows = await (db as any).userSipAccount.findMany({
    where: { userId: target.id },
    include: userSipAccountInclude,
    orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }],
  });
  return { userId: target.id, accounts: rows.map((r: any) => formatUserSipAccount(r)) };
});

// GET /admin/users/sip-accounts-summary?userIds=a,b,c — batch fetch for the
// Users table so it can show extra-account rows without N+1 requests.
app.get("/admin/users/sip-accounts-summary", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const query = z.object({ userIds: z.string().min(1).max(4000) }).parse(req.query || {});
  const ids = Array.from(new Set(query.userIds.split(",").map((s) => s.trim()).filter(Boolean))).slice(0, 200);
  if (!ids.length) return { accountsByUser: {} };
  const userWhere: Record<string, unknown> =
    admin.role === "SUPER_ADMIN" ? { id: { in: ids } } : { id: { in: ids }, tenantId: admin.tenantId };
  const visibleUsers = await db.user.findMany({ where: userWhere as any, select: { id: true } });
  const visibleIds = visibleUsers.map((u: { id: string }) => u.id);
  if (!visibleIds.length) return { accountsByUser: {} };
  const rows = await (db as any).userSipAccount.findMany({
    where: { userId: { in: visibleIds } },
    include: userSipAccountInclude,
    orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }],
  });
  const accountsByUser: Record<string, unknown[]> = {};
  for (const row of rows) {
    (accountsByUser[row.userId] ||= []).push(formatUserSipAccount(row));
  }
  return { accountsByUser };
});

// POST /admin/users/:id/sip-accounts — attach an extension (from any tenant the
// admin can manage) to this user as an extra SIP account.
app.post("/admin/users/:id/sip-accounts", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const input = z
    .object({
      tenantId: z.string().trim().min(1),
      extensionId: z.string().trim().min(1),
      label: z.string().trim().max(80).optional().nullable(),
    })
    .parse(req.body || {});
  const target = await resolveAdminTargetUser(admin, id);
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  // Tenant admins may only attach extensions from their own tenant; only
  // SUPER_ADMIN can link across tenants.
  if (admin.role !== "SUPER_ADMIN" && input.tenantId !== admin.tenantId) {
    return reply.status(403).send({ error: "cross_tenant_not_allowed" });
  }
  const tenant = await db.tenant.findUnique({ where: { id: input.tenantId }, select: { id: true, name: true } });
  if (!tenant) return reply.status(404).send({ error: "tenant_not_found" });
  const tenantLink = await db.tenantPbxLink.findUnique({ where: { tenantId: tenant.id } });
  if (!tenantLink) return reply.status(400).send({ error: "PBX_NOT_LINKED", message: `Tenant ${tenant.name} is not linked to the PBX.` });
  const ext = await db.extension.findFirst({
    where: { id: input.extensionId, tenantId: tenant.id, status: "ACTIVE" },
    include: { pbxLink: true } as any,
  });
  if (!ext) return reply.status(404).send({ error: "extension_not_found" });
  if (ext.ownerUserId === target.id) {
    return reply.status(400).send({ error: "extension_is_primary", message: "This extension is already the user's primary extension." });
  }
  const existingCount = await (db as any).userSipAccount.count({ where: { userId: target.id } });
  if (existingCount >= MAX_SIP_ACCOUNTS_PER_USER - 1) {
    return reply.status(400).send({
      error: "sip_account_limit_reached",
      message: `A user can have at most ${MAX_SIP_ACCOUNTS_PER_USER} SIP accounts (primary extension + ${MAX_SIP_ACCOUNTS_PER_USER - 1} extra).`,
    });
  }
  const dupe = await (db as any).userSipAccount.findFirst({ where: { userId: target.id, extensionId: ext.id } });
  if (dupe) return reply.status(409).send({ error: "sip_account_already_linked" });
  const created = await (db as any).userSipAccount.create({
    data: {
      userId: target.id,
      tenantId: tenant.id,
      extensionId: ext.id,
      label: (input.label || "").trim() || null,
      sortOrder: existingCount,
    },
    include: userSipAccountInclude,
  });
  await audit({
    tenantId: target.tenantId,
    actorUserId: admin.sub,
    targetUserId: target.id,
    action: "USER_SIP_ACCOUNT_ADDED",
    entityType: "UserSipAccount",
    entityId: created.id,
    metadata: { accountTenantId: tenant.id, accountTenantName: tenant.name, extensionId: ext.id, extNumber: ext.extNumber },
  });
  return { ok: true, account: formatUserSipAccount(created) };
});

// DELETE /admin/users/:id/sip-accounts/:accountId — detach an extra SIP account.
app.delete("/admin/users/:id/sip-accounts/:accountId", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id, accountId } = req.params as { id: string; accountId: string };
  const target = await resolveAdminTargetUser(admin, id);
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  const account = await loadUserSipAccount(target.id, accountId);
  if (!account) return reply.status(404).send({ error: "sip_account_not_found" });
  await (db as any).userSipAccount.delete({ where: { id: account.id } });
  // Clean up this user's outbound-route permissions in the account's tenant —
  // but NEVER when that tenant is the user's own tenant (those belong to the
  // primary extension) and only when no other extra account still uses it.
  if (account.tenantId !== target.tenantId) {
    const stillLinked = await (db as any).userSipAccount.count({
      where: { userId: target.id, tenantId: account.tenantId },
    });
    if (stillLinked === 0) {
      await (db as any).userOutboundRoutePermission.deleteMany({
        where: { userId: target.id, tenantId: account.tenantId },
      });
    }
  }
  await audit({
    tenantId: target.tenantId,
    actorUserId: admin.sub,
    targetUserId: target.id,
    action: "USER_SIP_ACCOUNT_REMOVED",
    entityType: "UserSipAccount",
    entityId: account.id,
    metadata: { accountTenantId: account.tenantId, extensionId: account.extensionId },
  });
  return { ok: true, removed: true };
});

// POST /admin/users/:id/sip-accounts/:accountId/sync — re-run the PBX sync for
// the ACCOUNT's tenant and report truthful provisioning state for that
// extension (same semantics as /admin/users/:id/phone/sync, scoped to the
// extra account instead of the primary extension).
app.post("/admin/users/:id/sip-accounts/:accountId/sync", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id, accountId } = req.params as { id: string; accountId: string };
  const target = await resolveAdminTargetUser(admin, id);
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  const account = await loadUserSipAccount(target.id, accountId);
  if (!account) return reply.status(404).send({ error: "sip_account_not_found" });

  const tenantLink = await db.tenantPbxLink.findUnique({
    where: { tenantId: account.tenantId },
    include: { pbxInstance: true },
  });
  if (!tenantLink) return reply.status(400).send({ error: "PBX_NOT_LINKED" });

  try {
    const auth = decryptJson<{ token: string; secret?: string }>(tenantLink.pbxInstance.apiAuthEncrypted);
    const vital = getVitalPbxClient({ baseUrl: tenantLink.pbxInstance.baseUrl, token: auth.token, secret: auth.secret, timeoutMs: 45000 });
    await syncExtensionsFromPbx(db, tenantLink.pbxInstanceId, vital, {
      ...(tenantLink.pbxTenantId ? { vitalTenantId: tenantLink.pbxTenantId } : {}),
    });
  } catch (err: any) {
    await audit({
      tenantId: target.tenantId,
      actorUserId: admin.sub,
      targetUserId: target.id,
      action: "USER_SIP_ACCOUNT_SYNC_FAILED",
      entityType: "UserSipAccount",
      entityId: account.id,
      metadata: { error: String(err?.message || err) },
    });
    return reply.status(502).send({ error: "pbx_sync_failed", message: String(err?.message || err) });
  }

  // The extension may only have gained its pbxLink during the sync above.
  let linkRow = await db.pbxExtensionLink.findFirst({ where: { extensionId: account.extensionId } });
  if (!linkRow) {
    return reply.status(409).send({
      error: "extension_not_linked_to_pbx",
      message: `Extension ${account.extension?.extNumber || ""} exists in Connect but has no PBX link even after sync. Check that it exists on the PBX for this tenant.`,
    });
  }

  let hasPassword = !!(linkRow as any).sipPasswordEncrypted;
  let webrtcEnabled = !!linkRow.webrtcEnabled;
  let createdWebrtcDevice = false;
  if (!webrtcEnabled || !hasPassword) {
    // Best-effort WebRTC device creation, mirroring the primary phone/sync path.
    try {
      const wireAuth = decryptJson<{ token: string; secret?: string }>(tenantLink.pbxInstance.apiAuthEncrypted);
      const out = await getWirePbxClient({
        baseUrl: tenantLink.pbxInstance.baseUrl,
        token: wireAuth.token,
        secret: wireAuth.secret,
        timeoutMs: 45000,
      }).createSipDevice({ pbxExtensionId: linkRow.pbxExtensionId, enableWebrtc: true });
      if (out?.sipPassword) {
        linkRow = await db.pbxExtensionLink.update({
          where: { id: linkRow.id },
          data: {
            pbxDeviceId: (out as any).pbxDeviceId || (linkRow as any).pbxDeviceId || null,
            pbxSipUsername: (out as any).sipUsername || linkRow.pbxSipUsername,
            pbxDeviceName: (out as any).sipUsername || (linkRow as any).pbxDeviceName || null,
            sipPasswordEncrypted: encryptJson(out.sipPassword),
            sipPasswordIssuedAt: new Date(),
            webrtcEnabled: true,
            provisionStatus: "PROVISIONED" as any,
            provisionSource: "PBX_GENERATED" as any,
            lastProvisionedAt: new Date(),
          } as any,
        });
        hasPassword = true;
        webrtcEnabled = true;
        createdWebrtcDevice = true;
      }
    } catch {
      // VitalPBX 4 may not expose device creation — fall through to the
      // truthful 409 below with manual instructions.
    }
  }

  const ready = webrtcEnabled && hasPassword;
  await db.pbxExtensionLink.update({
    where: { id: linkRow.id },
    data: {
      provisionStatus: (ready ? "PROVISIONED" : "PENDING") as any,
      provisionSource: (ready ? ((linkRow as any).provisionSource || "PBX_EXISTING") : null) as any,
      lastProvisionedAt: new Date(),
    } as any,
  });

  if (!ready) {
    const extLabel = account.extension?.extNumber || "this extension";
    const reason = !webrtcEnabled ? "NO_WEBRTC_DEVICE_ON_PBX" : "SIP_CREDENTIAL_NOT_SET";
    const message = !webrtcEnabled
      ? `VitalPBX extension ${extLabel} has no WebRTC device. Add a "_1" device with WebRTC Client enabled in VitalPBX, Apply Changes, then click Sync SIP again.`
      : `VitalPBX extension ${extLabel} has a WebRTC device but no SIP secret was returned. Regenerate its password in VitalPBX, Apply Changes, then click Sync SIP again.`;
    await audit({
      tenantId: target.tenantId,
      actorUserId: admin.sub,
      targetUserId: target.id,
      action: "USER_SIP_ACCOUNT_SYNC_NO_WEBRTC",
      entityType: "UserSipAccount",
      entityId: account.id,
      metadata: { webrtcEnabled, hasPassword },
    });
    return reply.status(409).send({ error: reason, message, provisionStatus: "PENDING", webrtcEnabled, hasSipPassword: hasPassword });
  }

  await audit({
    tenantId: target.tenantId,
    actorUserId: admin.sub,
    targetUserId: target.id,
    action: "USER_SIP_ACCOUNT_SYNC_OK",
    entityType: "UserSipAccount",
    entityId: account.id,
    metadata: { createdWebrtcDevice },
  });
  return {
    ok: true,
    provisionStatus: "PROVISIONED",
    hasSipPassword: true,
    webrtcEnabled: true,
    createdWebrtcDevice,
    endpointName: (linkRow as any).pbxDeviceName || linkRow.pbxSipUsername || null,
  };
});

// GET /admin/users/:id/sip-accounts/:accountId/outbound-routes — outbound-route
// assignment for the ACCOUNT's tenant (same shape as the primary endpoint).
app.get("/admin/users/:id/sip-accounts/:accountId/outbound-routes", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id, accountId } = req.params as { id: string; accountId: string };
  const target = await resolveAdminTargetUser(admin, id);
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  const account = await loadUserSipAccount(target.id, accountId);
  if (!account) return reply.status(404).send({ error: "sip_account_not_found" });
  const [routes, permissions] = await Promise.all([
    (db as any).outboundRoute.findMany({
      where: { tenantId: account.tenantId },
      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
    }),
    (db as any).userOutboundRoutePermission.findMany({
      where: { tenantId: account.tenantId, userId: target.id },
    }),
  ]);
  const byRoute = new Map<string, any>(permissions.map((p: any) => [p.outboundRouteId, p]));
  return {
    tenantId: account.tenantId,
    userId: target.id,
    accountId: account.id,
    routes: routes.map((r: any) => formatOutboundRoute(r, byRoute.get(r.id))),
  };
});

// PUT /admin/users/:id/sip-accounts/:accountId/outbound-routes — replace this
// user's route permissions WITHIN the account's tenant only.
app.put("/admin/users/:id/sip-accounts/:accountId/outbound-routes", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id, accountId } = req.params as { id: string; accountId: string };
  const input = outboundRouteAssignmentSchema.parse(req.body || {});
  const target = await resolveAdminTargetUser(admin, id);
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  const account = await loadUserSipAccount(target.id, accountId);
  if (!account) return reply.status(404).send({ error: "sip_account_not_found" });
  const enabled = input.routes.filter((r) => r.enabled !== false);
  const routeIds = Array.from(new Set(enabled.map((r) => r.outboundRouteId)));
  const validRoutes = routeIds.length
    ? await (db as any).outboundRoute.findMany({ where: { id: { in: routeIds }, tenantId: account.tenantId, isActive: true }, select: { id: true } })
    : [];
  const validIds = new Set(validRoutes.map((r: any) => r.id));
  const invalidIds = routeIds.filter((routeId) => !validIds.has(routeId));
  if (invalidIds.length) return reply.status(400).send({ error: "invalid_outbound_route", routeIds: invalidIds });
  const requestedDefault = enabled.find((r) => r.isDefault === true)?.outboundRouteId || null;
  const defaultRouteId = requestedDefault && validIds.has(requestedDefault) ? requestedDefault : null;
  await (db as any).$transaction(async (tx: any) => {
    await tx.userOutboundRoutePermission.deleteMany({ where: { tenantId: account.tenantId, userId: target.id } });
    if (routeIds.length) {
      await tx.userOutboundRoutePermission.createMany({
        data: routeIds.map((routeId) => ({
          tenantId: account.tenantId,
          userId: target.id,
          outboundRouteId: routeId,
          enabled: true,
          isDefault: routeId === defaultRouteId,
        })),
      });
    }
  });
  await audit({
    tenantId: target.tenantId,
    actorUserId: admin.sub,
    targetUserId: target.id,
    action: "USER_SIP_ACCOUNT_ROUTES_UPDATED",
    entityType: "UserSipAccount",
    entityId: account.id,
    metadata: { accountTenantId: account.tenantId, routeIds, defaultRouteId },
  });
  return { ok: true, userId: target.id, tenantId: account.tenantId, accountId: account.id, routeIds, defaultRouteId };
});

// GET /voice/me/sip-accounts — the logged-in user's extra SIP accounts with the
// full per-tenant WebRTC config each account needs to register. No passwords.
app.get("/voice/me/sip-accounts", async (req, reply) => {
  const user = getUser(req);
  if (!checkBillingRateLimit(`sip-accounts-fetch:${user.sub}`, 120, 60 * 60 * 1000)) {
    return reply.status(429).send({ error: "RATE_LIMITED" });
  }
  const rows = await (db as any).userSipAccount.findMany({
    where: { userId: user.sub },
    include: { tenant: true, extension: { include: { pbxLink: true } } },
    orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }],
  });
  if (!rows.length) return { accounts: [] };

  const accounts: unknown[] = [];
  for (const row of rows) {
    const tenant = row.tenant;
    const tenantLink = await db.tenantPbxLink.findUnique({
      where: { tenantId: row.tenantId },
      include: { pbxInstance: true },
    });
    const pbxLinkRow = row.extension?.pbxLink || null;
    const turnCfg = await getEffectiveTurnConfig(row.tenantId).catch(() => null);
    const cfg = tenantLink ? resolveWebrtcConfig(tenant, tenantLink, turnCfg) : null;
    const identity = pbxLinkRow
      ? resolveWebrtcSipIdentity(pbxLinkRow as any)
      : { sipUsername: null as string | null, authUsername: null as string | null };
    const routeRows = await (db as any).userOutboundRoutePermission.findMany({
      where: {
        tenantId: row.tenantId,
        userId: user.sub,
        enabled: true,
        outboundRoute: { isActive: true, tenantId: row.tenantId },
      },
      include: { outboundRoute: true },
    });
    routeRows.sort((a: any, b: any) => {
      if (a.isDefault !== b.isDefault) return a.isDefault ? -1 : 1;
      const sortDelta = (a.outboundRoute?.sortOrder || 0) - (b.outboundRoute?.sortOrder || 0);
      if (sortDelta) return sortDelta;
      return String(a.outboundRoute?.name || "").localeCompare(String(b.outboundRoute?.name || ""));
    });
    const ready = !!(
      cfg?.webrtcEnabled &&
      cfg?.sipWsUrl &&
      cfg?.sipDomain &&
      identity.sipUsername &&
      pbxLinkRow?.webrtcEnabled &&
      (pbxLinkRow as any)?.sipPasswordEncrypted &&
      !pbxLinkRow?.isSuspended
    );
    accounts.push({
      id: row.id,
      tenantId: row.tenantId,
      tenantName: tenant?.name || null,
      label: row.label || tenant?.name || "Second line",
      extensionNumber: row.extension?.extNumber || null,
      displayName: row.extension?.displayName || null,
      sipUsername: identity.sipUsername,
      authUsername: identity.authUsername ?? identity.sipUsername,
      hasSipPassword: !!(pbxLinkRow as any)?.sipPasswordEncrypted,
      webrtcEnabled: !!(cfg?.webrtcEnabled && pbxLinkRow?.webrtcEnabled),
      ready,
      sipWsUrl: cfg?.sipWsUrl ?? null,
      sipDomain: cfg?.sipDomain ?? null,
      outboundProxy: cfg?.outboundProxy ?? null,
      iceServers: cfg?.iceServers ?? [],
      dtmfMode: cfg?.dtmfMode ?? "RFC2833",
      routes: routeRows.map((p: any) => formatPublicOutboundRoute(p.outboundRoute, p)),
    });
  }
  return { accounts };
});

// POST /voice/me/sip-accounts/:accountId/reset-sip-password — issue the SIP
// credential for ONE extra account to its owner (mirror of
// /voice/me/reset-sip-password for the primary extension).
app.post("/voice/me/sip-accounts/:accountId/reset-sip-password", async (req, reply) => {
  const user = getUser(req);
  const { accountId } = req.params as { accountId: string };
  if (!checkBillingRateLimit(`sip-provision-acct:${user.sub}`, 60, 60 * 60 * 1000)) {
    return reply.status(429).send({ error: "RATE_LIMITED" });
  }
  const account = await loadUserSipAccount(user.sub, accountId);
  if (!account) return reply.status(404).send({ error: "SIP_ACCOUNT_NOT_FOUND" });
  const tenantLink = await db.tenantPbxLink.findUnique({
    where: { tenantId: account.tenantId },
    include: { pbxInstance: true },
  });
  if (!tenantLink) return reply.status(400).send({ error: "PBX_NOT_LINKED" });
  const linkRow = account.extension?.pbxLink;
  if (!linkRow) {
    return reply.status(404).send({
      error: "EXTENSION_NOT_PROVISIONED",
      extensionNumber: account.extension?.extNumber || null,
      message: "This SIP account's extension is not linked to the PBX yet. Ask an administrator to sync it.",
    });
  }
  if (linkRow.isSuspended) return reply.status(403).send({ error: "EXTENSION_SUSPENDED" });

  let sipPassword = "";
  if (voiceSimulate) {
    sipPassword = `sim-webrtc-${Date.now()}`;
  } else if ((linkRow as any).sipPasswordEncrypted) {
    sipPassword = decryptJson<string>((linkRow as any).sipPasswordEncrypted);
  } else {
    try {
      const auth = decryptJson<{ token: string; secret?: string }>(tenantLink.pbxInstance.apiAuthEncrypted);
      const out = await getWirePbxClient({ baseUrl: tenantLink.pbxInstance.baseUrl, token: auth.token, secret: auth.secret }).resetPassword(linkRow.pbxExtensionId);
      sipPassword = out.sipPassword;
    } catch {
      return reply.status(400).send({ error: "SIP_CREDENTIAL_NOT_SET" });
    }
  }
  if (!sipPassword) return reply.status(400).send({ error: "SIP_CREDENTIAL_NOT_SET" });

  await db.pbxExtensionLink.update({ where: { id: linkRow.id }, data: { sipPasswordIssuedAt: new Date() } });
  const tenant = await db.tenant.findUnique({ where: { id: account.tenantId } });
  const turnCfg = await getEffectiveTurnConfig(account.tenantId).catch(() => null);
  await audit({
    tenantId: user.tenantId,
    actorUserId: user.sub,
    action: "VOICE_ME_SIP_ACCOUNT_PASSWORD_ISSUED",
    entityType: "UserSipAccount",
    entityId: account.id,
    metadata: { accountTenantId: account.tenantId },
  });
  return {
    accountId: account.id,
    sipPassword,
    provisioning: buildVoiceProvisioningBundle(tenant, tenantLink, linkRow, sipPassword, turnCfg),
  };
});

// POST /voice/me/sip-accounts/resolve-dial — apply an (optional) outbound-route
// prefix from the ACCOUNT's tenant before dialing from that account.
app.post("/voice/me/sip-accounts/resolve-dial", async (req, reply) => {
  const user = getUser(req);
  const input = z
    .object({
      number: z.string().trim().min(1).max(80),
      accountId: z.string().trim().min(1),
      outboundRouteId: z.string().trim().min(1).optional().nullable(),
    })
    .parse(req.body || {});
  const account = await loadUserSipAccount(user.sub, input.accountId);
  if (!account) return reply.status(404).send({ error: "SIP_ACCOUNT_NOT_FOUND" });
  const originalNumber = input.number.trim();
  const normalizedNumber = normalizeOutboundDialTarget(originalNumber);
  if (!normalizedNumber) return reply.status(400).send({ error: "invalid_number" });

  if (!input.outboundRouteId) {
    return {
      originalNumber,
      normalizedNumber,
      finalNumber: normalizedNumber,
      accountId: account.id,
      outboundRouteId: null,
      outboundRouteName: null,
      prefixApplied: false,
    };
  }
  const permission = await (db as any).userOutboundRoutePermission.findFirst({
    where: {
      tenantId: account.tenantId,
      userId: user.sub,
      outboundRouteId: input.outboundRouteId,
      enabled: true,
      outboundRoute: { tenantId: account.tenantId, isActive: true },
    },
    include: { outboundRoute: true },
  });
  if (!permission?.outboundRoute) {
    await audit({
      tenantId: user.tenantId,
      actorUserId: user.sub,
      action: "OUTBOUND_ROUTE_DIAL_DENIED",
      entityType: "OutboundRoute",
      entityId: input.outboundRouteId,
      metadata: { originalNumber, accountId: account.id, reason: "route_not_allowed" },
    });
    return reply.status(403).send({ error: "outbound_route_not_allowed" });
  }
  const resolved = applyInternalOutboundPrefix(normalizedNumber, permission.outboundRoute.prefix);
  await audit({
    tenantId: user.tenantId,
    actorUserId: user.sub,
    action: "OUTBOUND_ROUTE_DIAL_RESOLVED",
    entityType: "OutboundRoute",
    entityId: permission.outboundRoute.id,
    metadata: {
      routeName: permission.outboundRoute.name,
      accountId: account.id,
      accountTenantId: account.tenantId,
      originalNumber,
      normalizedNumber,
      finalNumber: resolved.finalNumber,
      prefixApplied: resolved.prefixApplied,
      emergencyBypass: isEmergencyOutboundDialTarget(normalizedNumber),
    },
  });
  return {
    originalNumber,
    normalizedNumber,
    finalNumber: resolved.finalNumber,
    accountId: account.id,
    outboundRouteId: permission.outboundRoute.id,
    outboundRouteName: permission.outboundRoute.name,
    prefixApplied: resolved.prefixApplied,
  };
});

registerAdminUserCrmAccessRoutes(app, {
  requirePermission,
  canManageUsers,
  resolveAdminTargetUser,
  audit,
});

app.patch("/admin/users/:id", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageUsers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const input = z.object({
    tenantId: z.string().optional(),
    extensionId: z.string().nullable().optional(),
    role: z.union([z.enum(USER_MANAGEMENT_ROLES), z.enum(PORTAL_ROLE_BUCKETS)]).optional(),
    email: z.string().email().optional(),
    firstName: z.string().max(80).optional(),
    lastName: z.string().max(80).optional(),
    displayName: z.string().max(160).optional(),
    phone: z.string().max(80).nullable().optional(),
    title: z.string().max(120).nullable().optional(),
    department: z.string().max(120).nullable().optional(),
    notes: z.string().max(2000).nullable().optional(),
    status: z.enum(["INVITED", "ACTIVE", "DISABLED"]).optional(),
  }).parse(req.body || {});
  const rawRole = input.role ? String(input.role).toUpperCase() : undefined;
  const isPortalBucket = rawRole && (PORTAL_ROLE_BUCKETS as readonly string[]).includes(rawRole);
  const effectiveRole = rawRole
    ? (isPortalBucket ? dbRoleFromPortalBucket(rawRole as PortalRoleBucket) : rawRole) as UserManagementRole
    : undefined;
  const target = await db.user.findFirst({ where: admin.role === "SUPER_ADMIN" ? { id } : { id, tenantId: admin.tenantId } });
  if (!target) return reply.status(404).send({ error: "user_not_found" });
  if (effectiveRole && !canAssignRole(admin, effectiveRole)) return reply.status(403).send({ error: "forbidden" });
  const nextTenantId = admin.role === "SUPER_ADMIN" && input.tenantId ? await resolveManagedTenant(admin, input.tenantId) : target.tenantId;
  let nextExtension: any = undefined;
  if (input.extensionId !== undefined) {
    if (input.extensionId) {
      nextExtension = await db.extension.findFirst({ where: { id: input.extensionId, tenantId: nextTenantId } });
      if (!nextExtension) return reply.status(404).send({ error: "extension_not_found" });
      if (nextExtension.ownerUserId && nextExtension.ownerUserId !== target.id) return reply.status(409).send({ error: "extension_already_assigned" });
    } else {
      nextExtension = null;
    }
  }
  // User.email is globally unique. Pre-check so we return a clean, actionable
  // 409 instead of leaking a raw Prisma P2002 dump into the Edit User dialog.
  let nextEmail: string | undefined = undefined;
  if (input.email !== undefined) {
    nextEmail = normalizeEmail(input.email);
    if (nextEmail && nextEmail !== target.email) {
      const clash = await db.user.findFirst({
        where: { email: nextEmail, NOT: { id: target.id } },
        select: { id: true, tenant: { select: { name: true } } },
      });
      if (clash) {
        const msg = `That email (${nextEmail}) is already used by another user${clash.tenant?.name ? ` in tenant "${clash.tenant.name}"` : ""}. Choose a different email.`;
        return reply.status(409).send({ error: "email_already_in_use", message: msg, detail: msg });
      }
    }
  }
  let updated;
  try {
    updated = await db.$transaction(async (tx) => {
      if (nextExtension !== undefined) {
        await tx.extension.updateMany({ where: { ownerUserId: target.id }, data: { ownerUserId: null } });
        if (nextExtension) await tx.extension.update({ where: { id: nextExtension.id }, data: { ownerUserId: target.id } });
      }
      return tx.user.update({
      where: { id: target.id },
      data: {
        tenantId: nextTenantId,
        email: nextEmail,
        role: effectiveRole as any,
        status: input.status as any,
        firstName: input.firstName?.trim(),
        lastName: input.lastName?.trim(),
        displayName: input.displayName?.trim(),
        phone: input.phone === undefined ? undefined : input.phone?.trim() || null,
        title: input.title === undefined ? undefined : input.title?.trim() || null,
        department: input.department === undefined ? undefined : input.department?.trim() || null,
        notes: input.notes === undefined ? undefined : input.notes?.trim() || null,
      } as any,
      include: { tenant: { select: { id: true, name: true } }, ownedExtensions: { take: 1 }, passwordTokens: { take: 1, orderBy: { createdAt: "desc" } } } as any,
      });
    });
  } catch (err: any) {
    // Safety net for any unique collision that slipped past the pre-checks
    // (race, or a field other than email) — never leak the raw Prisma dump.
    if (String(err?.code) === "P2002") {
      const fields = Array.isArray(err?.meta?.target) ? err.meta.target.join(", ") : String(err?.meta?.target ?? "");
      const isEmail = /email/i.test(fields);
      const msg = isEmail
        ? "That email is already used by another user. Choose a different email."
        : `That change conflicts with an existing record${fields ? ` (${fields})` : ""}.`;
      return reply.status(409).send({ error: isEmail ? "email_already_in_use" : "duplicate_value", message: msg, detail: msg });
    }
    throw err;
  }
  await audit({ tenantId: updated.tenantId, actorUserId: admin.sub, targetUserId: updated.id, action: "USER_UPDATED", entityType: "User", entityId: updated.id, metadata: { role: effectiveRole, status: input.status } });
  return { ok: true, user: formatAdminUser(updated) };
});

