app.post("/pbx/link", async (req, reply) => {
  const admin = await requireAdmin(req, reply);
  if (!admin) return;
  const input = z.object({
    pbxInstanceId: z.string(),
    pbxTenantId: z.string().optional(),
    pbxTenantCode: z.string().optional(),
    pbxDomain: z.string().optional(),
  }).parse(req.body || {});

  const instance = await db.pbxInstance.findUnique({ where: { id: input.pbxInstanceId } });
  if (!instance || !instance.isEnabled) return reply.status(404).send({ error: "PBX_INSTANCE_NOT_FOUND" });

  const linked = await db.tenantPbxLink.upsert({
    where: { tenantId: admin.tenantId },
    create: {
      tenantId: admin.tenantId,
      pbxInstanceId: input.pbxInstanceId,
      pbxTenantId: input.pbxTenantId || null,
      pbxTenantCode: input.pbxTenantCode?.trim() || null,
      pbxDomain: input.pbxDomain || null,
      status: "LINKED"
    },
    update: {
      pbxInstanceId: input.pbxInstanceId,
      pbxTenantId: input.pbxTenantId || null,
      pbxTenantCode: input.pbxTenantCode !== undefined ? (input.pbxTenantCode?.trim() || null) : undefined,
      pbxDomain: input.pbxDomain || null,
      status: "LINKED",
      lastError: null
    }
  });

  // Auto-bootstrap WebRTC for new tenants: if the tenant has never had webrtcEnabled
  // set and we have a known PBX WebSocket endpoint, enable it now so the softphone
  // and QR-code provisioning work immediately without a separate manual step.
  const tenantRow = await db.tenant.findUnique({
    where: { id: admin.tenantId },
    select: { webrtcEnabled: true, sipWsUrl: true, sipDomain: true },
  });
  if (tenantRow && !tenantRow.webrtcEnabled) {
    // Never bake a raw-IP WS URL into the tenant row: rewrite it to the PBX's
    // canonical FQDN first (the PBX cert host). Persisting an IP here is exactly
    // what stranded tenants on a `wss://<ip>` URL that fails mobile TLS.
    const canonicalHost = deriveCanonicalPbxHost({
      pbxDomain: input.pbxDomain,
      pbxInstanceBaseUrl: instance.baseUrl,
      envPublicHost: process.env.PBX_WS_PUBLIC_HOST,
    });
    const rawWsEndpoint = normalizeSipWsUrlHost(pbxWsEndpoint || null, canonicalHost); // module-level const from PBX_WS_ENDPOINT
    const resolvedDomain =
      input.pbxDomain ||
      canonicalHost ||
      (rawWsEndpoint
        ? (() => { try { return new URL(rawWsEndpoint.replace(/^wss?:\/\//, "https://")).hostname; } catch { return null; } })()
        : null);
    await db.tenant.update({
      where: { id: admin.tenantId },
      data: {
        webrtcEnabled: true,
        ...(!tenantRow.sipWsUrl && rawWsEndpoint ? { sipWsUrl: rawWsEndpoint } : {}),
        ...(!tenantRow.sipDomain && resolvedDomain ? { sipDomain: resolvedDomain } : {}),
      },
    });
  }

  await audit({ tenantId: admin.tenantId, actorUserId: admin.sub, action: "PBX_LINKED", entityType: "TenantPbxLink", entityId: linked.id });
  return linked;
});

