/**
 * READ-ONLY per-tenant extension sync. Pulls THIS tenant's extensions from
 * VitalPBX (GET only) and upserts them into Connect — the efficient way to bring
 * in a newly-added extension without the full all-tenant "Refresh PBX".
 *
 * This path NEVER modifies the PBX: it issues no apply_changes, no tenant write,
 * no config regenerate. The VitalPbxClient is in read-only safe mode, so even a
 * future accidental mutation would be blocked. Safe to call as often as needed.
 */
app.post("/pbx/extensions/sync", async (req, reply) => {
  const admin = await requireAdmin(req, reply);
  if (!admin) return;
  if (!ensureCredentialCrypto(reply)) return;
  const input = z.object({ tenantId: z.string().optional() }).parse(req.body || {});

  // Super-admin with no tenant selected → sync EVERY tenant's extensions across
  // all enabled PBX instances in one shot (read-only against the PBX). This backs
  // the global "Sync from PBX" button so an admin never has to sync tenant-by-tenant.
  if (admin.role === "SUPER_ADMIN" && !input.tenantId) {
    const instances = await db.pbxInstance.findMany({ where: { isEnabled: true } });
    let totalFound = 0;
    let totalUpserted = 0;
    let totalDeactivated = 0;
    let totalErrors = 0;
    for (const instance of instances) {
      try {
        const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
        const client = getVitalPbxClient({
          baseUrl: instance.baseUrl,
          token: auth.token,
          secret: auth.secret,
          timeoutMs: 60000,
        });
        // No vitalTenantId → syncExtensionsFromPbx walks every tenant on the instance.
        const result = await syncExtensionsFromPbx(db, instance.id, client, {});
        totalFound += result.totalExtensions;
        totalUpserted += result.totalUpserted;
        totalDeactivated += result.totalDeactivated;
        totalErrors += result.totalErrors;
      } catch (e: any) {
        totalErrors += 1;
        app.log.error({ err: e, pbxInstanceId: instance.id }, "all-tenant extension sync failed for instance");
      }
    }
    return {
      ok: true,
      allTenants: true,
      extensionsFound: totalFound,
      extensionsUpserted: totalUpserted,
      extensionsDeactivated: totalDeactivated,
      errors: totalErrors,
    };
  }

  const tenantId =
    admin.role === "SUPER_ADMIN" && input.tenantId
      ? await resolveManagedTenant(admin, input.tenantId).catch(() => null)
      : admin.tenantId;
  if (!tenantId) return reply.status(400).send({ error: "tenant_required" });

  const link = await db.tenantPbxLink.findUnique({
    where: { tenantId },
    include: { pbxInstance: true },
  });
  if (!link || !link.pbxInstance) return reply.status(404).send({ error: "PBX_LINK_NOT_FOUND" });

  const auth = decryptJson<{ token: string; secret?: string }>(link.pbxInstance.apiAuthEncrypted);
  const client = getVitalPbxClient({
    baseUrl: link.pbxInstance.baseUrl,
    token: auth.token,
    secret: auth.secret,
    timeoutMs: 45000,
  });
  const vitalTenantId = link.pbxTenantId || undefined;
  try {
    const result = await syncExtensionsFromPbx(db, link.pbxInstanceId, client, {
      ...(vitalTenantId ? { vitalTenantId } : {}),
    });
    return {
      ok: true,
      tenantId,
      extensionsFound: result.totalExtensions,
      extensionsUpserted: result.totalUpserted,
      extensionsDeactivated: result.totalDeactivated,
      errors: result.totalErrors,
    };
  } catch (e: any) {
    return reply.status(502).send({ error: "PBX_SYNC_FAILED", message: String(e?.message || e) });
  }
});

app.post("/pbx/extensions", async (req, reply) => {
  const admin = await requireAdmin(req, reply);
  if (!admin) return;

  if (!checkBillingRateLimit(`pbx-ext-create:${admin.tenantId}`, 30, 60 * 60 * 1000)) {
    return reply.status(429).send({ error: "RATE_LIMITED" });
  }

  const input = z.object({ extensionNumber: z.string().min(2), displayName: z.string().min(2), enableWebrtc: z.boolean().default(true), enableMobile: z.boolean().default(true) }).parse(req.body || {});
  const link = await getTenantPbxLinkOrThrow(admin.tenantId).catch(() => null);
  if (!link) return reply.status(400).send({ error: "PBX_NOT_LINKED" });

  const ext = await db.extension.create({ data: { tenantId: admin.tenantId, extNumber: input.extensionNumber, displayName: input.displayName, ownerUserId: admin.sub } });

  const auth = decryptJson<{ token: string; secret?: string }>(link.pbxInstance.apiAuthEncrypted);
  const pbx = getWirePbxClient({ baseUrl: link.pbxInstance.baseUrl, token: auth.token, secret: auth.secret });

  try {
    const created = await pbx.createExtension({ pbxTenantId: link.pbxTenantId || undefined, extensionNumber: input.extensionNumber, displayName: input.displayName });
    const dev = await pbx.createSipDevice({ pbxExtensionId: created.pbxExtensionId, enableWebrtc: input.enableWebrtc, enableMobile: input.enableMobile });

    const tenantCfg = await db.tenant.findUnique({ where: { id: admin.tenantId } });
    const saved = await db.pbxExtensionLink.create({
      data: {
        tenantId: admin.tenantId,
        extensionId: ext.id,
        pbxExtensionId: created.pbxExtensionId,
        pbxSipUsername: dev.sipUsername || created.sipUsername,
        sipPasswordHash: dev.sipPassword ? await bcrypt.hash(dev.sipPassword, 10) : null,
        sipPasswordIssuedAt: dev.sipPassword ? new Date() : null,
        pbxDeviceId: dev.pbxDeviceId || null,
        isSuspended: false
      }
    });

    const provisioning = buildVoiceProvisioningBundle(tenantCfg, link, saved, dev.sipPassword || null);

    await audit({ tenantId: admin.tenantId, actorUserId: admin.sub, action: "PBX_EXTENSION_CREATED", entityType: "PbxExtensionLink", entityId: saved.id });
    return { extension: ext, pbxLink: saved, provisioning };
  } catch (e: any) {
    await queuePbxJob({ tenantId: admin.tenantId, pbxInstanceId: link.pbxInstanceId, type: "CREATE_EXTENSION", payload: { extensionId: ext.id, extensionNumber: input.extensionNumber, displayName: input.displayName, enableWebrtc: input.enableWebrtc, enableMobile: input.enableMobile }, lastError: String(e?.code || e?.message || "PBX_UNAVAILABLE") });
    // Do NOT mark the TenantPbxLink as ERROR here — the link itself is healthy;
    // only this individual extension creation hit a transient PBX error.
    // The job is queued for retry; poisoning the link status blocks the UI
    // and prevents QR codes / registration for the entire tenant.
    await audit({ tenantId: admin.tenantId, actorUserId: admin.sub, action: "PBX_EXTENSION_QUEUED", entityType: "Extension", entityId: ext.id });
    return reply.status(202).send({ queued: true, error: "PBX_UNAVAILABLE", extensionId: ext.id });
  }
});

