app.patch("/admin/pbx/instances/:id", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  if (!ensureCredentialCrypto(reply)) return;

  const { id } = req.params as { id: string };
  const input = z.object({ name: z.string().min(2).optional(), baseUrl: z.string().url().optional(), token: z.string().min(4).optional(), secret: z.string().optional(), isEnabled: z.boolean().optional() }).parse(req.body || {});
  const curr = await db.pbxInstance.findUnique({ where: { id } });
  if (!curr) return reply.status(404).send({ error: "not_found" });

  let apiAuthEncrypted = curr.apiAuthEncrypted;
  if (input.token || input.secret) {
    const existing = decryptJson<{ token: string; secret?: string | null }>(curr.apiAuthEncrypted);
    apiAuthEncrypted = encryptJson({ token: input.token || existing.token, secret: input.secret !== undefined ? input.secret : existing.secret || null });
  }

  const updated = await db.pbxInstance.update({ where: { id }, data: { name: input.name, baseUrl: input.baseUrl, isEnabled: input.isEnabled, apiAuthEncrypted } });
  await audit({ tenantId: admin.tenantId, actorUserId: admin.sub, action: "PBX_INSTANCE_UPDATED", entityType: "PbxInstance", entityId: updated.id });
  return { id: updated.id, name: updated.name, baseUrl: updated.baseUrl, isEnabled: updated.isEnabled, updatedAt: updated.updatedAt };
});

app.post("/admin/pbx/instances/:id/test", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  if (!ensureCredentialCrypto(reply)) return;

  const { id } = req.params as { id: string };
  const instance = await db.pbxInstance.findUnique({ where: { id } });
  if (!instance) return reply.status(404).send({ error: "not_found" });
  const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);

  try {
    // Primary test path for VitalPBX integrations: GET /api/v2/tenants.
    const vital = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret });
    const tenants = await vital.listTenants();
    const healthy = Array.isArray(tenants) && tenants.every((row) => row && typeof row === "object");
    if (!healthy) {
      return reply.status(400).send({ error: "PBX_PARSE_ERROR", message: "VitalPBX tenants payload is invalid." });
    }
    const capabilities = await vital.detectCapabilities().catch(() => null);
    await audit({ tenantId: admin.tenantId, actorUserId: admin.sub, action: "PBX_INSTANCE_TEST_OK", entityType: "PbxInstance", entityId: instance.id });
    return {
      ok: true,
      provider: "VITALPBX",
      tenantCount: tenants.length,
      capabilities
    };
  } catch (e: any) {
    // Backward-compatible fallback for existing WirePBX-style instances.
    try {
      await getWirePbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret }).healthCheck();
      await audit({ tenantId: admin.tenantId, actorUserId: admin.sub, action: "PBX_INSTANCE_TEST_OK", entityType: "PbxInstance", entityId: instance.id });
      return {
        ok: true,
        provider: "WIRE_PBX_COMPAT",
        warning: "VitalPBX test failed but WirePBX compatibility health endpoint passed.",
        vitalError: String(e?.code || e?.message || "PBX_UNAVAILABLE")
      };
    } catch (wireErr: any) {
      await audit({ tenantId: admin.tenantId, actorUserId: admin.sub, action: "PBX_INSTANCE_TEST_FAILED", entityType: "PbxInstance", entityId: instance.id });
      return reply.status(400).send({
        error: String(e?.code || "PBX_UNAVAILABLE"),
        message: String(e?.message || "VitalPBX connection test failed"),
        fallbackError: String(wireErr?.code || wireErr?.message || "PBX_UNAVAILABLE")
      });
    }
  }
});

type VitalResourceName =
  | "extensions"
  | "trunks"
  | "ring-groups"
  | "queues"
  | "ivr"
  | "routes"
  | "tenants"
  | "users"
  | "roles"
  | "cdr"
  | "devices"
  | "device-profiles"
  | "destinations"
  | "classes-of-services"
  | "conferences"
  | "phonebooks"
  | "route-selections"
  | "account-codes"
  | "authorization-codes"
  | "customer-codes"
  | "ai-api-keys"
  | "sms"
  | "whatsapp"
  | "virtual-faxes"
  | "voicemail"
  | "parking-lots";

function isVitalResourceName(input: string): input is VitalResourceName {
  return [
    "extensions",
    "trunks",
    "ring-groups",
    "queues",
    "ivr",
    "routes",
    "tenants",
    "users",
    "roles",
    "cdr",
    "devices",
    "device-profiles",
    "destinations",
    "classes-of-services",
    "conferences",
    "phonebooks",
    "route-selections",
    "account-codes",
    "authorization-codes",
    "customer-codes",
    "ai-api-keys",
    "sms",
    "whatsapp",
    "virtual-faxes",
    "voicemail",
    "parking-lots"
  ].includes(input);
}

async function vitalListByResource(client: VitalPbxClient, resource: VitalResourceName, tenantId?: string) {
  if (resource === "extensions") return client.listExtensions(tenantId);
  if (resource === "trunks") return client.listTrunks(tenantId);
  if (resource === "ring-groups") return client.listRingGroups(tenantId);
  if (resource === "queues") return client.listQueues(tenantId);
  if (resource === "ivr") return client.listIvr(tenantId);
  if (resource === "routes") return client.listRoutes(tenantId);
  if (resource === "tenants") return client.listTenants();
  if (resource === "users") return (await client.callEndpoint<any[]>("users.list", { tenant: tenantId })).data || [];
  if (resource === "roles") return (await client.callEndpoint<any[]>("roles.list", { tenant: tenantId })).data || [];
  if (resource === "cdr") return (await client.callEndpoint<any[]>("cdr.list", { tenant: tenantId })).data || [];
  if (resource === "devices") return (await client.callEndpoint<any[]>("devices.list", { tenant: tenantId })).data || [];
  if (resource === "device-profiles") return (await client.callEndpoint<any[]>("deviceProfiles.list", { tenant: tenantId })).data || [];
  if (resource === "destinations") return (await client.callEndpoint<any[]>("destinations.list", { tenant: tenantId })).data || [];
  if (resource === "classes-of-services") return (await client.callEndpoint<any[]>("classesOfServices.list", { tenant: tenantId })).data || [];
  if (resource === "conferences") return (await client.callEndpoint<any[]>("conferences.list", { tenant: tenantId })).data || [];
  if (resource === "phonebooks") return (await client.callEndpoint<any[]>("phonebooks.list", { tenant: tenantId })).data || [];
  if (resource === "route-selections") return (await client.callEndpoint<any[]>("routeSelections.list", { tenant: tenantId })).data || [];
  if (resource === "account-codes") return client.listAccountCodes(tenantId);
  if (resource === "authorization-codes") return client.listAuthorizationCodes(tenantId);
  if (resource === "customer-codes") return client.listCustomerCodes(tenantId);
  if (resource === "ai-api-keys") return client.listAiApiKeys(tenantId);
  if (resource === "sms") return (await client.callEndpoint<any[]>("sms.phoneNumbers", { tenant: tenantId })).data || [];
  if (resource === "whatsapp") return (await client.callEndpoint<any[]>("whatsapp.numbers", { tenant: tenantId })).data || [];
  if (resource === "virtual-faxes") return (await client.callEndpoint<any[]>("virtualFaxes.list", { tenant: tenantId })).data || [];
  if (resource === "parking-lots") return (await client.callEndpoint<any[]>("parkingLots.list", { tenant: tenantId })).data || [];
  if (resource === "voicemail") throw new Error("resource_requires_item_path");
  throw new Error("resource_not_supported");
}

async function vitalCreateByResource(client: VitalPbxClient, resource: VitalResourceName, payload: Record<string, unknown>, tenantId?: string) {
  if (resource === "extensions") return client.createExtension(payload);
  if (resource === "trunks") return client.createTrunk(payload);
  if (resource === "ring-groups") return client.createRingGroup(payload);
  if (resource === "queues") return client.createQueue(payload, tenantId);
  if (resource === "ivr") return client.createIvr(payload);
  if (resource === "routes") return client.createRoute(payload);
  if (resource === "tenants") return client.createTenant(payload);
  if (resource === "authorization-codes") return client.createAuthorizationCode(payload, tenantId);
  if (resource === "customer-codes") return client.createCustomerCode(payload, tenantId);
  if (resource === "ai-api-keys") return client.createAiApiKey(payload, tenantId);
  throw new Error("resource_not_supported");
}

async function vitalUpdateByResource(client: VitalPbxClient, resource: VitalResourceName, id: string, payload: Record<string, unknown>, tenantId?: string) {
  if (resource === "extensions") return client.updateExtension(id, payload);
  if (resource === "trunks") return client.updateTrunk(id, payload);
  if (resource === "ring-groups") return client.updateRingGroup(id, payload);
  if (resource === "queues") return client.updateQueue(id, payload, tenantId);
  if (resource === "ivr") return client.updateIvr(id, payload);
  if (resource === "routes") return client.updateRoute(id, payload);
  if (resource === "tenants") return client.updateTenant(id, payload);
  if (resource === "authorization-codes") return client.updateAuthorizationCode(id, payload, tenantId);
  if (resource === "customer-codes") return client.updateCustomerCode(id, payload, tenantId);
  if (resource === "ai-api-keys") return client.updateAiApiKey(id, payload, tenantId);
  throw new Error("resource_not_supported");
}

async function vitalDeleteByResource(client: VitalPbxClient, resource: VitalResourceName, id: string, tenantId?: string) {
  if (resource === "extensions") return client.deleteExtension(id);
  if (resource === "trunks") return client.deleteTrunk(id);
  if (resource === "ring-groups") return client.deleteRingGroup(id);
  if (resource === "queues") return client.deleteQueue(id, tenantId);
  if (resource === "ivr") return client.deleteIvr(id);
  if (resource === "routes") return client.deleteRoute(id);
  if (resource === "tenants") return client.deleteTenant(id);
  if (resource === "authorization-codes") return client.deleteAuthorizationCode(id, tenantId);
  if (resource === "customer-codes") return client.deleteCustomerCode(id, tenantId);
  if (resource === "ai-api-keys") return client.deleteAiApiKey(id, tenantId);
  throw new Error("resource_not_supported");
}

// PBX_TENANT_SYNC_INTERVAL_MS: how often the warm cycle re-fetches tenants from VitalPBX and
// upserts PbxTenantDirectory. Default 5 min; minimum 60 s; maximum 30 min.
// Increase on high-latency PBX hosts; decrease (to ≥60 s) for faster new-tenant discovery.
const _pbxTenantSyncIntervalMs = (() => {
  const raw = parseInt(process.env.PBX_TENANT_SYNC_INTERVAL_MS ?? "", 10);
  if (!Number.isFinite(raw) || raw <= 0) return 5 * 60_000;
  return Math.min(30 * 60_000, Math.max(60_000, raw));
})();
const PBX_TENANT_LIST_CACHE_TTL_MS = _pbxTenantSyncIntervalMs;
const PBX_TENANT_LIST_STALE_MS = 30_000;
type PbxTenantListPayload = {
  instanceId: string;
  tenants: any[];
  directoryUpserted: number;
  directoryCreated: number;
  directoryUpdated: number;
  directoryDeleted: number;
  inboundDidSync: { tenantsProcessed: number; numbersUpserted: number; errors: string[] };
};
const PBX_TENANT_LIST_CACHE = new Map<string, {
  at: number;
  payload: PbxTenantListPayload;
}>();
const PBX_TENANT_LIST_INFLIGHT = new Map<string, Promise<PbxTenantListPayload>>();
// Tracks when a *manual* POST /admin/pbx/refresh-tenants last ran per instance.
// Kept separate from PBX_TENANT_LIST_CACHE so that background GET /admin/pbx/tenants
// page-load calls don't erroneously block the next manual refresh.
const PBX_MANUAL_REFRESH_LAST_AT = new Map<string, number>();

async function listPbxTenantsFromDirectory(instanceId: string): Promise<any[]> {
  const rows = await db.pbxTenantDirectory.findMany({
    where: { pbxInstanceId: instanceId },
    orderBy: { displayName: "asc" },
    select: { vitalTenantId: true, tenantSlug: true, tenantCode: true, displayName: true },
    take: 500,
  });
  return rows.map((r) => ({
    tenant_id: r.vitalTenantId,
    id: r.vitalTenantId,
    name: r.tenantSlug || r.tenantCode || r.vitalTenantId,
    description: r.displayName || r.tenantSlug || r.tenantCode || r.vitalTenantId,
    enabled: true,
  }));
}

function startPbxTenantListRefresh(instance: any, auth: { token: string; secret?: string }, cacheKey: string) {
  const existing = PBX_TENANT_LIST_INFLIGHT.get(cacheKey);
  if (existing) return existing;

  const startedAt = Date.now();
  const promise = (async () => {
    const client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret, timeoutMs: 8_000 });
    const tenants = await client.listTenants();
    let directoryUpserted = 0;
    let directoryCreated = 0;
    let directoryUpdated = 0;
    let directoryDeleted = 0;
    try {
      const d = await syncPbxTenantDirectoryFromRows(db, instance.id, tenants);
      directoryUpserted = d.upserted;
      directoryCreated = d.created;
      directoryUpdated = d.updated;
      directoryDeleted = d.deleted;
      if (d.created > 0 || d.deleted > 0) {
        app.log.info(
          {
            event: "pbx_tenant_directory_new_tenants",
            pbxInstanceId: instance.id,
            created: d.created,
            updated: d.updated,
            deleted: d.deleted,
            upserted: d.upserted,
          },
          "pbx_tenant_directory_new_tenants",
        );
      }
    } catch (e: any) {
      app.log.warn(
        { event: "pbx_tenant_directory_sync_failed", pbxInstanceId: instance.id, err: e?.message },
        "pbx_tenant_directory_sync_failed",
      );
    }

    const payload = {
      instanceId: instance.id,
      tenants,
      directoryUpserted,
      directoryCreated,
      directoryUpdated,
      directoryDeleted,
      inboundDidSync: { tenantsProcessed: 0, numbersUpserted: 0, errors: [] as string[] },
    };
    PBX_TENANT_LIST_CACHE.set(cacheKey, { at: Date.now(), payload });

    // DID sync can fan out across tenants; never make UI boot wait for it.
    void syncPbxTenantInboundDids(db, instance.id)
      .then((inboundDidSync) => {
        if (inboundDidSync.errors.length) {
          app.log.warn({ count: inboundDidSync.errors.length, sample: inboundDidSync.errors.slice(0, 3) }, "admin/pbx/tenants: some inbound DID fetches failed");
        }
      })
      .catch((e: any) => app.log.warn({ err: e?.message }, "admin/pbx/tenants: inbound DID sync failed"));

    const elapsedMs = Date.now() - startedAt;
    if (elapsedMs > 4_000) app.log.warn({ elapsedMs, tenantCount: tenants.length }, "admin/pbx/tenants: refresh slow");
    return payload;
  })().finally(() => {
    PBX_TENANT_LIST_INFLIGHT.delete(cacheKey);
  });
  PBX_TENANT_LIST_INFLIGHT.set(cacheKey, promise);
  return promise;
}

app.get("/admin/pbx/tenants", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  const query = z.object({ instanceId: z.string().optional() }).parse(req.query || {});
  const instance = query.instanceId
    ? await db.pbxInstance.findUnique({ where: { id: query.instanceId } })
    : await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  if (!instance) return reply.status(404).send({ error: "PBX_INSTANCE_NOT_FOUND" });
  const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
  const cacheKey = instance.id;
  const cached = PBX_TENANT_LIST_CACHE.get(cacheKey);
  const age = cached ? Date.now() - cached.at : null;
  if (cached && age !== null && age < PBX_TENANT_LIST_STALE_MS) {
    return { ...cached.payload, cached: true, stale: false, refreshInProgress: PBX_TENANT_LIST_INFLIGHT.has(cacheKey), cacheAgeMs: age };
  }
  if (cached) {
    void startPbxTenantListRefresh(instance, auth, cacheKey).catch(() => undefined);
    return { ...cached.payload, cached: true, stale: age! > PBX_TENANT_LIST_CACHE_TTL_MS, refreshInProgress: PBX_TENANT_LIST_INFLIGHT.has(cacheKey), cacheAgeMs: age };
  }

  const directoryTenants = await listPbxTenantsFromDirectory(instance.id);
  if (directoryTenants.length > 0) {
    const payload = {
      instanceId: instance.id,
      tenants: directoryTenants,
      directoryUpserted: 0,
      directoryCreated: 0,
      directoryUpdated: 0,
      directoryDeleted: 0,
      inboundDidSync: { tenantsProcessed: 0, numbersUpserted: 0, errors: [] as string[] },
    };
    PBX_TENANT_LIST_CACHE.set(cacheKey, { at: Date.now(), payload });
    void startPbxTenantListRefresh(instance, auth, cacheKey).catch(() => undefined);
    return { ...payload, cached: true, stale: true, refreshInProgress: true, cacheAgeMs: 0 };
  }

  try {
    const payload = await startPbxTenantListRefresh(instance, auth, cacheKey);
    return { ...payload, cached: false, stale: false, refreshInProgress: false, cacheAgeMs: 0 };
  } catch (e: any) {
    return reply.status(502).send({ error: "PBX_TENANT_LIST_UNAVAILABLE", message: String(e?.message || "PBX tenant list unavailable") });
  }
});

let _pbxTenantListWarmStarted = false;
function startPbxTenantListWarm() {
  if (_pbxTenantListWarmStarted) return;
  _pbxTenantListWarmStarted = true;
  app.log.info(
    { intervalMs: PBX_TENANT_LIST_CACHE_TTL_MS },
    "pbx_tenant_sync_warm_init",
  );
  const warm = async () => {
    const warmStartedAt = Date.now();
    try {
      const instances = await db.pbxInstance.findMany({ where: { isEnabled: true }, take: 5 });
      for (const instance of instances) {
        const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
        const cacheKey = instance.id;
        const cached = PBX_TENANT_LIST_CACHE.get(cacheKey);
        if (cached && Date.now() - cached.at < PBX_TENANT_LIST_STALE_MS) continue;
        app.log.info(
          { event: "pbx_tenant_sync_warm_start", pbxInstanceId: instance.id },
          "pbx_tenant_sync_warm_start",
        );
        void startPbxTenantListRefresh(instance, auth, cacheKey)
          .then((payload) => {
            app.log.info(
              {
                event: "pbx_tenant_sync_warm_complete",
                pbxInstanceId: instance.id,
                pbxTenantCount: payload.tenants.length,
                directoryUpserted: payload.directoryUpserted,
                directoryCreated: payload.directoryCreated,
                directoryUpdated: payload.directoryUpdated,
                directoryDeleted: payload.directoryDeleted,
                durationMs: Date.now() - warmStartedAt,
              },
              "pbx_tenant_sync_warm_complete",
            );
          })
          .catch((e: any) => {
            app.log.warn(
              {
                event: "pbx_tenant_sync_warm_failed",
                pbxInstanceId: instance.id,
                err: e?.message || String(e),
                durationMs: Date.now() - warmStartedAt,
              },
              "pbx_tenant_sync_warm_failed",
            );
          });
      }
    } catch (e: any) {
      app.log.warn(
        { event: "pbx_tenant_sync_warm_failed", err: e?.message || String(e) },
        "pbx_tenant_sync_warm_failed",
      );
    }
  };
  registerShutdownTimer(setTimeout(warm, 3_000));
  registerShutdownTimer(setInterval(warm, PBX_TENANT_LIST_CACHE_TTL_MS));
}

/** Explicit backfill: list tenants once, refresh directory + inbound DIDs (same PBX call pattern as GET /admin/pbx/tenants). */
app.post("/admin/pbx/instances/:id/sync-tenant-dids", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const instance = await db.pbxInstance.findUnique({ where: { id } });
  if (!instance) return reply.status(404).send({ error: "PBX_INSTANCE_NOT_FOUND" });
  const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
  const client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret });
  const startedAt = Date.now();
  const tenants = await client.listTenants();
  const syncResult = await syncPbxTenantDirectoryFromRows(db, instance.id, tenants);
  const inboundDidSync = await syncPbxTenantInboundDids(db, instance.id);
  app.log.info(
    {
      event: "pbx_tenant_directory_manual_sync",
      pbxInstanceId: instance.id,
      pbxTenantCount: tenants.length,
      upserted: syncResult.upserted,
      created: syncResult.created,
      updated: syncResult.updated,
      deleted: syncResult.deleted,
      durationMs: Date.now() - startedAt,
      requestedBy: (admin as any).id ?? "unknown",
    },
    "pbx_tenant_directory_manual_sync",
  );
  return {
    ok: true,
    instanceId: instance.id,
    directoryUpserted: syncResult.upserted,
    directoryCreated: syncResult.created,
    directoryUpdated: syncResult.updated,
    directoryDeleted: syncResult.deleted,
    inboundDidSync,
  };
});

/**
 * Simple manual PBX tenant sync — uses the default enabled PBX instance.
 * Refreshes PbxTenantDirectory immediately without requiring a known instance ID.
 * Protected to SUPER_ADMIN only. Safe to call repeatedly; rate limited to 1 call per 30 s.
 *
 * After this returns, the telephony service's PbxTenantMapCache will pick up new tenants
 * within its configured poll interval (default 60 s, configurable via TELEPHONY_PBX_MAP_POLL_MS).
 */
app.post("/admin/pbx/refresh-tenants", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  if (!instance) return reply.status(404).send({ error: "PBX_INSTANCE_NOT_FOUND" });
  const cacheKey = instance.id;
  // Rate limit: at most one *manual* POST refresh per 30 s.
  // Uses a dedicated tracker (not PBX_TENANT_LIST_CACHE) so that background
  // GET /admin/pbx/tenants page-load calls do not block the user from clicking
  // the Refresh PBX button immediately after opening the tenant switcher.
  const lastManualRefreshAt = PBX_MANUAL_REFRESH_LAST_AT.get(cacheKey);
  const manualRefreshAgeMs = lastManualRefreshAt ? Date.now() - lastManualRefreshAt : null;
  if (manualRefreshAgeMs !== null && manualRefreshAgeMs < 30_000) {
    return reply.status(429).send({
      error: "pbx_tenant_refresh_rate_limited",
      message: "Tenant directory was refreshed less than 30 seconds ago. Please wait before retrying.",
      cacheAgeMs: manualRefreshAgeMs,
      retryAfterMs: 30_000 - manualRefreshAgeMs,
    });
  }
  PBX_MANUAL_REFRESH_LAST_AT.set(cacheKey, Date.now());
  const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
  const startedAt = Date.now();
  app.log.info(
    { event: "pbx_sync_start", pbxInstanceId: instance.id, requestedBy: (admin as any).id ?? "unknown" },
    "pbx_sync_start",
  );
  let tenants: any[] = [];
  let tenantSyncResult = { upserted: 0, created: 0, updated: 0, deleted: 0 };
  let client: ReturnType<typeof getVitalPbxClient>;
  try {
    client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret, timeoutMs: 8_000 });
    tenants = await client.listTenants();
    tenantSyncResult = await syncPbxTenantDirectoryFromRows(db, instance.id, tenants);
    // Invalidate in-memory cache so the next GET /admin/pbx/tenants serves fresh data.
    PBX_TENANT_LIST_CACHE.delete(cacheKey);
    app.log.info(
      {
        event: "tenant_options_refreshed",
        pbxInstanceId: instance.id,
        pbxTenantCount: tenants.length,
        created: tenantSyncResult.created,
        updated: tenantSyncResult.updated,
        deleted: tenantSyncResult.deleted,
      },
      "tenant_options_refreshed",
    );
  } catch (e: any) {
    app.log.warn(
      { event: "pbx_sync_tenant_failed", pbxInstanceId: instance.id, err: e?.message },
      "pbx_sync_tenant_failed",
    );
    return reply.status(502).send({ error: "PBX_TENANT_REFRESH_FAILED", message: String(e?.message || "PBX unavailable") });
  }

  // Extension sync — runs after tenant directory is up to date so that newly
  // created PbxTenantDirectory rows are already present for the mapping step.
  // Skipped tenants (no TenantPbxLink) are counted but do not cause errors.
  let extensionSyncResult: ExtensionSyncResult | null = null;
  try {
    extensionSyncResult = await syncExtensionsFromPbx(db, instance.id, client!);
    app.log.info(
      {
        event: "extension_sync_complete",
        pbxInstanceId: instance.id,
        totalExtensions: extensionSyncResult.totalExtensions,
        totalUpserted: extensionSyncResult.totalUpserted,
        totalSkipped: extensionSyncResult.totalSkipped,
        totalErrors: extensionSyncResult.totalErrors,
        linkedTenants: extensionSyncResult.tenantResults.filter((r) => !r.skipped).length,
      },
      "extension_sync_complete",
    );
  } catch (e: any) {
    // Extension sync failure is non-fatal — tenant directory is already updated.
    app.log.warn(
      { event: "extension_sync_failed", pbxInstanceId: instance.id, err: e?.message },
      "extension_sync_failed",
    );
  }

  // ── Step 3: Sync inbound DIDs (PbxTenantInboundDid) from Ombutel MySQL.
  // Non-fatal: skipped automatically if ombuMysqlUrlEncrypted is not configured.
  let didSyncResult: Awaited<ReturnType<typeof syncPbxTenantInboundDids>> | null = null;
  try {
    didSyncResult = await syncPbxTenantInboundDids(db, instance.id);
    app.log.info(
      {
        event: "did_sync_complete",
        pbxInstanceId: instance.id,
        source: didSyncResult.source,
        tenantsProcessed: didSyncResult.tenantsProcessed,
        numbersUpserted: didSyncResult.numbersUpserted,
        errors: didSyncResult.errors,
        skipReason: (didSyncResult as any).skipReason ?? null,
      },
      "did_sync_complete",
    );
  } catch (e: any) {
    // DID sync failure is non-fatal — extension and tenant syncs already completed.
    app.log.warn(
      { event: "did_sync_failed", pbxInstanceId: instance.id, err: e?.message },
      "did_sync_failed",
    );
  }

  const durationMs = Date.now() - startedAt;
  app.log.info(
    { event: "pbx_sync_complete", pbxInstanceId: instance.id, durationMs },
    "pbx_sync_complete",
  );

  return {
    ok: true,
    instanceId: instance.id,
    pbxTenantCount: tenants.length,
    directoryCreated: tenantSyncResult.created,
    directoryUpdated: tenantSyncResult.updated,
    directoryDeleted: tenantSyncResult.deleted,
    extensionsFound: extensionSyncResult?.totalExtensions ?? null,
    extensionsUpserted: extensionSyncResult?.totalUpserted ?? null,
    extensionsDeactivated: extensionSyncResult?.totalDeactivated ?? null,
    extensionsSkippedTenants: extensionSyncResult?.totalSkipped ?? null,
    extensionsAutoProvisioned: extensionSyncResult?.totalAutoProvisioned ?? null,
    extensionErrors: extensionSyncResult?.totalErrors ?? null,
    linkedTenants: extensionSyncResult?.tenantResults.filter((r) => !r.skipped).length ?? null,
    didSource: didSyncResult?.source ?? null,
    didTenantsProcessed: didSyncResult?.tenantsProcessed ?? null,
    didNumbersUpserted: didSyncResult?.numbersUpserted ?? null,
    didErrors: didSyncResult?.errors ?? null,
    lastSyncedAt: new Date().toISOString(),
    durationMs,
  };
});

/**
 * Sync VitalPBX extensions into Connect Extension + PbxExtensionLink tables.
 * Tenants with no TenantPbxLink are auto-provisioned (a Connect Tenant + link
 * is created automatically). Optional body: { vitalTenantId: "2" } to sync a single tenant.
 */
app.post("/admin/pbx/instances/:id/sync-extensions", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  if (!ensureCredentialCrypto(reply)) return;
  const { id } = req.params as { id: string };
  const input = z
    .object({ vitalTenantId: z.string().optional() })
    .parse(req.body || {});
  const instance = await db.pbxInstance.findUnique({ where: { id } });
  if (!instance) return reply.status(404).send({ error: "PBX_INSTANCE_NOT_FOUND" });
  const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
  const client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret });
  const syncResult = await syncExtensionsFromPbx(db, instance.id, client, {
    vitalTenantId: input.vitalTenantId,
  });
  return { ok: true, ...syncResult };
});

/** Read synced Extension + PbxExtensionLink rows for a PBX instance (admin view). */
app.get("/admin/pbx/extensions", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  const query = z
    .object({
      instanceId: z.string().optional(),
      tenantId: z.string().optional(),
      vitalTenantId: z.string().optional(),
    })
    .parse(req.query || {});

  const pbxLinks = await db.pbxExtensionLink.findMany({
    where: {
      ...(query.tenantId ? { tenantId: query.tenantId } : {}),
    },
    include: {
      extension: { select: { id: true, extNumber: true, displayName: true, status: true } },
    },
    orderBy: [{ tenantId: "asc" }, { extension: { extNumber: "asc" } }],
    take: 500,
  });

  return { ok: true, count: pbxLinks.length, extensions: pbxLinks };
});

/** Read persisted PBX tenant ↔ inbound DID rows (for verification / future UI). */
app.get("/admin/pbx/tenant-inbound-dids", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  const query = z.object({ instanceId: z.string().optional(), vitalTenantId: z.string().optional(), connectTenantId: z.string().optional(), activeOnly: z.enum(["0", "1"]).optional() }).parse(req.query || {});
  const instance = query.instanceId
    ? await db.pbxInstance.findUnique({ where: { id: query.instanceId } })
    : await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  if (!instance) return reply.status(404).send({ error: "PBX_INSTANCE_NOT_FOUND" });
  const where: Record<string, unknown> = { pbxInstanceId: instance.id };
  if (query.vitalTenantId?.trim()) where.vitalTenantId = query.vitalTenantId.trim();
  if (query.connectTenantId?.trim()) where.connectTenantId = query.connectTenantId.trim();
  if (query.activeOnly === "1") where.active = true;
  const rows = await db.pbxTenantInboundDid.findMany({
    where: where as any,
    orderBy: [{ vitalTenantId: "asc" }, { e164: "asc" }],
    take: 2000,
  });
  return { instanceId: instance.id, count: rows.length, rows };
});

app.post("/admin/pbx/tenants", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  const input = z.object({
    instanceId: z.string().min(1),
    name: z.string().min(2),
    externalId: z.string().optional(),
    sipDomain: z.string().optional(),
    extensionRangeStart: z.number().int().optional(),
    extensionRangeEnd: z.number().int().optional(),
    voicemailEnabled: z.boolean().default(true),
    recordingDirectory: z.string().optional()
  }).parse(req.body || {});
  const instance = await db.pbxInstance.findUnique({ where: { id: input.instanceId } });
  if (!instance) return reply.status(404).send({ error: "PBX_INSTANCE_NOT_FOUND" });
  const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
  const client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret });
  const created = await client.createTenant({
    name: input.name,
    externalId: input.externalId || undefined,
    sipDomain: input.sipDomain || undefined,
    extensionRangeStart: input.extensionRangeStart || undefined,
    extensionRangeEnd: input.extensionRangeEnd || undefined,
    voicemailEnabled: input.voicemailEnabled,
    recordingDirectory: input.recordingDirectory || undefined
  });
  await audit({ tenantId: admin.tenantId, actorUserId: admin.sub, action: "PBX_TENANT_CREATED", entityType: "PbxInstance", entityId: instance.id });
  return { ok: true, tenant: created };
});

