// Resource list cache: 120 s TTL — extensions/trunks/queues change rarely.
const PBX_RESOURCE_CACHE = new Map<string, { at: number; rows: any[] }>();

function isRealDirectoryExtensionNumber(value: unknown): boolean {
  const ext = String(value ?? "").trim();
  return /^\d{2,6}$/.test(ext);
}

function isTechnicalDirectoryValue(value: unknown): boolean {
  const raw = String(value ?? "").trim();
  if (!raw) return false;
  const lower = raw.toLowerCase();
  return (
    lower.includes("/") ||
    lower.startsWith("pjsip") ||
    lower.startsWith("custom") ||
    lower.startsWith("virtual") ||
    lower.startsWith("trunk") ||
    lower.startsWith("queue") ||
    lower.startsWith("ivr") ||
    lower.startsWith("parking") ||
    lower.startsWith("parked") ||
    lower.startsWith("voicemail") ||
    lower.includes("virtualdevice") ||
    lower.includes("custom/") ||
    lower.includes("pjsip/")
  );
}

function cleanDirectoryDisplayName(displayName: unknown, extNumber: string): string {
  const name = String(displayName ?? "").trim();
  if (!name || isTechnicalDirectoryValue(name)) return `Ext ${extNumber}`;
  return name;
}

function isDirectoryVisibleExtension(e: any): boolean {
  if (!e || e.status !== "ACTIVE" || e.billable === false) return false;
  if (!e.tenantId || !isRealDirectoryExtensionNumber(e.extNumber)) return false;
  // The canonical Connect Extension row is the source of truth. Reject rows whose
  // actual extension number is an Asterisk endpoint, but don't reject a real
  // extension just because PBX metadata contains a technical device name.
  return !isTechnicalDirectoryValue(e.extNumber);
}

function mapDirectoryExtensionRow(e: any): Record<string, unknown> {
  const extNumber = String(e.extNumber ?? "").trim();
  const displayName = cleanDirectoryDisplayName(e.displayName, extNumber);
  const safePbxDeviceName = isTechnicalDirectoryValue(e.pbxLink?.pbxDeviceName)
    ? null
    : e.pbxLink?.pbxDeviceName ?? null;
  return {
        id: e.pbxLink?.pbxExtensionId ?? e.id,
    extension: extNumber,
    name: displayName,
    callerName: displayName,
    displayName,
        technology: "pjsip",
        status: e.pbxLink?.isSuspended ? "disabled" : "enabled",
        tenantName: e.tenant?.name ?? null,
        tenantId: e.tenantId,
        pbxExtensionId: e.pbxLink?.pbxExtensionId,
        pbxSipUsername: e.pbxLink?.pbxSipUsername,
    pbxDeviceName: safePbxDeviceName,
        webrtcEnabled: e.pbxLink?.webrtcEnabled ?? false,
        connectExtensionId: e.id,
        // Provisioning metadata
        pbxExtensionLinkId: e.pbxLink?.id,
        ownerUserId: e.ownerUserId,
        assignedUser: e.ownerUser?.email ?? null,
        pbxUserEmail: e.pbxUserEmail ?? null,
        sipPasswordIssuedAt: e.pbxLink?.sipPasswordIssuedAt?.toISOString() ?? null,
  };
}

async function resolveDirectoryTenantIdFromContext(rawContext: string): Promise<string | null> {
  const raw = String(rawContext || "").trim();
  if (!raw || raw === "local") return null;

  if (!raw.startsWith("vpbx:")) {
    const tenant = await db.tenant.findUnique({ where: { id: raw }, select: { id: true } });
    return tenant?.id ?? null;
  }

  const slug = raw.slice(5).trim();
  const normalized = normalizeTenantLookupValue(slug);
  const links = await db.tenantPbxLink.findMany({
    include: { tenant: { select: { id: true, name: true } } },
    take: 500,
  });
  const direct = links.find((link) => {
    const candidates = [link.pbxTenantId, link.pbxTenantCode, link.tenant?.name]
      .map((v) => normalizeTenantLookupValue(String(v || "")));
    return candidates.includes(normalized);
  });
  if (direct) return direct.tenantId;

  const directory = await db.pbxTenantDirectory.findFirst({
    where: {
      OR: [
        { tenantSlug: slug },
        { tenantCode: slug },
        { vitalTenantId: slug },
        { tenantSlug: normalized },
        { tenantCode: normalized },
      ],
    },
  }).catch(() => null);
  if (!directory) return null;

  const byDirectory = links.find((link) => {
    if (link.pbxInstanceId !== directory.pbxInstanceId) return false;
    return [link.pbxTenantId, link.pbxTenantCode]
      .map((v) => normalizeTenantLookupValue(String(v || "")))
      .some((v) => v === normalizeTenantLookupValue(directory.vitalTenantId) || v === normalizeTenantLookupValue(directory.tenantCode));
  });
  return byDirectory?.tenantId ?? null;
}

app.get("/voice/pbx/resources/:resource", async (req, reply) => {
  const user = await requirePermission(req, reply, canViewCustomers);
  if (!user) return;
  const { resource } = req.params as { resource: string };
  if (!isVitalResourceName(resource)) return reply.status(400).send({ error: "resource_not_supported" });
  if (!canAccessVitalResourceAction(user, resource, "view")) return reply.status(403).send({ error: "forbidden" });

  // Extensions: serve from synced Connect DB (Phase 1 sync) — fast, no live VitalPBX call needed.
  if (resource === "extensions") {
    let queryTenantId: string | null = null;
    // Super-admin "all tenants" mode: when no specific tenant is selected, return
    // every tenant's extensions in one list (the Extensions table already shows a
    // Tenant column). This is the global directory view — so a platform admin never
    // has to pick tenants one-by-one to confirm every extension synced.
    let allTenants = false;

    if (!isRole(user, ["SUPER_ADMIN"])) {
      // Regular tenant users/admins are always scoped to their JWT tenant. Ignore
      // query/header tenant overrides so callers cannot enumerate another tenant.
      queryTenantId = user.tenantId;
    } else {
      const qsTenantId = String((req.query as any)?.tenantId || "").trim();
      const headerTenantId = String((req.headers as any)["x-tenant-context"] || "").trim();
      const pbxTenantOverride = (req as any).pbxTenantOverride as string | undefined;
      const tenantCtx = qsTenantId || headerTenantId || (pbxTenantOverride ? `vpbx:${pbxTenantOverride}` : "");
      if (tenantCtx) {
        queryTenantId = await resolveDirectoryTenantIdFromContext(tenantCtx);
      } else {
        // No tenant context at all → super-admin global directory (all tenants).
        allTenants = true;
      }
    }

    if (!allTenants && !queryTenantId) {
      app.log.info({ role: user.role }, "[EXT_FILTER_API] no tenant context; returning empty extension directory");
      return { resource, rows: [], source: "connect_db", tenantScoped: true };
    }

    const dbExts = await db.extension.findMany({
      where: allTenants
        ? { status: "ACTIVE", billable: true }
        : { tenantId: queryTenantId as string, status: "ACTIVE", billable: true },
      include: {
        pbxLink: { select: { id: true, pbxExtensionId: true, pbxSipUsername: true, pbxDeviceName: true, webrtcEnabled: true, isSuspended: true, sipPasswordIssuedAt: true } },
        ownerUser: { select: { id: true, email: true } },
        tenant: { select: { name: true } },
      },
      orderBy: allTenants
        ? [{ tenant: { name: "asc" } }, { extNumber: "asc" }]
        : [{ extNumber: "asc" }],
    });
    const rows = dbExts.filter(isDirectoryVisibleExtension).map(mapDirectoryExtensionRow);
    app.log.info(
      { mode: allTenants ? "all_tenants" : "tenant", queryTenantId, rowCount: rows.length, filteredOut: dbExts.length - rows.length },
      "[EXT_FILTER_API] returning real extensions"
    );
    return { resource, rows, source: "connect_db", tenantScoped: !allTenants };
  }

  // All other resources: proxy to VitalPBX directly.
  const pbxTenantOverride = (req as any).pbxTenantOverride as string | undefined;
  if (pbxTenantOverride && isRole(user, ["SUPER_ADMIN"])) {
    const overrideCacheKey = `vpbx:${pbxTenantOverride}:${resource}`;
    const overrideCached = PBX_RESOURCE_CACHE.get(overrideCacheKey);
    if (overrideCached && Date.now() - overrideCached.at < PBX_LIVE_TTL_RESOURCES) {
      return { resource, rows: overrideCached.rows };
    }
    const overrideInstance = await db.pbxInstance.findFirst({ where: { isEnabled: true } });
    if (!overrideInstance) return reply.status(404).send({ error: "PBX_INSTANCE_NOT_FOUND" });
    const overrideAuth = decryptJson<{ token: string; secret?: string }>(overrideInstance.apiAuthEncrypted);
    const overrideRows = await vitalListByResource(
      getVitalPbxClient({ baseUrl: overrideInstance.baseUrl, token: overrideAuth.token, secret: overrideAuth.secret }),
      resource as VitalResourceName,
      pbxTenantOverride
    );
    PBX_RESOURCE_CACHE.set(overrideCacheKey, { at: Date.now(), rows: overrideRows });
    return { resource, rows: overrideRows };
  }

  // Resolve WHOSE resources these are. This used to key off `user.tenantId` —
  // the signed-in admin's own tenant — so a super-admin viewing a customer
  // through the tenant switcher got their own (usually non-existent) PBX link
  // and a 404. That is why the IVR Studio could never offer a queue: every
  // tenant that has one is viewed this way. The extensions branch above already
  // honours the query param; this path did not. The cache key has to move with
  // it, or one customer's rows would be served to the next.
  const qTenantRaw = String((req.query as any)?.tenantId || "").trim();
  const scopedTenantId = qTenantRaw && isRole(user, ["SUPER_ADMIN"])
    ? (qTenantRaw.startsWith("vpbx:") ? await resolveConnectTenantIdFromScope(qTenantRaw) : qTenantRaw)
    : user.tenantId;
  if (!scopedTenantId) return reply.status(404).send({ error: "PBX_LINK_NOT_FOUND" });

  const cacheKey = `${scopedTenantId}:${resource}`;
  const cached = PBX_RESOURCE_CACHE.get(cacheKey);
  if (cached && Date.now() - cached.at < PBX_LIVE_TTL_RESOURCES) {
    return { resource, rows: cached.rows };
  }

  const link = await db.tenantPbxLink.findUnique({ where: { tenantId: scopedTenantId }, include: { pbxInstance: true } });
  if (!link) return reply.status(404).send({ error: "PBX_LINK_NOT_FOUND" });
  const auth = decryptJson<{ token: string; secret?: string }>(link.pbxInstance.apiAuthEncrypted);
  const out = await vitalListByResource(getVitalPbxClient({ baseUrl: link.pbxInstance.baseUrl, token: auth.token, secret: auth.secret }), resource, link.pbxTenantId || undefined);
  PBX_RESOURCE_CACHE.set(cacheKey, { at: Date.now(), rows: out });
  return { resource, rows: out };
});

// ── GET /voice/pbx/ring-groups ──────────────────────────────────────────────
//
// On-demand live listing of VitalPBX ring groups for a given tenant, scoped
// through Ombutel MariaDB (the REST collection doesn't expose ring groups).
// Used by the IVR destination picker so admins can pick a ring group from a
// dropdown instead of hand-typing `ext-group,601,1`.
//
// The caller may identify the target tenant in any of these formats (checked
// in priority order):
//   1. `?tenantId=<connectTenantId>`        — canonical Connect tenant id
//   2. `?tenantId=vpbx:<slug>`              — VitalPBX slug (super-admin
//                                              "view as tenant" mode — the
//                                              portal uses this shape when
//                                              no Connect TenantPbxLink row
//                                              exists yet for the tenant)
//   3. `x-tenant-context: vpbx:<slug>`      — same, but via header (set by
//                                              `apiClient` in the portal)
//   4. Otherwise: fall back to `user.tenantId`
//
// Response:
//   { rows: [{ number, name, strategy, id }], source, table }
//   On any config/schema problem we return `{ rows: [] }` plus a soft
//   `skipReason` so the UI can fall back to a free-text input cleanly.
app.get("/voice/pbx/ring-groups", async (req, reply) => {
  const user = await requirePermission(req, reply, canViewCustomers);
  if (!user) return;

  const isSuperAdmin = isRole(user, ["SUPER_ADMIN"]);
  const qsTenantId = String((req.query as any)?.tenantId || "").trim();
  const headerTenantId = String((req.headers as any)["x-tenant-context"] || "").trim();

  // Decide whether the caller gave us a `vpbx:<slug>` (super-admin mode) or
  // a Connect tenantId. vpbx: may arrive via the query string OR the header.
  let vpbxSlug: string | null = null;
  let connectTenantId: string | null = null;

  const raw = qsTenantId || headerTenantId || user.tenantId || "";
  if (raw.startsWith("vpbx:")) {
    if (!isSuperAdmin) {
      return reply.code(403).send({ error: "super_admin_required_for_vpbx_override" });
    }
    vpbxSlug = raw.slice(5).trim();
  } else if (raw && raw !== "local") {
    connectTenantId = raw;
  }

  if (!vpbxSlug && !connectTenantId) {
    return reply.send({ rows: [], source: "skipped", skipReason: "no tenant context" });
  }

  // Find the enabled PbxInstance for the mysql connection string, regardless
  // of which resolution path we took. In production we have exactly one.
  const pbxInstance = await db.pbxInstance.findFirst({ where: { isEnabled: true } });
  if (!pbxInstance) {
    return reply.send({ rows: [], source: "skipped", skipReason: "no_enabled_pbx_instance" });
  }

  // Resolve the VitalPBX tenant_id we should filter by in Ombutel. Two paths:
  //   A. connectTenantId → TenantPbxLink.pbxTenantId
  //   B. vpbxSlug        → PbxTenantDirectory.vitalTenantId (numeric id)
  let vitalTenantId: string | null = null;
  if (connectTenantId) {
    const link = await db.tenantPbxLink.findUnique({
      where: { tenantId: connectTenantId },
      select: { pbxTenantId: true },
    });
    vitalTenantId = link?.pbxTenantId?.trim() || null;
  } else if (vpbxSlug) {
    // The portal sends `a_plus_center`, `gesheft`, etc.; our directory stores
    // the slug + its numeric vitalTenantId. Match case-insensitively because
    // slugs can round-trip through UI inputs with weird casing.
    const dir = await db.pbxTenantDirectory.findFirst({
      where: { tenantSlug: vpbxSlug },
      select: { vitalTenantId: true },
    });
    vitalTenantId = dir?.vitalTenantId?.trim() || null;
    // Fallback: some super-admins pass the raw vitalTenantId in the slot too.
    if (!vitalTenantId && /^\d+$/.test(vpbxSlug)) vitalTenantId = vpbxSlug;
  }

  if (!vitalTenantId) {
    return reply.send({
      rows: [], source: "skipped",
      skipReason: vpbxSlug ? `no_directory_entry_for_slug:${vpbxSlug}` : "tenant_not_linked_to_pbx",
    });
  }

  // This opens a MySQL connection to the PBX per request and measured ~2.2s
  // average / 2.8s p95 — the single slowest thing on an IVR Studio page load,
  // and the floor the whole page waits on. Ring groups change when someone
  // makes one, not second to second, so a short shared cache makes every load
  // after the first effectively instant while staying fresh enough that a team
  // created in the Studio shows up right away.
  const result = await pbxReadCache(`ring-groups:${pbxInstance.id}:${vitalTenantId}`, async () => {
    const { listRingGroupsFromOmbutel } = await import("./pbxOmbutelRingGroupList");
    return listRingGroupsFromOmbutel(vitalTenantId!, pbxInstance.ombuMysqlUrlEncrypted);
  });

  if (result.source === "skipped") {
    return reply.send({ rows: [], source: "skipped", skipReason: result.skipReason });
  }
  return reply.send({ rows: result.rows, source: result.source, table: result.table, vitalTenantId });
});

