app.get("/customers/:id/summary", async (req, reply) => {
  const admin = await requirePermission(req, reply, canViewCustomers);
  if (!admin) return;
  const { id } = req.params as { id: string };
  const customer = await db.customer.findFirst({ where: { id, tenantId: admin.tenantId } });
  if (!customer) return reply.status(404).send({ error: "customer_not_found" });

  const customerInvoiceIds = (await db.invoice.findMany({
    where: { tenantId: admin.tenantId, customerId: customer.id },
    select: { id: true }
  })).map((r) => r.id);

  const smsOr = [
    customer.primaryPhone ? { toNumber: customer.primaryPhone } : null,
    customer.whatsappNumber ? { toNumber: customer.whatsappNumber } : null
  ].filter(Boolean) as any[];
  const waOr = [
    { customerId: customer.id },
    customer.whatsappNumber ? { contactNumber: customer.whatsappNumber } : null,
    customer.primaryPhone ? { contactNumber: customer.primaryPhone } : null
  ].filter(Boolean) as any[];
  const [invoiceCounts, invoiceUnpaidSum, recentInvoices, recentInvoiceEvents, recentPaymentEvents, recentSms, whatsappThreads, latestEmailJobs] = await Promise.all([
    db.invoice.groupBy({
      by: ["status"],
      where: { tenantId: admin.tenantId, customerId: customer.id },
      _count: { _all: true }
    }),
    db.invoice.aggregate({
      where: { tenantId: admin.tenantId, customerId: customer.id, status: { in: ["DRAFT", "SENT", "OVERDUE"] } },
      _sum: { amountCents: true }
    }),
    db.invoice.findMany({
      where: { tenantId: admin.tenantId, customerId: customer.id },
      orderBy: { createdAt: "desc" },
      take: 10
    }),
    customerInvoiceIds.length
      ? db.invoiceEvent.findMany({
          where: { tenantId: admin.tenantId, invoiceId: { in: customerInvoiceIds } },
          orderBy: { createdAt: "desc" },
          take: 20
        })
      : Promise.resolve([]),
    customerInvoiceIds.length
      ? db.paymentEvent.findMany({
          where: { tenantId: admin.tenantId, subscriptionId: { in: customerInvoiceIds } },
          orderBy: { receivedAt: "desc" },
          take: 20
        })
      : Promise.resolve([]),
    smsOr.length > 0
      ? db.smsMessage.findMany({
          where: { campaign: { tenantId: admin.tenantId }, OR: smsOr },
          orderBy: { createdAt: "desc" },
          take: 20,
          include: { campaign: { select: { id: true, name: true } } }
        })
      : Promise.resolve([]),
    db.whatsAppThread.findMany({
      where: {
        tenantId: admin.tenantId,
        OR: waOr
      },
      orderBy: { updatedAt: "desc" },
      take: 20
    }),
    (() => {
      const emailOr = [
        customer.primaryEmail ? { toEmail: customer.primaryEmail } : null,
        customerInvoiceIds.length ? { invoiceId: { in: customerInvoiceIds } } : null
      ].filter(Boolean) as any[];
      if (emailOr.length === 0) return Promise.resolve([]);
      return db.emailJob.findMany({
        where: { tenantId: admin.tenantId, OR: emailOr },
        orderBy: { createdAt: "desc" },
        take: 20
      });
    })()
  ]);

  const byStatus: Record<string, number> = { DRAFT: 0, SENT: 0, OVERDUE: 0, PAID: 0, VOID: 0 };
  let totalInvoiceCount = 0;
  for (const row of invoiceCounts) {
    byStatus[row.status] = row._count._all;
    totalInvoiceCount += row._count._all;
  }
  const unpaidCount = (byStatus.DRAFT || 0) + (byStatus.SENT || 0) + (byStatus.OVERDUE || 0);

  return {
    customer,
    invoices: {
      count: totalInvoiceCount,
      unpaidCount,
      unpaidBalanceCents: invoiceUnpaidSum._sum.amountCents || 0,
      byStatus,
      recent: recentInvoices
    },
    recentInvoiceEvents,
    recentPaymentEvents: recentPaymentEvents.map((e) => ({
      id: e.id,
      type: e.type,
      status: e.status,
      amountCents: e.amountCents,
      currency: e.currency,
      createdAt: e.receivedAt
    })),
    smsActivity: {
      totalRecent: recentSms.length,
      latestAt: recentSms[0]?.createdAt || null,
      recent: recentSms.map((m) => ({
        id: m.id,
        campaignId: m.campaignId,
        campaignName: m.campaign?.name || null,
        toNumber: maskValue(m.toNumber, 3, 2),
        status: m.status,
        createdAt: m.createdAt
      }))
    },
    whatsappActivity: {
      threadCount: whatsappThreads.length,
      latestThread: whatsappThreads[0]
        ? {
            id: whatsappThreads[0].id,
            contactNumberMasked: maskValue(whatsappThreads[0].contactNumber, 3, 2),
            lastMessageAt: whatsappThreads[0].lastMessageAt,
            lastStatus: whatsappThreads[0].lastStatus || null
          }
        : null
    },
    emailActivity: latestEmailJobs.map((j) => ({
      id: j.id,
      type: j.type,
      toEmail: maskValue(j.toEmail, 2, 8),
      status: j.status,
      createdAt: j.createdAt,
      sentAt: j.sentAt || null,
      lastErrorCode: j.lastErrorCode || null
    }))
  };
});

const DASHBOARD_CALL_TRAFFIC_CACHE = new Map<string, { at: number; payload: any }>();

function normalizeCallDirection(input: any): "incoming" | "outgoing" | "internal" {
  const numericType = Number(input?.calltype ?? input?.callType ?? input?.type_code ?? input?.direction_code);
  if (numericType === 1) return "internal";
  if (numericType === 2) return "incoming";
  if (numericType === 3) return "outgoing";
  const raw = String(
    input?.direction
      || input?.callDirection
      || input?.disposition
      || input?.call_type
      || input?.type
      || input?.dir
      || ""
  ).toLowerCase();
  if (raw === "internal" || raw === "extension" || raw.includes("internal")) return "internal";
  if (raw === "outgoing" || raw === "outbound" || raw === "out") return "outgoing";
  if (raw === "incoming" || raw === "inbound" || raw === "in") return "incoming";
  // Important: check outbound before inbound. "outgoing" contains "ing", so a
  // broad `includes("in")` test would incorrectly classify outgoing calls.
  if (raw.includes("outbound") || raw.includes("outgoing")) return "outgoing";
  if (raw.includes("inbound") || raw.includes("incoming")) return "incoming";
  return "outgoing";
}

type DashboardCallRange = "today" | "7d" | "30d" | "custom";
type DashboardCallDirection = "incoming" | "outgoing" | "internal";
type DashboardCallDisposition = "answered" | "missed" | "canceled" | "failed" | "unknown";
type DashboardCallActivityPoint = {
  label: string;
  start: string;
  end: string;
  total: number;
  incoming: number;
  outgoing: number;
  internal: number;
  missed: number;
  canceled: number;
};
type DashboardCallActivityAggregate = {
  range: DashboardCallRange;
  timezone: string;
  timeWhere: { gte: Date; lt: Date };
  bucketMinutes: number | null;
  totals: {
    made: number;
    total: number;
    incoming: number;
    outgoing: number;
    internal: number;
    missed: number;
    canceled: number;
  };
  points: DashboardCallActivityPoint[];
  sourceRows: { connectCdr: number; legacyCallRecord: number };
};

function normalizeDashboardDisposition(input: unknown): DashboardCallDisposition {
  const raw = String(input ?? "").trim().toLowerCase();
  if (raw === "answered" || raw === "answer" || raw === "completed") return "answered";
  if (raw === "missed" || raw === "no answer" || raw === "no_answer" || raw === "unanswered") return "missed";
  if (raw === "canceled" || raw === "cancelled" || raw === "busy") return "canceled";
  if (raw === "failed" || raw === "congestion") return "failed";
  return "unknown";
}

function formatDashboardBucketLabel(start: Date, range: DashboardCallRange, timezone: string): string {
  if (range === "7d" || range === "30d" || range === "custom") {
    return start.toLocaleDateString("en-US", { timeZone: timezone, weekday: "short", month: "short", day: "numeric" });
  }
  return start.toLocaleTimeString("en-US", { timeZone: timezone, hour: "numeric", minute: "2-digit" });
}

function resolveDashboardCallRange(
  range: DashboardCallRange,
  nowUtc = new Date(),
  customFrom?: Date | null,
  customTo?: Date | null,
): {
  timezone: string;
  timeWhere: { gte: Date; lt: Date };
  bucketMinutes: number | null;
} {
  const today = computePbxLocalDayRangeUtc(nowUtc);
  if (range === "7d") {
    return {
      timezone: today.timezone,
      timeWhere: {
        gte: new Date(today.dayStartUtc.getTime() - 6 * 24 * 60 * 60 * 1000),
        lt: today.dayEndUtc,
      },
      bucketMinutes: null,
    };
  }
  if (range === "30d") {
    return {
      timezone: today.timezone,
      timeWhere: {
        gte: new Date(today.dayStartUtc.getTime() - 29 * 24 * 60 * 60 * 1000),
        lt: today.dayEndUtc,
      },
      bucketMinutes: null,
    };
  }
  if (range === "custom" && customFrom instanceof Date && customTo instanceof Date && customFrom < customTo) {
    return {
      timezone: today.timezone,
      timeWhere: { gte: customFrom, lt: customTo },
      bucketMinutes: null,
    };
  }
  return { timezone: today.timezone, timeWhere: today.timeWhere, bucketMinutes: 30 };
}

async function aggregateDashboardCallActivity(opts: {
  tenantFilter: Record<string, unknown>;
  extensionFilter?: string[] | null;
  range?: DashboardCallRange;
  customFrom?: Date | null;
  customTo?: Date | null;
  logContext?: Record<string, unknown>;
}): Promise<DashboardCallActivityAggregate> {
  const range = opts.range ?? "today";
  const { timezone, timeWhere, bucketMinutes } = resolveDashboardCallRange(range, new Date(), opts.customFrom ?? null, opts.customTo ?? null);
  const normalizedRows: Array<{
    ts: number;
    direction: DashboardCallDirection;
    disposition: DashboardCallDisposition;
  }> = [];
  let connectCdrSourceRows = 0;
  let legacyCallRecordRows = 0;
  const extensionFilter = opts.extensionFilter ?? [];

  const connectRows = await db.connectCdr.findMany({
    where: {
      ...opts.tenantFilter,
      startedAt: timeWhere,
    },
    select: {
      id: true,
      linkedId: true,
      isForwarded: true,
      startedAt: true,
      direction: true,
      disposition: true,
      fromNumber: true,
      toNumber: true,
      channelsSeen: true,
      dcontextsSeen: true,
      dcontext: true,
    },
    orderBy: { startedAt: "asc" },
    take: 20_000,
  });
  connectCdrSourceRows = connectRows.length;
  const seenConnectCallKeys = new Set<string>();
  for (const row of connectRows) {
    if (row.isForwarded) continue;
    if (extensionFilter.length > 0 && !cdrRowMatchesExtensions(row, extensionFilter)) continue;
    const key = canonicalCdrCallKey(row.linkedId, row.id);
    if (seenConnectCallKeys.has(key)) continue;
    seenConnectCallKeys.add(key);
    const ts = row.startedAt.getTime();
    if (!Number.isFinite(ts)) continue;
    normalizedRows.push({
      ts,
      direction: normalizeCallDirection({ direction: row.direction }),
      disposition: normalizeDashboardDisposition(row.disposition),
    });
  }

  // Legacy fallback only when ConnectCdr has no rows, matching existing behaviour.
  if (connectCdrSourceRows === 0) {
    const legacyRows = await db.callRecord.findMany({
      where: {
        ...opts.tenantFilter,
        startedAt: timeWhere,
      },
      orderBy: { startedAt: "asc" },
      take: 20_000,
    });
    legacyCallRecordRows = legacyRows.length;
    const seenLegacyCallKeys = new Set<string>();
    for (const row of legacyRows) {
      if (extensionFilter.length > 0 && !cdrRowMatchesExtensions(row, extensionFilter)) continue;
      const key = canonicalCdrCallKey((row as any).pbxCallId, row.id);
      if (seenLegacyCallKeys.has(key)) continue;
      seenLegacyCallKeys.add(key);
      const ts = row.startedAt.getTime();
      if (!Number.isFinite(ts)) continue;
      normalizedRows.push({
        ts,
        direction: normalizeCallDirection({ direction: row.direction }),
        disposition: normalizeDashboardDisposition((row as any).disposition ?? (row as any).status),
      });
    }
  }

  const totals = normalizedRows.reduce(
    (acc, row) => {
      acc[row.direction] += 1;
      if (row.direction === "incoming" && row.disposition === "missed") acc.missed += 1;
      if (row.disposition === "canceled") acc.canceled += 1;
      return acc;
    },
    { made: 0, total: 0, incoming: 0, outgoing: 0, internal: 0, missed: 0, canceled: 0 },
  );
  totals.made = totals.incoming + totals.outgoing + totals.internal;
  totals.total = totals.made;

  const points: DashboardCallActivityPoint[] = [];
  const startMs = timeWhere.gte.getTime();
  const endMs = timeWhere.lt.getTime();
  const isDayBucketRange = range === "7d" || range === "30d" || (range === "custom" && bucketMinutes === null);
  if (isDayBucketRange) {
    const msPerDay = 24 * 60 * 60 * 1000;
    const dayCount = Math.max(1, Math.ceil((endMs - startMs) / msPerDay));
    for (let i = 0; i < dayCount; i++) {
      const start = new Date(startMs + i * msPerDay);
      const end = new Date(Math.min(endMs, start.getTime() + msPerDay));
      points.push({
        label: formatDashboardBucketLabel(start, range, timezone),
        start: start.toISOString(),
        end: end.toISOString(),
        total: 0,
        incoming: 0,
        outgoing: 0,
        internal: 0,
        missed: 0,
        canceled: 0,
      });
    }
  } else {
    const msPerBucket = (bucketMinutes ?? 30) * 60 * 1000;
    const bucketCount = Math.max(1, Math.ceil((endMs - startMs) / msPerBucket));
    for (let i = 0; i < bucketCount; i++) {
      const start = new Date(startMs + i * msPerBucket);
      const end = new Date(Math.min(endMs, start.getTime() + msPerBucket));
      points.push({
        label: formatDashboardBucketLabel(start, range, timezone),
        start: start.toISOString(),
        end: end.toISOString(),
        total: 0,
        incoming: 0,
        outgoing: 0,
        internal: 0,
        missed: 0,
        canceled: 0,
      });
    }
  }

  for (const row of normalizedRows) {
    const bucketSizeMs = isDayBucketRange ? 24 * 60 * 60 * 1000 : (bucketMinutes ?? 30) * 60 * 1000;
    const bucketIndex = Math.floor((row.ts - startMs) / bucketSizeMs);
    if (bucketIndex < 0 || bucketIndex >= points.length) continue;
    const point = points[bucketIndex];
    point[row.direction] += 1;
    if (row.direction === "incoming" && row.disposition === "missed") point.missed += 1;
    if (row.disposition === "canceled") point.canceled += 1;
    point.total = point.incoming + point.outgoing + point.internal;
  }

  const pointTotals = points.reduce(
    (acc, p) => {
      acc.incoming += p.incoming;
      acc.outgoing += p.outgoing;
      acc.internal += p.internal;
      acc.missed += p.missed;
      acc.canceled += p.canceled;
      return acc;
    },
    { incoming: 0, outgoing: 0, internal: 0, missed: 0, canceled: 0 },
  );
  if (
    pointTotals.incoming !== totals.incoming ||
    pointTotals.outgoing !== totals.outgoing ||
    pointTotals.internal !== totals.internal ||
    pointTotals.missed !== totals.missed ||
    pointTotals.canceled !== totals.canceled
  ) {
    app.log.warn({ ...opts.logContext, totals, pointTotals, range }, "dashboard_call_activity_aggregation_mismatch");
  } else {
    app.log.debug({ ...opts.logContext, totals, range }, "dashboard_call_activity_aggregation_ok");
  }

  return {
    range,
    timezone,
    timeWhere,
    bucketMinutes,
    totals,
    points,
    sourceRows: { connectCdr: connectCdrSourceRows, legacyCallRecord: legacyCallRecordRows },
  };
}

function extractCallTimestampMs(input: any): number | null {
  const raw = input?.startedAt || input?.start || input?.calldate || input?.createdAt || input?.date || input?.timestamp || input?.end || input?.answeredAt;
  if (!raw) return null;
  if (typeof raw === "number") return raw > 1_000_000_000_000 ? raw : raw * 1000;
  if (typeof raw === "string" && /^\d+$/.test(raw.trim())) {
    const parsed = Number(raw.trim());
    if (Number.isFinite(parsed)) return parsed > 1_000_000_000_000 ? parsed : parsed * 1000;
  }
  const text = String(raw).trim();
  const slashMatch = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (slashMatch) {
    const [, dd, mm, yyyy, hh, min, ss] = slashMatch;
    const ts = Date.UTC(Number(yyyy), Number(mm) - 1, Number(dd), Number(hh), Number(min), Number(ss || "0"));
    return Number.isFinite(ts) ? ts : null;
  }
  const dashMatch = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (dashMatch) {
    const [, yyyy, mm, dd, hh, min, ss] = dashMatch;
    const ts = Date.UTC(Number(yyyy), Number(mm) - 1, Number(dd), Number(hh), Number(min), Number(ss || "0"));
    return Number.isFinite(ts) ? ts : null;
  }
  const ts = new Date(text).getTime();
  return Number.isFinite(ts) ? ts : null;
}

function extractReportItems(report: any): any[] {
  if (Array.isArray(report)) return report;
  const containers = [report, report?.data, report?.result, report?.report, report?.data?.data].filter(Boolean);
  for (const box of containers) {
    if (Array.isArray(box)) return box;
    if (Array.isArray(box?.items)) return box.items;
    if (Array.isArray(box?.rows)) return box.rows;
    if (Array.isArray(box?.records)) return box.records;
    if (Array.isArray(box?.cdr)) return box.cdr;
    if (Array.isArray(box?.cdrs)) return box.cdrs;
    if (Array.isArray(box?.calls)) return box.calls;
    if (Array.isArray(box?.data)) return box.data;
  }
  return [];
}

// ─── CDR tenant rules cache ───────────────────────────────────────────────────
// In-memory cache of CdrTenantRule rows. Refreshed on first use and on every rule write.
let _cdrRulesCache: Array<{ matchType: string; matchValue: string; tenantSlug: string }> | null = null;

async function getCdrTenantRules() {
  if (!_cdrRulesCache) {
    _cdrRulesCache = await db.cdrTenantRule.findMany({
      select: { matchType: true, matchValue: true, tenantSlug: true },
    });
  }
  return _cdrRulesCache;
}

function invalidateCdrRulesCache() {
  _cdrRulesCache = null;
}

/** Resolve a VitalPBX tenantId ("vpbx:{slug}") from CDR numbers using admin-configured rules. */
async function resolveTenantFromRules(fromNumber: string | null, toNumber: string | null): Promise<string | null> {
  const rules = await getCdrTenantRules();
  for (const rule of rules) {
    if (rule.matchType === "did" && toNumber) {
      if (toNumber === rule.matchValue || toNumber.replace(/^\+1/, "") === rule.matchValue) {
        return `vpbx:${rule.tenantSlug}`;
      }
    }
    if (rule.matchType === "from_did" && fromNumber) {
      if (fromNumber === rule.matchValue || fromNumber.replace(/^\+1/, "") === rule.matchValue) {
        return `vpbx:${rule.tenantSlug}`;
      }
    }
    if (rule.matchType === "extension_prefix" && fromNumber) {
      if (fromNumber.startsWith(rule.matchValue)) {
        return `vpbx:${rule.tenantSlug}`;
      }
    }
  }
  return null;
}

// ─── VitalPBX tenant cache for CDR tenant resolution ─────────────────────────
// Caches the VitalPBX tenant list so CDR ingest doesn't hit the API on every call.
// Lookup map keys: lowercased tenant name slug AND numeric tenant ID (both → vpbx:slug).
let _vpbxTenantCache: { entries: Array<{ name: string; numericId: string }>; fetchedAt: number } | null = null;
const VPBX_TENANT_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

async function getVpbxTenantLookup(): Promise<Map<string, string>> {
  const now = Date.now();
  if (!_vpbxTenantCache || now - _vpbxTenantCache.fetchedAt > VPBX_TENANT_CACHE_TTL_MS) {
    try {
      // Use the DB-stored PbxInstance (same approach as /admin/pbx/tenants route)
      const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
      if (!instance) throw new Error("no enabled PbxInstance found");
      const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
      const client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret });
      await syncPbxTenantDirectory(db, instance.id, client).catch((e: any) => {
        app.log.warn({ err: e?.message }, "cdr-ingest: PbxTenantDirectory sync failed (non-fatal)");
      });
      const tenants = await client.listTenants();
      _vpbxTenantCache = {
        entries: tenants
          .filter((t: any) => t && typeof t === "object")
          .map((t: any) => ({
            name: String(t.name || "").trim(),
            numericId: String(t.tenant_id ?? t.id ?? "").trim(),
          }))
          .filter((t: any) => t.name),
        fetchedAt: now,
      };
      app.log.debug({ count: _vpbxTenantCache.entries.length }, "cdr-ingest: VitalPBX tenant cache refreshed");
    } catch (err: any) {
      app.log.warn({ err: err?.message }, "cdr-ingest: VitalPBX tenant cache refresh failed");
      if (!_vpbxTenantCache) return new Map();
    }
  }
  const map = new Map<string, string>();
  for (const t of _vpbxTenantCache!.entries) {
    // Key by lowercased name slug → vpbx:name (preserving original case from VitalPBX)
    if (t.name) map.set(t.name.toLowerCase(), `vpbx:${t.name}`);
    // Key by numeric ID string → same vpbx:name
    if (t.numericId && /^\d+$/.test(t.numericId)) map.set(t.numericId, `vpbx:${t.name}`);
  }
  return map;
}

/** Normalize a string for fuzzy tenant slug matching.
 *  Replaces hyphens with underscores and lowercases — so "Relax-Tires" matches "relax_tires". */
function normSlug(s: string): string {
  return s.toLowerCase().replace(/-/g, "_");
}

/** Try to extract a tenantId (vpbx:slug) from Asterisk channel names using VitalPBX tenant lookup.
 *  VitalPBX names PJSIP endpoints like "{numericTenantId}_{tenantSlug}-{uniqueid}"
 *  e.g. "PJSIP/344822_Comfortone-00003060" → match "344822" or "Comfortone" against tenant list.
 *  Also builds a normalized (hyphen→underscore) lookup to handle naming mismatches. */
function resolveTenantFromChannels(channels: string[], tenantMap: Map<string, string>): string | null {
  // Build normalized slug map (handles hyphen/underscore mismatch in endpoint names)
  const normMap = new Map<string, string>();
  for (const [key, val] of tenantMap) {
    normMap.set(normSlug(key), val);
  }

  for (const channel of channels) {
    const m = /PJSIP\/([^-]+(?:-[^-]+)*?)-[\da-f]{8}/i.exec(channel) ??
              /PJSIP\/([^-]+)-/.exec(channel);
    if (!m) continue;
    const endpoint = m[1]!; // e.g. "344822_Comfortone" or "relax_tires"
    // Try exact lookup first
    const full = tenantMap.get(endpoint.toLowerCase()) ?? normMap.get(normSlug(endpoint));
    if (full) return full;
    // Split by underscore and try each part (handles "{numericId}_{slug}")
    for (const part of endpoint.split("_")) {
      if (!part) continue;
      const hit = tenantMap.get(part.toLowerCase()) ?? normMap.get(normSlug(part));
      if (hit) return hit;
    }
    // Also split by hyphen for endpoint names like "Relax-Tires"
    for (const part of endpoint.split("-")) {
      if (!part) continue;
      const hit = tenantMap.get(part.toLowerCase()) ?? normMap.get(normSlug(part));
      if (hit) return hit;
    }
  }
  return null;
}

/** Try to extract a tenantId (vpbx:slug) from AMI dcontext using VitalPBX tenant list.
 *  VitalPBX names contexts like "ext-local-relax_tires", "from-pstn-relax_tires",
 *  "app-queue-relax_tires", "app-dial-relax_tires", etc.
 *  Strategy: check if the dcontext ends with a known tenant slug (case-insensitive + normalized). */
function resolveTenantFromDcontext(dcontext: string | null | undefined, tenantMap: Map<string, string>): string | null {
  if (!dcontext) return null;

  // Build normalized slug map
  const normMap = new Map<string, string>();
  for (const [key, val] of tenantMap) {
    normMap.set(normSlug(key), val);
  }

  const ctx = dcontext.trim();
  // Check all known VitalPBX context prefixes — slug follows the last "-"
  const VPBX_CTX_PREFIXES = [
    "ext-local-", "from-pstn-", "from-internal-", "from-trunk-",
    "outbound-", "from-external-",
    "app-queue-", "app-dial-", "app-ringgroup-", "app-announcement-",
    "app-followme-", "app-blacklist-", "app-voicemail-", "app-dnd-",
    "macro-dial-exec-",
  ];
  for (const pfx of VPBX_CTX_PREFIXES) {
    if (ctx.toLowerCase().startsWith(pfx)) {
      const slug = ctx.slice(pfx.length).trim();
      if (!slug || /^\d+$/.test(slug)) continue;
      // Try exact match first, then normalized
      const hit = tenantMap.get(slug.toLowerCase()) ?? normMap.get(normSlug(slug));
      if (hit) return hit;
      // Also return direct slug if it looks like a real tenant name (not in tenant list yet)
      if (slug.length > 2) return `vpbx:${slug}`;
    }
  }

  // Fallback: check if any tenant slug appears as the last path segment of the context
  // e.g. "custom-context-relax_tires" → "relax_tires"
  const lastSegment = ctx.split("-").pop() ?? "";
  if (lastSegment.length > 2 && !/^\d+$/.test(lastSegment)) {
    const hit = tenantMap.get(lastSegment.toLowerCase()) ?? normMap.get(normSlug(lastSegment));
    if (hit) return hit;
  }

  return null;
}

// ─── PBX endpoint registration-state ingest ──────────────────────────────────
// Internal endpoint: the telephony service forwards AMI ContactStatus /
// PeerStatus here so we can track per-device PBX registration state (the
// authoritative "is this device Registered at the PBX" signal). Secured by the
// same CDR_INGEST_SECRET header as /internal/cdr-ingest. Drives the device
// registration watchdog, admin dashboard, and Not-Registered alerting.
function parsePbxEndpointName(endpoint: string): {
  pbxTenantNumber: string | null;
  extNumber: string | null;
  isWebrtcDevice: boolean;
} {
  const m = /^T(\d+)_(\d+)(?:_(\d+))?$/i.exec(String(endpoint || "").trim());
  if (!m) return { pbxTenantNumber: null, extNumber: null, isWebrtcDevice: false };
  return {
    pbxTenantNumber: m[1] ?? null,
    extNumber: m[2] ?? null,
    isWebrtcDevice: Boolean(m[3]),
  };
}

app.post("/internal/pbx/contact-status", async (req, reply) => {
  const secret = process.env.CDR_INGEST_SECRET?.trim();
  const incoming = String((req.headers as Record<string, string | undefined>)["x-cdr-secret"] || "").trim();
  if (secret) {
    if (!incoming) return reply.code(401).send({ error: "missing secret" });
    const a = Buffer.from(incoming.padEnd(64, "\0").slice(0, 64));
    const b = Buffer.from(secret.padEnd(64, "\0").slice(0, 64));
    if (!timingSafeEqual(a, b)) {
      app.log.warn({ ip: req.ip, endpoint: "/internal/pbx/contact-status" }, "internal_secret_mismatch");
      return reply.code(403).send({ error: "forbidden" });
    }
  }

  const schema = z.object({
    endpoint: z.string().min(1).max(128),
    status: z.enum(["REGISTERED", "UNREACHABLE", "UNREGISTERED", "UNKNOWN"]),
    rawStatus: z.string().max(64).nullable().optional(),
    contactUri: z.string().max(512).nullable().optional(),
    userAgent: z.string().max(256).nullable().optional(),
    roundtripUsec: z.string().max(32).nullable().optional(),
    tenantId: z.string().max(64).nullable().optional(),
    source: z.string().max(48).optional(),
    statusChanged: z.boolean().optional(),
  });
  const parsed = schema.safeParse(req.body);
  if (!parsed.success) {
    return reply.code(400).send({ error: "invalid payload", issues: parsed.error.issues });
  }
  const d = parsed.data;
  const endpoint = d.endpoint.trim();
  const { pbxTenantNumber, extNumber, isWebrtcDevice } = parsePbxEndpointName(endpoint);

  // Resolve Connect tenant + extension from the canonical PBX device name when possible.
  let tenantId: string | null = d.tenantId ?? null;
  let extensionId: string | null = null;
  try {
    const link = await (db as any).pbxExtensionLink.findFirst({
      where: { pbxDeviceName: endpoint },
      select: { tenantId: true, extensionId: true },
    });
    if (link) {
      tenantId = link.tenantId ?? tenantId;
      extensionId = link.extensionId ?? null;
    }
  } catch { /* resolution is best-effort */ }

  const now = new Date();
  try {
    const prev = await (db as any).pbxEndpointRegistration.findUnique({
      where: { endpoint },
      select: { status: true },
    });
    // The DB previous state is authoritative for whether this is a real
    // transition worth logging to the history table.
    const transition = !prev || prev.status !== d.status;

    await (db as any).pbxEndpointRegistration.upsert({
      where: { endpoint },
      create: {
        endpoint,
        tenantId,
        extensionId,
        pbxTenantNumber,
        extNumber,
        isWebrtcDevice,
        status: d.status,
        rawStatus: d.rawStatus ?? null,
        contactUri: d.contactUri ?? null,
        userAgent: d.userAgent ?? null,
        roundtripUsec: d.roundtripUsec ?? null,
        lastRegisteredAt: d.status === "REGISTERED" ? now : null,
        lastUnreachableAt: d.status === "UNREACHABLE" ? now : null,
        lastUnregisteredAt: d.status === "UNREGISTERED" ? now : null,
        lastEventAt: now,
        source: d.source ?? null,
      },
      update: {
        tenantId,
        extensionId,
        pbxTenantNumber,
        extNumber,
        isWebrtcDevice,
        status: d.status,
        rawStatus: d.rawStatus ?? null,
        contactUri: d.contactUri ?? undefined,
        userAgent: d.userAgent ?? undefined,
        roundtripUsec: d.roundtripUsec ?? undefined,
        ...(d.status === "REGISTERED" ? { lastRegisteredAt: now } : {}),
        ...(d.status === "UNREACHABLE" ? { lastUnreachableAt: now } : {}),
        ...(d.status === "UNREGISTERED" ? { lastUnregisteredAt: now } : {}),
        lastEventAt: now,
        source: d.source ?? undefined,
      },
    });

    // Append an event row only on real transitions to keep the history table lean.
    if (transition) {
      await (db as any).pbxEndpointRegistrationEvent.create({
        data: {
          endpoint,
          tenantId,
          extensionId,
          status: d.status,
          rawStatus: d.rawStatus ?? null,
          contactUri: d.contactUri ?? null,
          userAgent: d.userAgent ?? null,
          details: { source: d.source ?? null, roundtripUsec: d.roundtripUsec ?? null },
        },
      });
    }
  } catch (e: any) {
    app.log.warn({ endpoint, err: e?.message }, "pbx contact-status persist failed");
    return reply.code(500).send({ error: "persist_failed" });
  }
  return { ok: true, endpoint, status: d.status };
});

// ─── Connect CDR ingest ──────────────────────────────────────────────────────
// Internal endpoint: the telephony service POSTs completed call data here.
// No user auth required — secured by a shared CDR_INGEST_SECRET header.
// Performs an upsert by linkedId to prevent duplicate rows.
app.post("/internal/cdr-ingest", async (req, reply) => {
  const secret = process.env.CDR_INGEST_SECRET?.trim();
  const incoming = String((req.headers as Record<string, string | undefined>)["x-cdr-secret"] || "").trim();
  if (!secret) {
    app.log.warn({ endpoint: "/internal/cdr-ingest" }, "CDR_INGEST_SECRET not set — internal endpoint is unauthenticated");
  } else {
    if (!incoming) return reply.code(401).send({ error: "missing secret" });
    // Constant-time compare
    const a = Buffer.from(incoming.padEnd(64, "\0").slice(0, 64));
    const b = Buffer.from(secret.padEnd(64, "\0").slice(0, 64));
    if (!timingSafeEqual(a, b)) {
      app.log.warn({ ip: req.ip, endpoint: "/internal/cdr-ingest" }, "rate_limit_internal_secret_mismatch");
      return reply.code(403).send({ error: "forbidden" });
    }
  }

  const schema = z.object({
    linkedId:    z.string().min(1),
    tenantId:    z.string().nullable().optional(),
    fromNumber:  z.string().nullable().optional(),
    fromName:    z.string().nullable().optional(),
    fromPrefix:  z.string().nullable().optional(),
    toNumber:    z.string().nullable().optional(),
    direction:   z.enum(["incoming", "outgoing", "internal", "unknown"]),
    disposition: z.enum(["answered", "missed", "busy", "failed", "canceled", "unknown"]),
    startedAt:   z.string().datetime(),
    answeredAt:  z.string().datetime().nullable().optional(),
    endedAt:     z.string().datetime(),
    durationSec: z.number().int().min(0).default(0),
    talkSec:     z.number().int().min(0).default(0),
    queueId:     z.string().nullable().optional(),
    hangupCause: z.string().nullable().optional(),
    channels:    z.array(z.string()).optional().default([]),
    dcontext:    z.string().nullable().optional(),
    dcontexts:   z.array(z.string()).optional().default([]),
    accountCode: z.string().nullable().optional(),
    pbxVitalTenantId: z.string().nullable().optional(),
    pbxTenantCode: z.string().nullable().optional(),
    recordingAbsPath: z.string().nullable().optional(),
  });

  const parsed = schema.safeParse(req.body);
  if (!parsed.success) {
    return reply.code(400).send({ error: "invalid payload", issues: parsed.error.issues });
  }
  const d = parsed.data;
  // Detect forwarded call legs: the telephony service (CdrNotifier) appends ":out" or ":outN"
  // when it emits the outbound PSTN leg of a find-me/follow-me / call-forwarding scenario.
  const isForwardedLeg = /:out\d*$/.test(d.linkedId);

  // ── Disposition priority merge (HARDENED, Izzy 2026-07-29) ────────────────
  // The telephony service posts once per completed leg — a multi-device fork
  // produces several posts for the SAME linkedId, and the unanswered devices'
  // legs (NO ANSWER → "missed") can arrive AFTER the answering leg's post.
  // The old last-write-wins update let that late "missed" OVERWRITE an
  // "answered" verdict (live repro 2026-07-29: linkedId 1785376701.138512 —
  // 84s of talk, stored "missed"). Rule: a disposition may only ever get
  // STRONGER. Once any leg answered, the call is answered — no matter which
  // device answered or in what order the leg reports arrive. Voicemail-only
  // calls are unaffected: their every post is already downgraded to "missed"
  // by the telephony classifier, so nothing ever posts "answered" for them.
  const DISP_RANK: Record<string, number> = {
    answered: 6, busy: 5, missed: 4, canceled: 3, failed: 2, unknown: 0,
  };

  const existing = await db.connectCdr.findUnique({ where: { linkedId: d.linkedId } });
  const newDcx = [...(d.dcontexts || []).map((s) => String(s).trim()), d.dcontext ? String(d.dcontext).trim() : ""].filter(Boolean);
  const prevDcx = Array.isArray(existing?.dcontextsSeen) ? (existing!.dcontextsSeen as string[]) : [];
  const mergedDcx = [...new Set([...prevDcx, ...newDcx])];

  const newCh = (d.channels || []).map((s) => String(s).trim()).filter(Boolean);
  const prevCh = Array.isArray(existing?.channelsSeen) ? (existing!.channelsSeen as string[]) : [];
  const mergedCh = [...new Set([...prevCh, ...newCh])];

  const pbxInstance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  let tenantPack = {
    tenantId: null as string | null,
    pbxVitalTenantId: null as string | null,
    pbxTenantCode: null as string | null,
    tenantResolutionSource: null as string | null,
  };
  if (pbxInstance) {
    try {
      const dirCount = await db.pbxTenantDirectory.count({ where: { pbxInstanceId: pbxInstance.id } });
      if (dirCount === 0) {
        const auth = decryptJson<{ token: string; secret?: string }>(pbxInstance.apiAuthEncrypted);
        const client = getVitalPbxClient({ baseUrl: pbxInstance.baseUrl, token: auth.token, secret: auth.secret });
        const { upserted } = await syncPbxTenantDirectory(db, pbxInstance.id, client);
        app.log.info({ upserted }, "cdr-ingest: PbxTenantDirectory bootstrapped (was empty)");
      }
    } catch (err: any) {
      app.log.warn({ err: err?.message }, "cdr-ingest: PbxTenantDirectory bootstrap failed (non-fatal)");
    }
  }

  if (pbxInstance) {
    try {
      tenantPack = await resolveCdrTenant(db, pbxInstance.id, {
        telephonyTenantId: d.tenantId,
        pbxVitalTenantIdHint: d.pbxVitalTenantId ?? null,
        pbxTenantCodeHint: d.pbxTenantCode ?? null,
        dcontexts: mergedDcx,
        channels: mergedCh,
        fromNumber: d.fromNumber,
        toNumber: d.toNumber,
        ruleResolver: () => resolveTenantFromRules(d.fromNumber ?? null, d.toNumber ?? null),
      });
    } catch (err: any) {
      app.log.warn({ err: err?.message }, "cdr-ingest: resolveCdrTenant error (non-fatal)");
    }
  }

  if (!tenantPack.tenantId && d.accountCode && d.accountCode.trim() && !/^\d+$/.test(d.accountCode.trim())) {
    try {
      const tenantMap = await getVpbxTenantLookup();
      const codeSlug = d.accountCode.trim();
      const hit = tenantMap.get(codeSlug.toLowerCase());
      if (hit) {
        tenantPack = {
          tenantId: hit,
          pbxVitalTenantId: tenantPack.pbxVitalTenantId,
          pbxTenantCode: tenantPack.pbxTenantCode,
          tenantResolutionSource: "account_code_slug_map",
        };
      }
    } catch (err: any) {
      app.log.warn({ err: err?.message }, "cdr-ingest: accountCode tenant resolution error (non-fatal)");
    }
  }

  const resolvedDirection = canonicalDirection(d.fromNumber, d.toNumber, d.direction, d.dcontext, {
    dcontexts: mergedDcx,
    channelNames: mergedCh,
    telephonyDirectionHint: d.direction,
  });
  const storedFromName = cleanIncomingCallerNameForTenant(
    d.fromName,
    resolvedDirection,
    [tenantPack.tenantId, d.tenantId, d.pbxTenantCode],
  );

  const lastDcontext = mergedDcx.length > 0 ? mergedDcx[mergedDcx.length - 1]! : d.dcontext ?? null;

  // Recording path: telephony captures MIXMONITOR_FILENAME from AMI (fires around
  // MixMonitor() in the VitalPBX dialplan) and includes the absolute filesystem
  // path on the PBX in the ingest payload.  We store it verbatim — no
  // computation, no PBX query, no directory scan.  On user click to play/
  // download, the stream endpoint turns it into an "<baseUrl>/monitor/<rel>"
  // HTTPS request to VitalPBX.  Null when the call was not recorded.
  const recordingPath: string | null =
    typeof (d as any).recordingAbsPath === "string" &&
    (d as any).recordingAbsPath.trim().length > 0 &&
    d.disposition === "answered" &&
    d.talkSec >= 1
      ? String((d as any).recordingAbsPath).trim()
      : null;

  try {
    const existingCdr = await db.connectCdr.findUnique({
      where: { linkedId: d.linkedId },
      select: { id: true },
    });
    await db.connectCdr.upsert({
      where: { linkedId: d.linkedId },
      create: {
        linkedId:    d.linkedId,
        tenantId:    tenantPack.tenantId,
        pbxVitalTenantId: tenantPack.pbxVitalTenantId,
        pbxTenantCode: tenantPack.pbxTenantCode,
        tenantResolutionSource: tenantPack.tenantResolutionSource,
        fromNumber:  d.fromNumber ?? null,
        fromName:    storedFromName,
        fromPrefix:  d.fromPrefix ?? null,
        toNumber:    d.toNumber ?? null,
        direction:   resolvedDirection,
        disposition: d.disposition,
        startedAt:   new Date(d.startedAt),
        answeredAt:  d.answeredAt ? new Date(d.answeredAt) : null,
        endedAt:     new Date(d.endedAt),
        durationSec: d.durationSec,
        talkSec:     d.talkSec,
        queueId:     d.queueId ?? null,
        hangupCause: d.hangupCause ?? null,
        dcontext:    lastDcontext,
        dcontextsSeen: mergedDcx,
        channelsSeen: mergedCh,
        isForwarded: isForwardedLeg,
        recordingPath,
        rawLegCount: 1,
      },
      update: {
        tenantId:    tenantPack.tenantId != null ? tenantPack.tenantId : undefined,
        pbxVitalTenantId: tenantPack.pbxVitalTenantId != null ? tenantPack.pbxVitalTenantId : undefined,
        pbxTenantCode: tenantPack.pbxTenantCode != null ? tenantPack.pbxTenantCode : undefined,
        tenantResolutionSource: tenantPack.tenantResolutionSource != null ? tenantPack.tenantResolutionSource : undefined,
        fromNumber:  d.fromNumber ?? undefined,
        fromName:    d.fromName !== undefined ? storedFromName : undefined,
        fromPrefix:  d.fromPrefix ?? undefined,
        toNumber:    d.toNumber ?? undefined,
        direction:   resolvedDirection !== "unknown" ? resolvedDirection : undefined,
        disposition: (() => {
          if (d.disposition === "unknown") return undefined;
          const prev = existing?.disposition ?? null;
          if (prev && (DISP_RANK[prev] ?? 0) >= (DISP_RANK[d.disposition] ?? 0)) {
            if (prev === "answered" && d.disposition === "missed") {
              app.log.info(
                { linkedId: d.linkedId, prev, incoming: d.disposition },
                "cdr-ingest: blocked missed-downgrade of answered call (late unanswered fork leg)",
              );
            }
            return undefined; // keep the stronger existing verdict
          }
          return d.disposition;
        })(),
        answeredAt:  d.answeredAt ? new Date(d.answeredAt) : undefined,
        durationSec: d.durationSec > 0 ? d.durationSec : undefined,
        talkSec:     d.talkSec > 0 ? d.talkSec : undefined,
        queueId:     d.queueId ?? undefined,
        hangupCause: d.hangupCause ?? undefined,
        dcontext:    lastDcontext ?? undefined,
        dcontextsSeen: mergedDcx,
        channelsSeen: mergedCh,
        ...(recordingPath ? { recordingPath } : {}),
        rawLegCount: { increment: 1 },
      },
    });
    // ── CRM CDR hook — fire-and-forget, never blocks CDR ingest ──────────────
    if (tenantPack.tenantId) {
      fireCrmCdrHook({
        linkedId: d.linkedId,
        tenantId: tenantPack.tenantId,
        fromNumber: d.fromNumber ?? null,
        toNumber: d.toNumber ?? null,
        direction: resolvedDirection,
        disposition: d.disposition,
        durationSec: d.durationSec,
        talkSec: d.talkSec,
        recordingAvailable: recordingPath !== null,
        startedAt: new Date(d.startedAt),
      }).catch(() => {}); // fire-and-forget — CDR ingest must never be affected
    }

    if (process.env.CDR_PIPELINE_DIAG?.trim() === "1") {
      app.log.info(
        {
          phase: "cdr_ingest_persisted",
          linkedId: d.linkedId,
          tenantId: tenantPack.tenantId,
          pbxVitalTenantId: tenantPack.pbxVitalTenantId,
          tenantResolutionSource: tenantPack.tenantResolutionSource,
          rawDirection: d.direction,
          direction: resolvedDirection,
          directionOverridden: resolvedDirection !== d.direction,
          fromNumber: d.fromNumber ?? null,
          toNumber: d.toNumber ?? null,
          startedAt: d.startedAt,
        },
        "cdr_pipeline_diag"
      );
    }
    if (!existingCdr && tenantPack.tenantId && resolvedDirection === "incoming" && d.disposition === "missed") {
      const targetExt = String(d.toNumber || "").trim();
      const ext = targetExt
        ? await db.extension.findFirst({
            where: { tenantId: tenantPack.tenantId, extNumber: targetExt, status: "ACTIVE", ownerUserId: { not: null } },
            select: { id: true, ownerUserId: true },
          })
        : null;
      if (
        ext?.ownerUserId &&
        (await claimNotification(db as any, {
          type: "missed_call",
          entityId: String(d.linkedId),
          userId: ext.ownerUserId,
          tenantId: tenantPack.tenantId,
          source: "fastpath:cdr-ingest",
        }))
      ) {
        await sendPushToUserDevices({
          tenantId: tenantPack.tenantId,
          userId: ext.ownerUserId,
          payload: {
            type: "missed_call",
            callId: d.linkedId,
            tenantId: tenantPack.tenantId,
            extensionId: ext.id,
            recipientUserId: ext.ownerUserId,
            callerNumber: d.fromNumber || "Unknown caller",
            callerNameOrNumber: d.fromName || d.fromNumber || "Unknown caller",
            timestamp: new Date().toISOString(),
          },
        }).catch((err: any) => app.log.warn({ err: err?.message, linkedId: d.linkedId }, "missed-call-push: failed"));
      }
    }

    // ── Channel-based outbound PSTN leg detection ─────────────────────────────
    // VitalPBX does not reliably emit AMI CDR events, so the CDR-event-based path
    // in the telephony service never fires.  Instead we detect outbound PSTN legs
    // directly from channelsSeen: when a ring-group, virtual extension, or follow-me
    // dials an external number, Asterisk creates a Local channel whose first segment
    // encodes the dialled PSTN number and whose context segment identifies the
    // outbound dial route.
    //
    // Pattern:  Local/{7+digits}@T{n}_{cos-*|ext-local*|from-internal*|outbound*}-{hex}[;n]
    //
    // This runs for every ingest call (even updates) but uses upsert, so it is
    // idempotent — re-ingest of the same linkedId will not duplicate the :out row.
    if (resolvedDirection === "incoming" && mergedCh.length > 0) {
      const outNumbers = new Map<string, string>(); // normalised number → context base
      for (const ch of mergedCh) {
        if (!ch.startsWith("Local/")) continue;
        const atIdx = ch.indexOf("@");
        if (atIdx < 0) continue;
        const numPart = ch.slice("Local/".length, atIdx);
        if (!/^\d{7,}$/.test(numPart)) continue;
        const ctxRaw = ch.slice(atIdx + 1); // "T8_cos-all-0000243e;1"
        // Only treat as an outbound PSTN dial when the context is an outbound route context
        if (!/^T\d+_(?:cos-|ext-local|from-internal|outbound)/i.test(ctxRaw)) continue;
        const normNum = numPart.replace(/^1(\d{10})$/, "$1");
        if (!outNumbers.has(normNum)) {
          // Strip hex suffix to get the clean context name  e.g. "T8_cos-all"
          const ctxBase = ctxRaw.replace(/-[0-9a-f]+(?:;\d+)?$/i, "").replace(/-[0-9a-f]+$/i, "");
          outNumbers.set(normNum, ctxBase);
        }
      }
      let outIdx = 0;
      for (const [outNum, outCtx] of outNumbers) {
        const suffix = outIdx === 0 ? ":out" : `:out${outIdx}`;
        outIdx++;
        const outLinkedId = d.linkedId + suffix;
        try {
          const existingOut = await db.connectCdr.findUnique({ where: { linkedId: outLinkedId } });
          await db.connectCdr.upsert({
            where:  { linkedId: outLinkedId },
            create: {
              linkedId:               outLinkedId,
              tenantId:               tenantPack.tenantId,
              pbxVitalTenantId:       tenantPack.pbxVitalTenantId,
              pbxTenantCode:          tenantPack.pbxTenantCode,
              tenantResolutionSource: "channel_outbound_leg",
              fromNumber:             d.toNumber ?? null,  // DID is the outbound caller-ID
              toNumber:               outNum,
              direction:              "outgoing",
              disposition:            d.disposition,
              startedAt:              new Date(d.startedAt),
              answeredAt:             d.answeredAt ? new Date(d.answeredAt) : null,
              endedAt:                new Date(d.endedAt),
              durationSec:            d.talkSec,
              talkSec:                d.talkSec,
              queueId:                null,
              hangupCause:            null,
              dcontext:               outCtx,
              dcontextsSeen:          [outCtx],
              channelsSeen:           mergedCh,
              isForwarded:            true,
              rawLegCount:            0,
            },
            update: {
              disposition:  d.disposition !== "unknown" ? d.disposition : undefined,
              answeredAt:   d.answeredAt ? new Date(d.answeredAt) : undefined,
              durationSec:  d.talkSec > 0 ? d.talkSec : undefined,
              talkSec:      d.talkSec > 0 ? d.talkSec : undefined,
              channelsSeen: mergedCh,
            },
          });
          if (!existingOut) {
            app.log.info(
              { linkedId: outLinkedId, to: outNum, tenant: tenantPack.tenantId, ctx: outCtx },
              "cdr-ingest: channel-based outbound-pstn-leg created",
            );
          }
        } catch (outErr: any) {
          app.log.warn({ linkedId: outLinkedId, err: outErr?.message }, "cdr-ingest: outbound-leg upsert failed (non-fatal)");
        }
      }
    }

    return reply.code(200).send({ ok: true });
  } catch (err: any) {
    app.log.error({ linkedId: d.linkedId, err: err?.message }, "cdr-ingest: db error");
    return reply.code(500).send({ error: "db_error" });
  }
});

// ─── PBX Observability — Phase 1 event ingest (READ-ONLY diagnostics) ─────────
// Internal endpoint: the (future, flag-gated) telephony collector POSTs batches of
// already-mapped PBX events here. This NEVER writes back to the PBX/AstDB/ombutel —
// it only persists normalized, redacted events into the PbxEvent table.
//
// Safety:
//   - Disabled unless PBX_EVENT_INGEST_ENABLED is explicitly truthy (default OFF).
//   - Secret-authenticated via PBX_EVENT_INGEST_SECRET (x-pbx-event-secret header),
//     same constant-time pattern as /internal/cdr-ingest.
//   - Redaction-before-insert + payload/batch limits live in ./pbxEventIngest.
//   - Idempotent: createMany(skipDuplicates) on the unique eventKey.
app.post("/internal/pbx-event-ingest", async (req, reply) => {
  // Default-off kill switch — the collector is not enabled in Phase 1 Step 0/1.
  if (!isPbxEventIngestEnabled(process.env)) {
    return reply.code(404).send({ error: "disabled" });
  }

  const secret = process.env[PBX_EVENT_INGEST_SECRET_ENV]?.trim();
  const incoming = String(
    (req.headers as Record<string, string | undefined>)["x-pbx-event-secret"] || "",
  ).trim();
  if (!secret) {
    app.log.warn(
      { endpoint: "/internal/pbx-event-ingest" },
      "PBX_EVENT_INGEST_SECRET not set — refusing ingest while enabled",
    );
    return reply.code(503).send({ error: "secret_not_configured" });
  }
  if (!incoming) return reply.code(401).send({ error: "missing secret" });
  const a = Buffer.from(incoming.padEnd(64, "\0").slice(0, 64));
  const b = Buffer.from(secret.padEnd(64, "\0").slice(0, 64));
  if (!timingSafeEqual(a, b)) {
    app.log.warn(
      { ip: req.ip, endpoint: "/internal/pbx-event-ingest" },
      "pbx_event_ingest_secret_mismatch",
    );
    return reply.code(403).send({ error: "forbidden" });
  }

  const normalized = normalizePbxEventBatch(req.body);
  if (!normalized.ok) {
    return reply.code(400).send({ error: normalized.error, issues: normalized.issues });
  }

  try {
    const result = await db.pbxEvent.createMany({
      // Prisma nullable Json columns need Prisma.JsonNull, not a literal JS null.
      data: normalized.rows.map((r) => ({
        ...r,
        metadata: r.metadata == null ? Prisma.JsonNull : (r.metadata as Prisma.InputJsonValue),
      })),
      skipDuplicates: true, // idempotent re-delivery
    });
    return reply.code(200).send({
      ok: true,
      received: normalized.received,
      stored: result.count,
      dedupedInBatch: normalized.deduped,
    });
  } catch (err: any) {
    app.log.error({ err: err?.message }, "pbx-event-ingest: db error");
    return reply.code(500).send({ error: "db_error" });
  }
});

// ── Ring-vs-cancel race guard for /internal/mobile-ring-notify ───────────────
// Live failure (Trimpro T11, invite cms7ms72g4k5lof13ww3pq95i, 2026-07-30
// 14:50:46): the PBX had zero registered contacts, diverted the call to
// voicemail instantly, and telephony's "ringing" and "hungup" notifies raced.
// The cancel path canceled the freshly created invite and pushed
// INVITE_CANCELED at .060; the still-running ring path (delayed by the
// INCOMING_CALL_WAKE send) pushed INCOMING_CALL at .301. The device processed
// cancel (no-op) then ring — full ringtone for a dead call, Answer tap into
// nothing, no cancel ever coming. Two guarantees below (single API process,
// in-memory state is authoritative):
//   1. serializeMobileRingNotify: ring and cancel processing for one pbxCallId
//      never interleave, so a cancel that arrives mid-ring waits and its
//      INVITE_CANCELED push always post-dates the INCOMING_CALL push.
//   2. Cancel tombstones: once a cancel for a pbxCallId is processed, a ring
//      notify for that same (unique-per-call) id is dead on arrival — covers
//      the opposite ordering where the cancel fully completes first, finds no
//      invite to cancel, and the late ring would otherwise ring unopposed.
const mobileRingNotifyChains = new Map<string, Promise<void>>();
function serializeMobileRingNotify<T>(pbxCallId: string, fn: () => Promise<T>): Promise<T> {
  const prev = mobileRingNotifyChains.get(pbxCallId) ?? Promise.resolve();
  const run = prev.then(fn, fn);
  const tail: Promise<void> = run.then(() => undefined, () => undefined);
  mobileRingNotifyChains.set(pbxCallId, tail);
  void tail.then(() => {
    if (mobileRingNotifyChains.get(pbxCallId) === tail) mobileRingNotifyChains.delete(pbxCallId);
  });
  return run;
}

const canceledPbxCallTombstones = new Map<string, number>();
const CANCELED_PBX_CALL_TOMBSTONE_TTL_MS = 10 * 60_000;
function markPbxCallCanceled(pbxCallId: string): void {
  const now = Date.now();
  canceledPbxCallTombstones.set(pbxCallId, now);
  if (canceledPbxCallTombstones.size > 2000) {
    for (const [k, at] of canceledPbxCallTombstones) {
      if (now - at > CANCELED_PBX_CALL_TOMBSTONE_TTL_MS) canceledPbxCallTombstones.delete(k);
    }
  }
}
function wasPbxCallCanceled(pbxCallId: string): boolean {
  const at = canceledPbxCallTombstones.get(pbxCallId);
  if (at == null) return false;
  if (Date.now() - at > CANCELED_PBX_CALL_TOMBSTONE_TTL_MS) {
    canceledPbxCallTombstones.delete(pbxCallId);
    return false;
  }
  return true;
}

// Internal: telephony service POSTs when an inbound call rings at an extension.
// Creates a CallInvite and sends an Expo push to the owner's mobile devices.
// Secured by the same CDR_INGEST_SECRET shared header.
app.post("/internal/mobile-ring-notify", async (req, reply) => {
  const secret = process.env.CDR_INGEST_SECRET?.trim();
  const incoming = String((req.headers as Record<string, string | undefined>)["x-cdr-secret"] || "").trim();
  if (!secret) {
    app.log.warn({ endpoint: "/internal/mobile-ring-notify" }, "CDR_INGEST_SECRET not set — internal endpoint is unauthenticated");
  } else {
    if (!incoming) return reply.code(401).send({ error: "missing secret" });
    const a = Buffer.from(incoming.padEnd(64, "\0").slice(0, 64));
    const b = Buffer.from(secret.padEnd(64, "\0").slice(0, 64));
    if (!timingSafeEqual(a, b)) {
      app.log.warn({ ip: req.ip, endpoint: "/internal/mobile-ring-notify" }, "rate_limit_internal_secret_mismatch");
      return reply.code(403).send({ error: "forbidden" });
    }
  }

  const input = z.object({
    linkedId: z.string().min(1),
    toExtension: z.string().min(0).optional().default(""),
    fromNumber: z.string().nullable().optional(),
    fromDisplay: z.string().nullable().optional(),
    fromPrefix: z.string().nullable().optional(),
    connectTenantId: z.string().nullable().optional(),
    pbxVitalTenantId: z.string().nullable().optional(),
    state: z.enum(["ringing", "hungup", "diverted_to_voicemail", "answered_elsewhere"]).optional(),
    /** When state is hungup, optional override for INVITE_CANCELED `reason` (default pbx_hangup). */
    cancelReason: z.string().max(120).optional().nullable(),
    /** True when a tenant extension leg answered (desk phone / other endpoint) — suppresses the missed-call alert. */
    answered: z.boolean().optional(),
  }).parse(req.body || {});
  const cleanedFromDisplay = cleanIncomingCallerNameForTenant(
    input.fromDisplay,
    "incoming",
    [input.connectTenantId, input.pbxVitalTenantId],
  );

  app.log.info(
    { linkedId: input.linkedId, toExtension: input.toExtension, connectTenantId: input.connectTenantId, state: input.state || "ringing" },
    "mobile-ring-notify: received"
  );

  // ── Hangup / voicemail-divert fast-path: cancel any PENDING invite for this
  // pbxCallId and push INVITE_CANCELED so the native ringtone stops immediately.
  // Runs under the per-call lock so it can never interleave with the ring path
  // for the same call (see the race-guard comment above the endpoint).
  if (input.state === "hungup" || input.state === "diverted_to_voicemail" || input.state === "answered_elsewhere") {
    return serializeMobileRingNotify(input.linkedId, async () => {
    // pbxCallId (Asterisk linkedid) is unique per call, so any ring notify for
    // this id that arrives from here on is stale — tombstone it permanently.
    markPbxCallCanceled(input.linkedId);
    const pending = await db.callInvite.findMany({
      where: {
        pbxCallId: input.linkedId,
        status: "PENDING",
      },
    });
    if (!pending.length) {
      app.log.info({ linkedId: input.linkedId, state: input.state }, "mobile-ring-notify: stop — no pending invites");
      return { ok: true, hungup: true, canceled: 0 };
    }
    const nowIso = new Date().toISOString();
    let canceled = 0;
    for (const inv of pending) {
      await db.callInvite.update({
        where: { id: inv.id },
        data: { status: "CANCELED", canceledAt: new Date() },
      });
      canceled += 1;
      const terminationReason =
        input.state === "diverted_to_voicemail"
          ? "diverted_to_voicemail"
          : input.state === "answered_elsewhere"
            ? "answered_elsewhere"
            : (input.cancelReason?.trim() || "pbx_hangup");
      try {
        await sendPushToUserDevices({
          tenantId: inv.tenantId,
          userId: inv.userId,
          payload: {
            type: "INVITE_CANCELED",
            inviteId: inv.id,
            pbxCallId: inv.pbxCallId,
            reason: terminationReason,
            tenantId: inv.tenantId,
            timestamp: nowIso,
          },
        });
      } catch (err: any) {
        app.log.warn({ err: err?.message, inviteId: inv.id }, "mobile-ring-notify: hangup push failed");
      }
      // User-visible missed-call alert. This fast-path is the cancel route real
      // calls actually take (the pbx-event/poll paths are fallbacks), and it
      // historically never recorded the missed outcome — so no alert ever
      // fired for calls whose ring ended here. `answered` (extension leg
      // answered on a desk phone / other endpoint) suppresses the alert:
      // those are not missed calls.
      if (!input.answered) {
        await createMissedCallRecordForInvite(
          inv,
          input.state === "diverted_to_voicemail" ? "MISSED" : "CANCELED",
        ).catch((err: any) =>
          app.log.warn({ err: err?.message, inviteId: inv.id }, "mobile-ring-notify: missed-call record/alert failed"),
        );
      }
    }
    app.log.info({ linkedId: input.linkedId, canceled, answered: !!input.answered }, "mobile-ring-notify: hangup — invites canceled + push sent");
    return { ok: true, hungup: true, canceled };
    });
  }

  if (!input.toExtension) {
    return reply.code(400).send({ error: "toExtension required for ringing state" });
  }

  // ── Resolve the extension owner ──────────────────────────────────────────────
  // Fast path: use the Connect tenantId the telephony service already resolved.
  let target: { tenantId: string; userId: string; extensionId: string | null; sipDomain: string | null } | null = null;

  if (input.connectTenantId) {
    const ext = await db.extension.findFirst({
      where: {
        tenantId: input.connectTenantId,
        extNumber: input.toExtension,
        status: "ACTIVE",
      },
      include: {
        tenant: { select: { sipDomain: true } },
      },
    });
    if (ext) {
      let resolvedUserId: string | null = ext.ownerUserId ?? null;
      if (!resolvedUserId) {
        const pairedDevice = await db.mobileDevice.findFirst({
          where: {
            tenantId: ext.tenantId,
            extensionId: ext.id,
            active: true,
          } as any,
          orderBy: { lastSeenAt: "desc" } as any,
          select: { userId: true } as any,
        });
        const pairedUserId = pairedDevice?.userId as unknown;
        resolvedUserId = typeof pairedUserId === "string" && pairedUserId.length > 0 ? pairedUserId : null;
        if (resolvedUserId) {
          app.log.info(
            { linkedId: input.linkedId, toExtension: input.toExtension, connectTenantId: input.connectTenantId, extensionId: ext.id, resolvedUserId },
            "mobile-ring-notify: resolved target via active extension-paired device",
          );
        }
      }
      if (resolvedUserId) {
      target = {
        tenantId: ext.tenantId,
          userId: resolvedUserId,
        extensionId: ext.id,
        sipDomain: ext.tenant?.sipDomain ?? null,
      };
      }
    }
  }

  // Fallback: use the existing pbxTenantId-based resolver.
  if (!target) {
    const fakeEvt: NormalizedWirePbxEvent = {
      eventType: "telephony-ring",
      state: "RINGING",
      pbxCallId: input.linkedId,
      toExtension: input.toExtension,
      fromNumber: input.fromNumber || "unknown",
      fromDisplay: input.fromDisplay || undefined,
      timestamp: new Date().toISOString(),
      pbxTenantId: input.pbxVitalTenantId || undefined,
    };
    const resolved = await resolvePbxEventTarget(fakeEvt);
    if (resolved) {
      target = { tenantId: resolved.tenantId, userId: resolved.userId, extensionId: resolved.extensionId, sipDomain: resolved.sipDomain ?? null };
    }
  }

  if (!target) {
    app.log.warn(
      { linkedId: input.linkedId, toExtension: input.toExtension, connectTenantId: input.connectTenantId },
      "mobile-ring-notify: extension owner not found — no push sent"
    );
    return { ok: false, reason: "TARGET_NOT_FOUND" };
  }

  // ── Contact-name resolution (Izzy 2026-07-30) ────────────────────────────────
  // A saved contact's name beats carrier CNAM ("WIRELESS CALLER") on every
  // incoming-call surface — full-screen, floating notification, lock screen,
  // in-app — because they all render this invite's fromDisplay. Lean lookup:
  // one indexed query on the tenant's contact phone numbers (last-10 match).
  let resolvedFromDisplay = cleanedFromDisplay;
  try {
    const digits = String(input.fromNumber || "").replace(/\D/g, "");
    if (digits.length >= 7) {
      const cp = await db.contactPhone.findFirst({
        where: {
          contact: { tenantId: target.tenantId, active: true, archivedAt: null },
          numberNormalized: { endsWith: digits.slice(-10) },
        },
        include: { contact: { select: { displayName: true, firstName: true, lastName: true, company: true } } },
      });
      const c = cp?.contact;
      const contactName = (c?.displayName || [c?.firstName, c?.lastName].filter(Boolean).join(" ") || c?.company || "").trim();
      if (contactName) {
        resolvedFromDisplay = contactName;
        app.log.info(
          { linkedId: input.linkedId, fromNumber: input.fromNumber },
          "mobile-ring-notify: caller resolved to tenant contact"
        );
      }
    }
  } catch (err: any) {
    app.log.warn({ err: err?.message }, "mobile-ring-notify: contact resolution failed (non-fatal)");
  }

  // Everything from invite creation to the INCOMING_CALL push runs under the
  // per-call lock: a concurrent cancel notify for this call queues behind us,
  // so its INVITE_CANCELED push always post-dates our INCOMING_CALL push.
  const resolvedTarget = target;
  return serializeMobileRingNotify(input.linkedId, async () => {
  const target = resolvedTarget;

  // Ring-after-cancel guard: the hangup notify for this call already ran to
  // completion (possibly before we created any invite for it to cancel). This
  // ring is for a dead call — pushing it would ring the device with no cancel
  // ever coming.
  if (wasPbxCallCanceled(input.linkedId)) {
    app.log.warn(
      { linkedId: input.linkedId, toExtension: input.toExtension, connectTenantId: input.connectTenantId },
      "mobile-ring-notify: ring notify arrived after cancel for the same call — suppressed",
    );
    return { ok: true, suppressed: "ring_after_cancel" };
  }

  // ── Upsert CallInvite (unique on tenantId+pbxCallId) ─────────────────────────
  const existingInvite = await db.callInvite.findFirst({
    where: { tenantId: target.tenantId, pbxCallId: input.linkedId },
    orderBy: { createdAt: "desc" },
  });

  if (existingInvite && existingInvite.status === "PENDING" && existingInvite.expiresAt > new Date()) {
    app.log.info({ inviteId: existingInvite.id }, "mobile-ring-notify: invite already active — skipping");
    return { ok: true, deduped: true, inviteId: existingInvite.id };
  }

  const invite = existingInvite
    ? await db.callInvite.update({
        where: { id: existingInvite.id },
        data: {
          userId: target.userId,
          extensionId: target.extensionId,
          fromNumber: input.fromNumber || "unknown",
          fromDisplay: resolvedFromDisplay,
          fromPrefix: input.fromPrefix ?? null,
          toExtension: input.toExtension,
          status: "PENDING",
          expiresAt: new Date(Date.now() + 45_000),
          acceptedAt: null,
          declinedAt: null,
          canceledAt: null,
          acceptedByDeviceId: null,
        },
      })
    : await db.callInvite.create({
        data: {
          tenantId: target.tenantId,
          userId: target.userId,
          extensionId: target.extensionId,
          pbxCallId: input.linkedId,
          fromNumber: input.fromNumber || "unknown",
          fromDisplay: resolvedFromDisplay,
          fromPrefix: input.fromPrefix ?? null,
          toExtension: input.toExtension,
          status: "PENDING",
          expiresAt: new Date(Date.now() + 45_000),
        },
      });

  // ── Send Expo push to all registered devices for this user ───────────────────
  const wakeRequestedAt = new Date().toISOString();
  try {
    await sendPushToUserDevices({
      tenantId: target.tenantId,
      userId: target.userId,
      payload: {
        type: "INCOMING_CALL_WAKE",
        pbxCallId: invite.pbxCallId ?? input.linkedId,
        fromNumber: invite.fromNumber,
        fromDisplay: invite.fromDisplay,
        fromPrefix: invite.fromPrefix,
        toExtension: invite.toExtension,
        tenantId: target.tenantId,
        pbxVitalTenantId: input.pbxVitalTenantId,
        timestamp: wakeRequestedAt,
        wakeRequestedAt,
      },
    });
    await recordWakeEvent({
      tenantId: target.tenantId,
      pbxCallId: invite.pbxCallId ?? input.linkedId,
      stage: "WAKE_PUSH_QUEUED",
      source: "api",
      userId: target.userId,
      extensionId: target.extensionId,
      details: { path: "mobile_ring_notify" },
    });
  } catch (err: any) {
    app.log.warn(
      { err: err?.message, inviteId: invite.id, pbxCallId: invite.pbxCallId },
      "mobile-ring-notify: INCOMING_CALL_WAKE failed (non-fatal)",
    );
  }

  // The wake push + wake-event write above take real time (the observed race
  // window was 241ms). The lock protects against the cancel path in THIS
  // endpoint; this re-read also covers every other path that can terminate an
  // invite (worker, pbx-event ingest, expiry). Never push INCOMING_CALL for an
  // invite that is no longer PENDING.
  const inviteNow = await db.callInvite.findUnique({
    where: { id: invite.id },
    select: { status: true },
  });
  if (!inviteNow || inviteNow.status !== "PENDING") {
    app.log.warn(
      { inviteId: invite.id, pbxCallId: invite.pbxCallId, status: inviteNow?.status ?? "MISSING" },
      "mobile-ring-notify: invite went terminal before INCOMING_CALL push — suppressed",
    );
    return { ok: true, suppressed: "invite_terminal_before_ring_push", inviteId: invite.id };
  }

  const push = await sendPushToUserDevices({
    tenantId: target.tenantId,
    userId: target.userId,
    payload: {
      type: "INCOMING_CALL",
      inviteId: invite.id,
      fromNumber: invite.fromNumber,
      fromDisplay: invite.fromDisplay,
      fromPrefix: invite.fromPrefix,
      toExtension: invite.toExtension,
      pbxCallId: invite.pbxCallId,
      sipCallTarget: invite.sipCallTarget,
      pbxSipUsername: invite.pbxSipUsername,
      tenantId: target.tenantId,
      timestamp: new Date().toISOString(),
    },
  });

  app.log.info(
    { inviteId: invite.id, tenantId: target.tenantId, userId: target.userId, push },
    "mobile-ring-notify: push sent"
  );

  await audit({
    tenantId: target.tenantId,
    action: "PBX_CALL_INVITE_TELEPHONY",
    entityType: "CallInvite",
    entityId: invite.id,
    actorUserId: target.userId,
  });

  return { ok: true, inviteId: invite.id, push };
  });
});

// ─── Inbound pre-wake (server-side; no PBX changes, every tenant) ────────────
// Fired by the telephony service the MOMENT an inbound call is OBSERVED for a
// known tenant — BEFORE the extension is dialed.
//
// Why this exists: when every mobile app on the target extension is asleep
// (SIP unregistered), VitalPBX's Dial() finds zero contacts and drops the call
// to voicemail in ~2s. No ringing leg is ever created, so Connect's normal
// observed-ring wake (/internal/mobile-ring-notify) never fires — the call
// dies before any device can be woken. The only lever that does NOT touch the
// PBX, inbound routes, or dialplan is to wake the tenant's asleep devices the
// instant the call is seen (while the caller is still in the IVR greeting), so
// they re-register before the extension is dialed and the call rings normally.
//
// Strictly ADDITIVE and side-effect-free with respect to call routing:
//   • Sends ONLY caller-less INCOMING_CALL_WAKE data pushes — identical to the
//     proven /admin/mobile/devices/:id/force-reregister path. The native app
//     suppresses the heads-up when caller info is absent, so there is no
//     user-visible ring from this; it just kicks SIP re-registration.
//   • Never creates/cancels a CallInvite, never redirects/originates a call,
//     never writes to the PBX. If it does nothing, behavior is exactly as before.
//   • Targets only devices that look ASLEEP (stale lastSeenAt) so already-online
//     phones are left untouched — this is what makes the multi-device case work
//     (the registered sibling is skipped; the asleep sibling is woken).
//
// Body (JSON):
//   linkedId          — MANDATORY — PBX linkedid (dedup + wake-event correlation)
//   connectTenantId   — OPTIONAL — Connect tenantId (preferred)
//   pbxVitalTenantId  — OPTIONAL — VitalPBX tenant code (e.g. "T5") fallback
//   toExtension       — OPTIONAL — if already known, wake only that ext's owner
//
// Auth: same x-cdr-secret header as the rest of /internal/*.
const PREWAKE_USER_COOLDOWN_MS = Number.parseInt(process.env.PBX_PREWAKE_USER_COOLDOWN_MS ?? "12000", 10) || 12_000;
const PREWAKE_DEVICE_STALE_MS = Number.parseInt(process.env.PBX_PREWAKE_DEVICE_STALE_MS ?? "45000", 10) || 45_000;
const PREWAKE_MAX_USERS = Number.parseInt(process.env.PBX_PREWAKE_MAX_USERS ?? "25", 10) || 25;
// In-memory per-(tenant,user) cooldown so repeated upserts for the same call —
// or a burst of inbound calls — don't fan out wake pushes every few hundred ms.
const prewakeUserCooldown = new Map<string, number>();
function prewakeCooldownGate(tenantId: string, userId: string): boolean {
  const key = `${tenantId}:${userId}`;
  const now = Date.now();
  const last = prewakeUserCooldown.get(key) ?? 0;
  if (now - last < PREWAKE_USER_COOLDOWN_MS) return false;
  prewakeUserCooldown.set(key, now);
  // Opportunistic GC so the map can't grow unbounded on a busy PBX.
  if (prewakeUserCooldown.size > 5000) {
    for (const [k, ts] of prewakeUserCooldown) {
      if (now - ts > PREWAKE_USER_COOLDOWN_MS * 4) prewakeUserCooldown.delete(k);
    }
  }
  return true;
}

app.post("/internal/mobile-prewake", async (req, reply) => {
  const secret = process.env.CDR_INGEST_SECRET?.trim();
  const incoming = String((req.headers as Record<string, string | undefined>)["x-cdr-secret"] || "").trim();
  if (!secret) {
    app.log.warn({ endpoint: "/internal/mobile-prewake" }, "CDR_INGEST_SECRET not set — internal endpoint is unauthenticated");
  } else {
    if (!incoming) return reply.code(401).send({ error: "missing secret" });
    const a = Buffer.from(incoming.padEnd(64, "\0").slice(0, 64));
    const b = Buffer.from(secret.padEnd(64, "\0").slice(0, 64));
    if (!timingSafeEqual(a, b)) {
      app.log.warn({ ip: req.ip, endpoint: "/internal/mobile-prewake" }, "prewake_secret_mismatch");
      return reply.code(403).send({ error: "forbidden" });
    }
  }

  if ((process.env.PBX_INBOUND_PREWAKE ?? "1") !== "1") {
    return { ok: false, disabled: true };
  }

  const input = z.object({
    linkedId: z.string().min(1),
    connectTenantId: z.string().nullable().optional(),
    pbxVitalTenantId: z.string().nullable().optional(),
    toExtension: z.string().nullable().optional(),
    fromNumber: z.string().nullable().optional(),
  }).parse(req.body || {});

  // ── Resolve Connect tenantId ──────────────────────────────────────────────
  let tenantId: string | null = input.connectTenantId?.trim() || null;
  if (!tenantId && input.pbxVitalTenantId) {
    const code = input.pbxVitalTenantId.trim();
    const numeric = code.replace(/^T/i, "");
    const link = await db.tenantPbxLink.findFirst({
      where: {
        OR: [
          { pbxTenantCode: code },
          ...(numeric ? [{ pbxTenantId: numeric }] : []),
        ],
      },
      select: { tenantId: true },
    }).catch(() => null);
    tenantId = link?.tenantId ?? null;
  }
  if (!tenantId) {
    return { ok: false, reason: "tenant_not_resolved" };
  }

  // ── Pick the target users to wake ─────────────────────────────────────────
  // Preferred: the specific extension's owner (surgical). Otherwise wake every
  // user in the tenant that has at least one ASLEEP active mobile device — the
  // staleness gate keeps this naturally bounded to phones that would miss the
  // call.
  const staleCutoff = new Date(Date.now() - PREWAKE_DEVICE_STALE_MS);
  let candidateUserIds: string[] = [];

  if (input.toExtension && input.toExtension.trim()) {
    const ext = await db.extension.findFirst({
      where: { tenantId, extNumber: input.toExtension.trim(), status: "ACTIVE" },
      select: { id: true, ownerUserId: true },
    }).catch(() => null);
    let ownerUserId: string | null = ext?.ownerUserId ?? null;
    if (!ownerUserId && ext?.id) {
      const paired = await db.mobileDevice.findFirst({
        where: { tenantId, extensionId: ext.id, active: true } as any,
        orderBy: { lastSeenAt: "desc" } as any,
        select: { userId: true } as any,
      }).catch(() => null);
      const pu = (paired as any)?.userId;
      ownerUserId = typeof pu === "string" && pu.length > 0 ? pu : null;
    }
    if (ownerUserId) candidateUserIds = [ownerUserId];
  }

  // Owner request 2026-07-31: ALWAYS also wake the tenant's other asleep
  // devices, not just the dialled extension's owner. A call that is later
  // transferred, picked up by a colleague, or rolls to a ring group then finds
  // those phones already awake instead of starting the wake clock from zero at
  // the moment it moves. Bounded by the 45s staleness gate (already-online
  // phones are skipped entirely), the per-user 12s cooldown, and
  // PREWAKE_MAX_USERS. The dialled extension's owner stays FIRST in the list so
  // that if the cap ever truncates, the person actually being called is never
  // the one dropped.
  const PREWAKE_TENANT_WIDE = (process.env.PBX_PREWAKE_TENANT_WIDE ?? "1") === "1";
  if (PREWAKE_TENANT_WIDE || candidateUserIds.length === 0) {
    // Tenant-wide: only users with an asleep device (stale lastSeenAt or never
    // seen). Already-online phones (fresh lastSeenAt) are intentionally skipped.
    // NOTE: do the stale-check in JS. Prisma's null-filter handling on
    // `lastSeenAt` is fragile across client versions ({ not: null } and
    // { lastSeenAt: null } both throw on 6.x) and a throw here silently
    // returns zero devices -> no wake. Plain query + JS filter is version-proof.
    const tenantDevices = await db.mobileDevice.findMany({
      where: { tenantId, active: true } as any,
      select: { userId: true, lastSeenAt: true } as any,
      take: 500,
    }).catch((err: any) => {
      app.log.warn({ err: err?.message, tenantId, linkedId: input.linkedId }, "mobile-prewake: device query failed");
      return [] as Array<{ userId: string | null; lastSeenAt: Date | null }>;
    });
    const staleMs = staleCutoff.getTime();
    const asleepUserIds = (tenantDevices as Array<{ userId: string | null; lastSeenAt: Date | null }>)
      .filter((d) => !d.lastSeenAt || new Date(d.lastSeenAt).getTime() < staleMs)
      .map((d) => d.userId)
      .filter((u): u is string => typeof u === "string" && u.length > 0);
    // Dedupe with the dialled extension's owner FIRST (Set preserves insertion
    // order), so PREWAKE_MAX_USERS truncation can never drop the callee.
    candidateUserIds = Array.from(new Set([...candidateUserIds, ...asleepUserIds]));
  }

  if (candidateUserIds.length === 0) {
    return { ok: true, woken: 0, reason: "no_asleep_devices" };
  }
  if (candidateUserIds.length > PREWAKE_MAX_USERS) {
    candidateUserIds = candidateUserIds.slice(0, PREWAKE_MAX_USERS);
  }

  const wakeRequestedAt = new Date().toISOString();
  let woken = 0;
  for (const userId of candidateUserIds) {
    if (!prewakeCooldownGate(tenantId, userId)) continue;
    try {
      const res = await sendPushToUserDevices({
        tenantId,
        userId,
        payload: {
          // Caller-less wake — native app re-registers SIP without showing a
          // heads-up (placeholder is suppressed when caller info is absent).
          type: "INCOMING_CALL_WAKE",
          pbxCallId: input.linkedId,
          fromNumber: "",
          fromDisplay: null,
          toExtension: input.toExtension?.trim() || "",
          tenantId,
          pbxVitalTenantId: input.pbxVitalTenantId ?? null,
          timestamp: wakeRequestedAt,
          wakeRequestedAt,
        },
      });
      if ((res?.queued ?? 0) > 0 || res?.simulated) woken += 1;
      await recordWakeEvent({
        tenantId,
        pbxCallId: input.linkedId,
        stage: "PREWAKE_PUSH_QUEUED",
        source: "api",
        userId,
        details: { path: "mobile_prewake", queued: res?.queued ?? 0 },
      }).catch(() => undefined);
    } catch (err: any) {
      app.log.warn({ err: err?.message, tenantId, userId, linkedId: input.linkedId }, "mobile-prewake: push failed (non-fatal)");
    }
  }

  // ⛔ iOS VoIP PRE-WAKE IS DISABLED — it created a SECOND system call on every
  // single call (2026-08-02, proven from the device's own native log).
  //
  // Izzy: "I just hung up the phone, and it's still going. It's not even on the
  // lock screen; it's on the regular screen."
  //
  // WHY IT IS WRONG ON iOS, not just noisy:
  // Every VoIP push MUST report a CallKit call before its completion handler
  // returns or Apple terminates the app. The CallKit call's identity is derived
  // deterministically from the push's `callId`. This block fired at ring time,
  // BEFORE the CallInvite exists, so the only id available was the PBX
  // `linkedId` — a DIFFERENT id from the `inviteId` the real INCOMING_CALL push
  // sends moments later. Two ids => two derived identities => TWO separate
  // ringing CallKit calls for ONE phone call:
  //
  //   real call  cmsbtysij07nzqe128y77e7ne -> d0b81c61-5c7c-5ff9-8c96-8ed53c76243d
  //   pre-wake   1785676975.150051         -> a0caa00d-494e-550b-94e6-232d6afa1fef
  //
  // Hanging up in Connect tears down the call Connect is attached to; the other
  // one survives — still ringing, still showing a call screen, still holding the
  // green pill, and it has to be hung up by hand. It also gives the user a
  // phantom call to answer that has NO SIP session behind it, which is the
  // "answers and it connects to nothing / caller shows unknown" report in
  // PLAN_PUSH_AND_WAIT_SIMON.md §0.
  //
  // It cannot be fixed by re-keying this push: at ring time the invite does not
  // exist, so there is no shared id to derive from.
  //
  // Nothing is lost. Cold-killed wake is already the INCOMING_CALL VoIP push's
  // job — that is the push the native handler reports from before JS boots, and
  // it is what makes a terminated iPhone ring at all. Measured on Izzy's device,
  // this pre-wake preceded the real push by 1ms, 1ms, 49ms, 90ms and 1000ms.
  //
  // Kept as dead-but-documented code behind one constant so it is one edit to
  // restore, and the skip is logged so the cold-start wake can be measured.
  // ⛔ Do NOT re-enable without first making both pushes derive the SAME CallKit
  // identity — otherwise the duplicate call comes straight back.
  const IOS_VOIP_PREWAKE_ENABLED = false;
  let voipWoken = 0;
  if (!IOS_VOIP_PREWAKE_ENABLED && input.toExtension && input.toExtension.trim() && isApnsVoipConfigured()) {
    app.log.info(
      { event: "prewake_voip_skipped_duplicate_callkit", linkedId: input.linkedId, tenantId, toExtension: input.toExtension.trim() },
      "mobile-prewake: iOS VoIP pre-wake skipped (would create a duplicate CallKit call)",
    );
  }
  if (IOS_VOIP_PREWAKE_ENABLED && input.toExtension && input.toExtension.trim() && isApnsVoipConfigured()) {
    try {
      const iosDevices = await db.mobileDevice.findMany({
        where: { tenantId, userId: { in: candidateUserIds }, active: true, platform: "IOS" } as any,
        select: { id: true, platform: true, voipPushToken: true, userId: true } as any,
        take: 50,
      }).catch((err: any) => {
        app.log.warn({ err: err?.message, tenantId, linkedId: input.linkedId }, "prewake_voip_device_query_failed");
        return [] as Array<{ id: string; platform: string; voipPushToken: string | null; userId: string | null }>;
      });
      const byUser = new Map<string, Array<{ id: string; platform: string; voipPushToken: string | null }>>();
      for (const d of iosDevices as Array<{ id: string; platform: string; voipPushToken: string | null; userId: string | null }>) {
        if (!d.voipPushToken) continue;
        const u = typeof d.userId === "string" ? d.userId : "";
        if (!u) continue;
        if (!byUser.has(u)) byUser.set(u, []);
        byUser.get(u)!.push({ id: d.id, platform: d.platform, voipPushToken: d.voipPushToken });
      }
      for (const [uid, devs] of byUser) {
        voipWoken += devs.length;
        await sendApnsVoipPushesForIncomingCallApi({
          tenantId,
          userId: uid,
          callId: input.linkedId,
          voipPayload: {
            callId: input.linkedId,
            tenantId,
            toExtension: input.toExtension.trim(),
            callerNumber: input.fromNumber?.trim() || null,
            callerName: null,
            timestamp: wakeRequestedAt,
          },
          devices: devs,
        }).catch((err: any) =>
          app.log.warn({ err: err?.message, tenantId, userId: uid, linkedId: input.linkedId }, "prewake_voip_send_failed"),
        );
      }
    } catch (err: any) {
      app.log.warn({ err: err?.message, linkedId: input.linkedId }, "prewake_voip_block_error");
    }
  }

  app.log.info(
    { linkedId: input.linkedId, tenantId, candidates: candidateUserIds.length, woken, voipWoken, toExtension: input.toExtension ?? null },
    "mobile-prewake: done",
  );
  return { ok: true, woken, voipWoken, candidates: candidateUserIds.length };
});

// ─── Push-wake config publisher (admin/internal) ─────────────────────────────
// One-shot publisher for the AstDB keys the [connect-dial-with-wake] dialplan
// context reads. Use this to bootstrap a PBX after deploying the new dialplan
// snippet, or to re-publish after rotating CDR_INGEST_SECRET / changing
// PBX_WAKE_WAIT_SECS without doing a full IVR republish.
//
// Body (JSON):
//   tenantId  — OPTIONAL — Connect tenantId. If omitted, publishes ONLY the
//                          system-wide keys (connect/system/*). The
//                          telephony service requires a tenantSlug for auth,
//                          so omitted tenant uses the first available tenant
//                          slug just to satisfy the routing — keys still land
//                          in the global family.
//
// Auth: same x-cdr-secret header as the rest of the /internal/* endpoints.
//
// Returns:
//   { ok, slug, wakeUrl, wakeWaitSecs, hasSecret, tenantPublished, pbxTenantId, pbxTenantCode }
app.post("/internal/pbx/publish-wake-config", async (req, reply) => {
  const secret = process.env.CDR_INGEST_SECRET?.trim();
  const incoming = String((req.headers as Record<string, string | undefined>)["x-cdr-secret"] || "").trim();
  if (!secret) {
    app.log.warn({ endpoint: "/internal/pbx/publish-wake-config" }, "CDR_INGEST_SECRET not set — internal endpoint is unauthenticated");
  } else {
    if (!incoming) return reply.code(401).send({ error: "missing secret" });
    const a = Buffer.from(incoming.padEnd(64, "\0").slice(0, 64));
    const b = Buffer.from(secret.padEnd(64, "\0").slice(0, 64));
    if (!timingSafeEqual(a, b)) {
      return reply.code(403).send({ error: "forbidden" });
    }
  }

  const input = z.object({
    tenantId: z.string().nullable().optional(),
  }).parse(req.body || {});

  // Pick a tenant slug to satisfy the telephony service's tenant-scoped
  // authorisation (the keys themselves go into the global family). When
  // tenantId is supplied use that tenant's slug; otherwise grab any active
  // tenant. The slug only gates the auth path — wake_api_url/secret/etc
  // land under connect/system regardless of which slug we passed.
  let resolvedTenantId: string | null = input.tenantId || null;
  if (!resolvedTenantId) {
    const anyTenant = await db.tenant.findFirst({ select: { id: true } });
    resolvedTenantId = anyTenant?.id ?? null;
  }
  if (!resolvedTenantId) {
    return reply.code(409).send({ error: "no_tenant_available", detail: "Cannot publish wake config — no tenants exist." });
  }

  const slug = await getIvrSlugForTenant(resolvedTenantId);
  let systemPublished = false;
  let tenantPublished: { published: boolean; pbxTenantId: string | null; pbxTenantCode: string | null } = {
    published: false, pbxTenantId: null, pbxTenantCode: null,
  };
  let publishError: string | null = null;
  try {
    await publishWakeSystemConfig(slug);
    systemPublished = true;
    if (input.tenantId) {
      tenantPublished = await publishWakeTenantConfig(slug, input.tenantId);
    }
  } catch (err: any) {
    publishError = err?.message ?? "publish_failed";
    app.log.warn({ tenantId: resolvedTenantId, slug, err: publishError }, "publish-wake-config: failed");
  }

  const baseUrl = (process.env.PUBLIC_API_BASE_URL ?? "https://app.connectcomunications.com/api").replace(/\/$/, "");
  return reply.send({
    ok: systemPublished,
    slug,
    wakeUrl: `${baseUrl}/internal/pbx/wake-extension`,
    wakeWaitSecs: Number.parseInt(process.env.PBX_WAKE_WAIT_SECS ?? "10", 10) || 10,
    hasSecret: Boolean(secret),
    systemPublished,
    tenantPublished,
    error: publishError,
  });
});

// Admin-authenticated remote action: send a synthetic INCOMING_CALL_WAKE
// data-only push to a specific user/device so an operator can remotely
// kick a phone's SIP socket without contacting the user. Powers the
// "Force re-register" button on /admin/call-wake-diagnostics.
//
// The mobile native handler treats the wake push exactly like a real one:
//   • starts SipKeepAliveService (FGS + wake lock)
//   • emits Sip.WakeRegister so SipContext fires register({forceRestart:true})
// But because the synthetic payload carries no caller info, the new
// "wake placeholder" heads-up is intentionally suppressed (the placeholder
// only fires when haveCallerInfo=true). So an operator can use this as a
// silent diagnostic prod with zero user-visible side effect.
app.post("/admin/mobile/devices/:id/force-reregister", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;
  const { id: deviceId } = req.params as { id: string };
  if (!deviceId) return reply.code(400).send({ error: "missing_device_id" });

  const device = await db.mobileDevice.findUnique({
    where: { id: deviceId },
    select: { id: true, tenantId: true, userId: true, active: true, expoPushToken: true },
  });
  if (!device) return reply.code(404).send({ error: "device_not_found" });
  if (!device.active) {
    return reply.code(409).send({ error: "device_inactive", detail: "Cannot force-reregister an inactive device — token is stale." });
  }

  const syntheticPbxCallId = `admin-force-${Date.now()}`;
  const wakeRequestedAtIso = new Date().toISOString();

  let pushResult: { queued?: number; simulated?: boolean } | null = null;
  let pushError: string | null = null;
  try {
    pushResult = await sendPushToUserDevices({
      tenantId: device.tenantId,
      userId: device.userId,
      payload: {
        type: "INCOMING_CALL_WAKE",
        pbxCallId: syntheticPbxCallId,
        // Empty caller info — mobile placeholder logic skips the heads-up
        // when neither fromNumber nor fromDisplay is present. We still
        // pass blank strings (not omitted) so the FCM data map shape
        // matches a real wake.
        fromNumber: "",
        fromDisplay: null,
        toExtension: "",
        tenantId: device.tenantId,
        pbxVitalTenantId: null,
        timestamp: wakeRequestedAtIso,
        wakeRequestedAt: wakeRequestedAtIso,
      },
    });
  } catch (err: any) {
    pushError = err?.message ?? "push_send_failed";
    app.log.warn({ deviceId, err: pushError }, "force-reregister: push send threw");
  }

  await audit({
    tenantId: device.tenantId,
    actorUserId: admin.sub,
    action: "MOBILE_DEVICE_FORCE_REREGISTER",
    entityType: "MobileDevice",
    entityId: device.id,
  });

  return reply.send({
    ok: !!pushResult && !pushError,
    deviceId: device.id,
    syntheticPbxCallId,
    queued: pushResult?.queued ?? 0,
    simulated: pushResult?.simulated ?? false,
    error: pushError,
  });
});

// Admin-authenticated wrapper around publish-wake-config so an operator can
// hit "Republish wake config" from /admin/call-wake-diagnostics after we tune
// PBX_WAKE_WAIT_SECS or wake_api_url. The /internal/* sibling above is
// nginx-blocked and requires CDR_INGEST_SECRET; this one accepts a
// SUPER_ADMIN JWT and reuses the same publish helpers.
//
// Optional body { allTenants?: boolean } — when true, also republishes the
// per-tenant identity keys (pbx_tenant_id / pbx_tenant_code) for every
// tenant that has a TenantPbxLink. The system family (wake_api_url,
// wake_api_secret, wake_wait_secs) is global and only written once.
app.post("/admin/pbx/republish-wake-config", async (req, reply) => {
  const admin = await requireSuperAdmin(req, reply);
  if (!admin) return;

  const input = z.object({
    allTenants: z.boolean().optional().default(true),
  }).parse(req.body || {});

  const anyTenant = await db.tenant.findFirst({ select: { id: true } });
  if (!anyTenant) {
    return reply.code(409).send({ error: "no_tenant_available" });
  }
  const slugForSystem = await getIvrSlugForTenant(anyTenant.id);

  let systemPublished = false;
  let systemError: string | null = null;
  try {
    await publishWakeSystemConfig(slugForSystem);
    systemPublished = true;
  } catch (err: any) {
    systemError = err?.message ?? "publish_failed";
    app.log.warn({ tenantId: anyTenant.id, slug: slugForSystem, err: systemError }, "republish-wake-config: system failed");
  }

  const tenantResults: Array<{
    tenantId: string;
    slug: string;
    published: boolean;
    pbxTenantId: string | null;
    pbxTenantCode: string | null;
    error: string | null;
  }> = [];

  if (input.allTenants) {
    const links = await db.tenantPbxLink.findMany({
      where: { status: "LINKED" },
      select: { tenantId: true },
    }).catch(() => [] as Array<{ tenantId: string }>);
    const linkedTenantIds = Array.from(new Set(links.map((l) => l.tenantId).filter(Boolean)));
    for (const tenantId of linkedTenantIds) {
      let tSlug = "";
      try {
        tSlug = await getIvrSlugForTenant(tenantId);
        const r = await publishWakeTenantConfig(tSlug, tenantId);
        tenantResults.push({
          tenantId, slug: tSlug,
          published: r.published, pbxTenantId: r.pbxTenantId, pbxTenantCode: r.pbxTenantCode,
          error: null,
        });
      } catch (err: any) {
        tenantResults.push({
          tenantId, slug: tSlug,
          published: false, pbxTenantId: null, pbxTenantCode: null,
          error: err?.message ?? "publish_failed",
        });
      }
    }
  }

  return reply.send({
    ok: systemPublished,
    systemPublished,
    systemError,
    wakeWaitSecs: Number.parseInt(process.env.PBX_WAKE_WAIT_SECS ?? "10", 10) || 10,
    tenantsAttempted: tenantResults.length,
    tenantsPublished: tenantResults.filter((t) => t.published).length,
    tenants: tenantResults,
  });
});

// ─── Push-wake (Option 2) ───────────────────────────────────────────────────
// Called BY the VitalPBX dialplan (via CURL) for the target extension(s) the
// PBX is about to Dial(). The dialplan calls this, then Wait()s ~6 seconds,
// then Dial()s. During those 6 seconds the mobile device wakes, registers
// SIP, and is ready to receive the INVITE.
//
// Hard requirements:
//   * MUST respond fast (<500 ms typical, <2 s ceiling) — the dialplan blocks
//     on the CURL response. Push send happens AFTER we respond if needed.
//   * MUST be idempotent at the (tenant, pbxCallId) grain — the dialplan may
//     retry on transient HTTP failure.
//   * MUST NOT throw on missing extension owner / no devices — return ok:false
//     with reason so the dialplan logs cleanly.
//   * MUST emit CallWakeEvent rows at every stage for ops debug.
//
// Body (JSON):
//   pbxCallId           — MANDATORY — the linkedid the PBX assigns to this call
//   pbxVitalTenantId    — MANDATORY — VitalPBX tenant code (e.g. "T25")
//   extensionNumber     — MANDATORY — the extension the PBX is about to dial (e.g. "101")
//   fromNumber          — caller ID number (raw)
//   fromDisplay         — caller ID name
//   tenantId            — OPTIONAL — short-circuits PBX→Connect tenant lookup if known
//
// Auth: same x-cdr-secret header as the rest of the /internal/* endpoints.
app.post("/internal/pbx/wake-extension", async (req, reply) => {
  const t0 = Date.now();
  const secret = process.env.CDR_INGEST_SECRET?.trim();
  const incoming = String((req.headers as Record<string, string | undefined>)["x-cdr-secret"] || "").trim();
  if (!secret) {
    app.log.warn({ endpoint: "/internal/pbx/wake-extension" }, "CDR_INGEST_SECRET not set — internal endpoint is unauthenticated");
  } else {
    if (!incoming) return reply.code(401).send({ error: "missing secret" });
    const a = Buffer.from(incoming.padEnd(64, "\0").slice(0, 64));
    const b = Buffer.from(secret.padEnd(64, "\0").slice(0, 64));
    if (!timingSafeEqual(a, b)) {
      app.log.warn({ ip: req.ip, endpoint: "/internal/pbx/wake-extension" }, "wake_extension_secret_mismatch");
      return reply.code(403).send({ error: "forbidden" });
    }
  }

  const input = z.object({
    pbxCallId: z.string().min(1),
    pbxVitalTenantId: z.string().min(1),
    extensionNumber: z.string().min(1),
    fromNumber: z.string().nullable().optional(),
    fromDisplay: z.string().nullable().optional(),
    tenantId: z.string().nullable().optional(),
  }).parse(req.body || {});

  const wakeRequestedAtIso = new Date().toISOString();

  app.log.info(
    {
      callWake: true,
      stage: "WAKE_HTTP_RECEIVED",
      pbxCallId: input.pbxCallId,
      pbxVitalTenantId: input.pbxVitalTenantId,
      extensionNumber: input.extensionNumber,
      fromNumber: input.fromNumber || null,
      hintTenantId: input.tenantId || null,
      ip: req.ip,
    },
    "[CALL_WAKE] WAKE_HTTP_RECEIVED",
  );

  // ── Resolve Connect tenant + extension owner ───────────────────────────────
  // Strategy mirrors /internal/mobile-ring-notify so the wake hook works for
  // any tenant the dialplan opts in. Fast path: caller passed tenantId.
  let target: { tenantId: string; userId: string; extensionId: string | null } | null = null;
  let resolvedTenantId: string | null = input.tenantId || null;

  // Resolve PBX tenant code (e.g. T25) → Connect tenantId if not provided.
  // The dialplan can send either the numeric vitalTenantId OR the human code
  // ("T25"); we match either against pbxTenantId / pbxTenantCode.
  if (!resolvedTenantId) {
    try {
      const link = await db.tenantPbxLink.findFirst({
        where: {
          OR: [
            { pbxTenantId: input.pbxVitalTenantId },
            { pbxTenantCode: input.pbxVitalTenantId },
          ],
        },
        select: { tenantId: true },
      });
      if (link) resolvedTenantId = link.tenantId;
    } catch (err: any) {
      app.log.warn({ err: err?.message, pbxVitalTenantId: input.pbxVitalTenantId }, "wake-extension: tenant lookup failed");
    }
  }

  if (!resolvedTenantId) {
    await recordWakeEvent({
      tenantId: input.pbxVitalTenantId, // placeholder; we have nothing better
      pbxCallId: input.pbxCallId,
      stage: "WAKE_TENANT_NOT_FOUND",
      source: "api",
      details: { pbxVitalTenantId: input.pbxVitalTenantId, extensionNumber: input.extensionNumber },
    }).catch(() => undefined);
    app.log.warn(
      { pbxCallId: input.pbxCallId, pbxVitalTenantId: input.pbxVitalTenantId },
      "wake-extension: no Connect tenant for PBX vitalTenantId",
    );
    return reply.code(200).send({ ok: false, reason: "TENANT_NOT_FOUND", elapsedMs: Date.now() - t0 });
  }

  await recordWakeEvent({
    tenantId: resolvedTenantId,
    pbxCallId: input.pbxCallId,
    stage: "WAKE_REQUESTED",
    source: "pbx_dialplan",
    details: {
      pbxVitalTenantId: input.pbxVitalTenantId,
      extensionNumber: input.extensionNumber,
      fromNumber: input.fromNumber || null,
      fromDisplay: input.fromDisplay || null,
      wakeRequestedAt: wakeRequestedAtIso,
      callerIp: req.ip,
    },
  });

  // Resolve extension owner.
  try {
    const ext = await db.extension.findFirst({
      where: {
        tenantId: resolvedTenantId,
        extNumber: input.extensionNumber,
        status: "ACTIVE",
      },
      select: { id: true, tenantId: true, ownerUserId: true },
    });
    if (ext) {
      let resolvedUserId: string | null = ext.ownerUserId ?? null;
      if (!resolvedUserId) {
        const pairedDevice = await db.mobileDevice.findFirst({
          where: {
            tenantId: ext.tenantId,
            extensionId: ext.id,
            active: true,
          } as any,
          orderBy: { lastSeenAt: "desc" } as any,
          select: { userId: true } as any,
        });
        const pairedUserId = pairedDevice?.userId as unknown;
        resolvedUserId = typeof pairedUserId === "string" && pairedUserId.length > 0 ? pairedUserId : null;
        if (resolvedUserId) {
          app.log.info(
            { pbxCallId: input.pbxCallId, extensionNumber: input.extensionNumber, tenantId: ext.tenantId, extensionId: ext.id, resolvedUserId },
            "wake-extension: resolved target via active extension-paired device",
          );
        }
      }
      if (resolvedUserId) {
        target = { tenantId: ext.tenantId, userId: resolvedUserId, extensionId: ext.id };
      }
    }
  } catch (err: any) {
    app.log.warn({ err: err?.message, pbxCallId: input.pbxCallId }, "wake-extension: extension lookup failed");
  }

  if (!target) {
    await recordWakeEvent({
      tenantId: resolvedTenantId,
      pbxCallId: input.pbxCallId,
      stage: "WAKE_EXTENSION_NOT_FOUND",
      source: "api",
      details: { extensionNumber: input.extensionNumber, pbxVitalTenantId: input.pbxVitalTenantId },
    });
    return reply.code(200).send({ ok: false, reason: "EXTENSION_NOT_FOUND", elapsedMs: Date.now() - t0 });
  }

  // Fetch active devices to record DEVICES_RESOLVED before push send (so we can
  // see the count in the timeline even if the push step itself is slow/fails).
  const devices = await db.mobileDevice.findMany({
    where: { tenantId: target.tenantId, userId: target.userId, active: true } as any,
    select: { id: true, platform: true, expoPushToken: true } as any,
  });

  await recordWakeEvent({
    tenantId: target.tenantId,
    pbxCallId: input.pbxCallId,
    stage: "WAKE_DEVICES_RESOLVED",
    source: "api",
    userId: target.userId,
    extensionId: target.extensionId,
    details: {
      deviceCount: devices.length,
      platforms: devices.map((d: any) => d.platform),
      tokenTails: devices.map((d: any) => String(d.expoPushToken).slice(-12)),
    },
  });

  if (!devices.length) {
    return reply.code(200).send({
      ok: true,
      devicesNotified: 0,
      tenantId: target.tenantId,
      userId: target.userId,
      extensionId: target.extensionId,
      reason: "NO_ACTIVE_DEVICES",
      elapsedMs: Date.now() - t0,
    });
  }

  // ── Send the wake push ────────────────────────────────────────────────────
  // We send synchronously so the dialplan knows whether the push was queued
  // before it starts its Wait(). Worst case Expo accepts in <300 ms.
  let pushResult: { queued?: number; simulated?: boolean } | null = null;
  try {
    pushResult = await sendPushToUserDevices({
      tenantId: target.tenantId,
      userId: target.userId,
      payload: {
        type: "INCOMING_CALL_WAKE",
        pbxCallId: input.pbxCallId,
        fromNumber: input.fromNumber || "unknown",
        fromDisplay: input.fromDisplay ?? null,
        toExtension: input.extensionNumber,
        tenantId: target.tenantId,
        pbxVitalTenantId: input.pbxVitalTenantId,
        timestamp: new Date().toISOString(),
        wakeRequestedAt: wakeRequestedAtIso,
      },
    });
  } catch (err: any) {
    await recordWakeEvent({
      tenantId: target.tenantId,
      pbxCallId: input.pbxCallId,
      stage: "WAKE_PUSH_THREW",
      source: "api",
      userId: target.userId,
      extensionId: target.extensionId,
      details: { error: err?.message, stack: err?.stack?.slice(0, 1000) },
    });
    app.log.error({ err: err?.message, pbxCallId: input.pbxCallId }, "wake-extension: push send threw");
    return reply.code(200).send({ ok: false, reason: "PUSH_THREW", elapsedMs: Date.now() - t0 });
  }

  await recordWakeEvent({
    tenantId: target.tenantId,
    pbxCallId: input.pbxCallId,
    stage: "WAKE_PUSH_QUEUED",
    source: "api",
    userId: target.userId,
    extensionId: target.extensionId,
    details: {
      queued: pushResult?.queued ?? 0,
      simulated: pushResult?.simulated ?? false,
      elapsedMs: Date.now() - t0,
    },
  });

  app.log.info(
    {
      callWake: true,
      stage: "WAKE_HTTP_RESPONDED",
      pbxCallId: input.pbxCallId,
      tenantId: target.tenantId,
      userId: target.userId,
      extensionId: target.extensionId,
      devicesNotified: pushResult?.queued ?? 0,
      elapsedMs: Date.now() - t0,
    },
    "[CALL_WAKE] WAKE_HTTP_RESPONDED",
  );

  return reply.code(200).send({
    ok: true,
    tenantId: target.tenantId,
    userId: target.userId,
    extensionId: target.extensionId,
    devicesNotified: pushResult?.queued ?? 0,
    simulated: pushResult?.simulated ?? false,
    elapsedMs: Date.now() - t0,
  });
});

// ─── Device-side wake telemetry ─────────────────────────────────────────────
// The mobile app POSTs here from the FCM service / SipContext to tell us
// "I received the wake push at <ts>", "I started SIP REGISTER", "I got
// REGISTERED at <ts>". Each call writes one CallWakeEvent row keyed by
// pbxCallId so the Diagnostics screen can show the full Gantt-style timeline.
//
// Auth: requires a valid mobile JWT (preAuthHook). We'll trust the deviceId
// the device claims (verified via the JWT's userId).
app.post("/mobile/wake/event", async (req, reply) => {
  const user = req.user as JwtUser | undefined;
  if (!user?.sub || !user?.tenantId) return reply.code(401).send({ error: "UNAUTHORIZED" });

  const body = z.object({
    pbxCallId: z.string().min(1),
    // .nullish(): the Android client sends deviceId:null before it knows its
    // device row id. A bare .optional() rejected null with a ZodError → 500,
    // which silently killed the DEVICE_REGISTER_COMPLETE requeue trigger
    // (observed 2026-07-27, "postWakeEvent non-2xx 500" on every cold answer).
    deviceId: z.string().min(1).nullish(),
    stage: z.enum([
      "DEVICE_PUSH_RECEIVED",
      "DEVICE_REGISTER_TRIGGERED",
      "DEVICE_REGISTER_COMPLETE",
      "DEVICE_REGISTER_FAILED",
      "DEVICE_INVITE_RECEIVED",
      "DEVICE_INVITE_UI_SHOWN",
      "DEVICE_ANSWER_TAPPED",
      "DEVICE_DECLINE_TAPPED",
      "DEVICE_TIMED_OUT",
    ]),
    details: z.record(z.string(), z.any()).optional().nullable(),
  }).parse(req.body || {});

  // If the client passes a deviceId, verify it belongs to this user.
  let resolvedDeviceId: string | null = null;
  if (body.deviceId) {
    const owned = await db.mobileDevice.findFirst({
      where: { id: body.deviceId, userId: user.sub, tenantId: user.tenantId } as any,
      select: { id: true },
    });
    if (owned) resolvedDeviceId = owned.id;
  }

  // Wake-health bookkeeping: any DEVICE_* stage proves the push reached the app.
  // "lastPushSentAt recent but lastWakeAckAt stale" is the delivery-failure signal
  // the wake-health monitor scans for. Never blocks telemetry ingest.
  try {
    if (resolvedDeviceId) {
      await db.mobileDevice.update({ where: { id: resolvedDeviceId }, data: { lastWakeAckAt: new Date() } as any });
    } else {
      await db.mobileDevice.updateMany({ where: { userId: user.sub, tenantId: user.tenantId, active: true }, data: { lastWakeAckAt: new Date() } as any });
    }
  } catch { /* bookkeeping must never fail the event */ }

  await recordWakeEvent({
    tenantId: user.tenantId,
    pbxCallId: body.pbxCallId,
    stage: body.stage,
    source: "device",
    userId: user.sub,
    deviceId: resolvedDeviceId,
    details: body.details || null,
  });

  if (body.stage === "DEVICE_REGISTER_COMPLETE") {
    const pendingInvite = await db.callInvite.findFirst({
      where: {
        tenantId: user.tenantId,
        userId: user.sub,
        pbxCallId: body.pbxCallId,
        status: "PENDING",
        expiresAt: { gte: new Date() },
      },
      select: {
        id: true,
        pbxCallId: true,
        toExtension: true,
        status: true,
      },
    });
    if (isPendingMobileInviteEligible(pendingInvite)) {
      await tryRequeuePendingMobileInvite({
        linkedId: pendingInvite.pbxCallId ?? body.pbxCallId,
        exten: pendingInvite.toExtension,
        inviteId: pendingInvite.id,
        trigger: "register_complete",
        logContext: { pbxCallId: body.pbxCallId, deviceId: resolvedDeviceId },
      });
    } else {
      // ZERO-CONTACT COLD-START (both devices were asleep at dial time).
      //
      // When EVERY device on the target extension is asleep/unregistered, the
      // PBX Dial() finds zero contacts and fails INSTANTLY — no extension leg
      // is ever created, so `mobile-ring-notify` never fires and NO CallInvite
      // row exists. The pre-wake push (sent the moment the inbound call hit the
      // trunk) still woke this device; it has now finished REGISTER. The call
      // is most likely sitting in the IVR/voicemail right now.
      //
      // Re-dial the still-live inbound call so the freshly-registered endpoint
      // actually rings instead of staying in voicemail. This is the same AMI
      // requeue that already makes the "one phone open" case ring the second
      // device — we just additionally allow it when no invite row exists.
      //
      // SAFE FOR ALL TENANTS: requeueLiveCallToDialplan is loop-guarded — it
      // SKIPS if the call already answered (`extensionAnsweredAt`), if an
      // extension leg is live, or if any extension leg was ever seen
      // (`extensionLegSeen`). The genuine zero-contact case trips none of
      // those, so only the legitimately-stuck call is re-dialled. We probe
      // telephony first purely to avoid pointless requeue calls.
      try {
        const liveStatus = await requestTelephonyInviteStatus({ linkedId: body.pbxCallId });
        if (liveStatus.exists && liveStatus.state !== "hungup" && !liveStatus.extensionAnsweredAt) {
          let fallbackExten: string | null = null;
          if (resolvedDeviceId) {
            const dev = await db.mobileDevice
              .findFirst({
                where: { id: resolvedDeviceId } as any,
                select: { extension: { select: { extNumber: true } } } as any,
              })
              .catch(() => null);
            fallbackExten = (dev as any)?.extension?.extNumber ?? null;
          }
          await tryRequeuePendingMobileInvite({
            linkedId: body.pbxCallId,
            exten: fallbackExten,
            inviteId: null,
            trigger: "register_complete",
            logContext: {
              pbxCallId: body.pbxCallId,
              deviceId: resolvedDeviceId,
              path: "zero_contact_coldstart",
              telephonyState: liveStatus.state,
            },
          });
        } else {
          app.log.info(
            {
              pbxCallId: body.pbxCallId,
              exists: liveStatus.exists,
              state: liveStatus.state,
              extensionAnsweredAt: liveStatus.extensionAnsweredAt,
            },
            "register-complete: zero-contact requeue skipped (call not live / already answered)",
          );
        }
      } catch (err) {
        app.log.warn(
          {
            err: err instanceof Error ? err.message : String(err),
            pbxCallId: body.pbxCallId,
          },
          "register-complete: zero-contact requeue probe failed",
        );
      }
    }
  }

  return reply.send({ ok: true });
});

// ─── iOS foreground-active heartbeat ────────────────────────────────────────
// The iOS Connect app POSTs here (~every 15s) while it is FOREGROUND and holds a
// live SIP socket, so the incoming-call pipeline can skip the APNs VoIP push for
// this device (see sendApnsVoipPushesForIncomingCallApi). This is what keeps the
// native CallKit screen from appearing over the in-app Connect incoming screen
// while the app is open. Backgrounding/quitting stops the pings; the Redis key
// expires (short TTL) and VoIP pushes resume automatically. iOS-only by
// construction — Android never calls this, and non-IOS devices are a no-op.
// Fails soft: a Redis error never breaks the client.
app.post("/mobile/foreground-active", async (req, reply) => {
  const user = req.user as JwtUser | undefined;
  if (!user?.sub || !user?.tenantId) return reply.code(401).send({ error: "UNAUTHORIZED" });

  const body = z
    .object({ deviceId: z.string().min(1), active: z.boolean().optional().default(true) })
    .safeParse(req.body);
  if (!body.success) return reply.code(400).send({ error: "invalid_payload" });

  const device = await db.mobileDevice
    .findFirst({
      where: { id: body.data.deviceId, tenantId: user.tenantId, userId: user.sub },
      select: { id: true, platform: true },
    })
    .catch(() => null);
  if (!device) return reply.code(404).send({ error: "DEVICE_NOT_FOUND" });

  // Only iOS devices participate in the VoIP-push gate; others are a harmless no-op.
  if (device.platform !== "IOS") return reply.send({ ok: true, ignored: "not_ios" });

  const key = "ios_fg_active:" + device.id;
  try {
    if (body.data.active) {
      // ~10s TTL; the client re-pings every ~4s, well within that window, so a
      // force-quit (pings stop) resumes the VoIP push within ~10s.
      await redis.set(key, "1", "EX", 10);
    } else {
      await redis.del(key);
    }
  } catch (err: any) {
    app.log.warn({ err: err?.message, deviceId: device.id }, "mobile/foreground-active: redis error");
    return reply.send({ ok: false, reason: "redis_error" });
  }

  return reply.send({ ok: true, active: body.data.active });
});

// ─── Wake timeline read API (for Diagnostics screen + admin tools) ──────────
// Returns the full event sequence for a pbxCallId, or the most recent N events
// for the calling user when no pbxCallId is supplied. Tenant-scoped.
app.get("/mobile/wake/timeline", async (req, reply) => {
  const user = req.user as JwtUser | undefined;
  if (!user?.sub || !user?.tenantId) return reply.code(401).send({ error: "UNAUTHORIZED" });

  const q = z.object({
    pbxCallId: z.string().min(1).optional(),
    // Admin-only override: when SUPER_ADMIN / TENANT_ADMIN passes a userId,
    // we surface that user's wake timeline. Powers the
    // /admin/call-wake-diagnostics portal page so an admin can triage a
    // remote user's "phone goes straight to voicemail" report without
    // needing the device in hand. Quietly ignored for non-admins.
    userId: z.string().min(1).optional(),
    deviceId: z.string().min(1).optional(),
    limit: z.coerce.number().int().min(1).max(500).optional().default(100),
  }).parse(req.query || {});

  const isAdmin = user.role === "SUPER_ADMIN" || user.role === "TENANT_ADMIN";

  const where: any = { tenantId: user.tenantId };
  if (q.pbxCallId) {
    where.pbxCallId = q.pbxCallId;
  } else if (isAdmin && q.userId) {
    where.userId = q.userId;
  } else if (isAdmin && q.deviceId) {
    where.deviceId = q.deviceId;
  } else {
    // Limit to "this user" view when no pbxCallId is specified, so non-admin
    // diagnostics don't accidentally surface other users' calls.
    where.userId = user.sub;
  }

  const events = await (db as any).callWakeEvent.findMany({
    where,
    orderBy: { occurredAt: "desc" },
    take: q.limit,
    select: {
      id: true,
      pbxCallId: true,
      stage: true,
      source: true,
      userId: true,
      deviceId: true,
      extensionId: true,
      details: true,
      latencyMs: true,
      occurredAt: true,
    },
  });

  return reply.send({ events });
});

// Internal: telephony service pulls PBX tenant → Connect tenant map (same auth as cdr-ingest).
app.get("/internal/telephony/pbx-tenant-map", async (req, reply) => {
  const secret = process.env.CDR_INGEST_SECRET?.trim();
  const incoming = String((req.headers as Record<string, string | undefined>)["x-cdr-secret"] || "").trim();
  if (!secret) {
    app.log.warn({ endpoint: "/internal/telephony/pbx-tenant-map" }, "CDR_INGEST_SECRET not set — internal endpoint is unauthenticated");
  } else {
    if (!incoming) return reply.code(401).send({ error: "missing secret" });
    const a = Buffer.from(incoming.padEnd(64, "\0").slice(0, 64));
    const b = Buffer.from(secret.padEnd(64, "\0").slice(0, 64));
    if (!timingSafeEqual(a, b)) {
      app.log.warn({ ip: req.ip, endpoint: "/internal/telephony/pbx-tenant-map" }, "rate_limit_internal_secret_mismatch");
      return reply.code(403).send({ error: "forbidden" });
    }
  }
  const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  if (!instance) return reply.send({ version: 1, pbxInstanceId: null, fetchedAt: new Date().toISOString(), entries: [] });
  const [rows, links, didRows, extensionRows] = await Promise.all([
    db.pbxTenantDirectory.findMany({ where: { pbxInstanceId: instance.id } }),
    db.tenantPbxLink.findMany({ where: { pbxInstanceId: instance.id, status: "LINKED" } }),
    db.pbxTenantInboundDid.findMany({
      where: { pbxInstanceId: instance.id, active: true },
      select: { e164: true, vitalTenantId: true, pbxTenantCode: true, connectTenantId: true },
    }),
    db.extension.findMany({
      where: { status: "ACTIVE" },
      select: { extNumber: true, tenantId: true },
      orderBy: [{ tenantId: "asc" }, { extNumber: "asc" }],
    }),
  ]);
  const connectByVital = new Map<string, string>();
  for (const l of links) {
    const v = (l.pbxTenantId || "").trim().toLowerCase();
    if (v) connectByVital.set(v, l.tenantId);
    const code = (l.pbxTenantCode || "").trim().toUpperCase();
    if (code) {
      const hit = rows.find((r) => r.tenantCode.toUpperCase() === code);
      if (hit) connectByVital.set(hit.vitalTenantId.trim().toLowerCase(), l.tenantId);
    }
  }
  // Build entries (without names first to gather tenant IDs)
  const rawEntries = rows.map((r) => ({
    vitalTenantId: r.vitalTenantId,
    tenantCode: r.tenantCode,
    tenantSlug: r.tenantSlug,
    connectTenantId: connectByVital.get(r.vitalTenantId.trim().toLowerCase()) ?? null,
  }));
  const rawDidEntries = didRows.map((r) => ({
    e164: r.e164,
    vitalTenantId: r.vitalTenantId,
    tenantCode: (r.pbxTenantCode || "").trim(),
    connectTenantId: r.connectTenantId,
  }));

  // Join tenant names in one query
  const allConnectIds = [
    ...rawEntries.map((e) => e.connectTenantId),
    ...rawDidEntries.map((d) => d.connectTenantId),
  ].filter((id): id is string => !!id);
  const uniqueIds = [...new Set(allConnectIds)];
  const tenantNameRows = uniqueIds.length > 0
    ? await db.tenant.findMany({ where: { id: { in: uniqueIds } }, select: { id: true, name: true } })
    : [];
  const tenantNameById = new Map(tenantNameRows.map((t) => [t.id, t.name]));

  const entries = rawEntries.map((e) => ({
    ...e,
    tenantName: e.connectTenantId ? (tenantNameById.get(e.connectTenantId) ?? null) : null,
  }));
  const didEntries = rawDidEntries.map((d) => ({
    ...d,
    tenantName: d.connectTenantId ? (tenantNameById.get(d.connectTenantId) ?? null) : null,
  }));
  const extensionEntries = extensionRows.map((e) => ({
    extNumber: e.extNumber,
    connectTenantId: e.tenantId,
    tenantName: tenantNameById.get(e.tenantId) ?? null,
  }));

  return reply.send({
    version: 2,
    pbxInstanceId: instance.id,
    fetchedAt: new Date().toISOString(),
    entries,
    didEntries,
    extensionEntries,
  });
});

app.get("/internal/telephony/user-extensions", async (req, reply) => {
  if (!verifyCdrSecret(req)) return reply.code(403).send({ error: "forbidden" });
  const query = z.object({
    userId: z.string().min(1),
    tenantId: z.string().min(1),
  }).parse(req.query || {});
  const rows = await db.extension.findMany({
    where: {
      tenantId: query.tenantId,
      ownerUserId: query.userId,
      status: "ACTIVE",
    },
    select: { extNumber: true },
    orderBy: { extNumber: "asc" },
  });
  return reply.send({
    userId: query.userId,
    tenantId: query.tenantId,
    extensions: [...new Set(rows.map((r) => String(r.extNumber || "").trim()).filter(Boolean))],
  });
});

registerInboundCrmMatchInternalRoute(app, verifyCdrSecret);

// ─── Connect CDR KPI totals ───────────────────────────────────────────────────
// Default: source=connect → ConnectCdr only (DB counts).
// source=pbx → reads from background cache (single global PBX query every 30s).
/** Comma-separated tenant names to skip when aggregating VitalPBX CDR (listTenants `name`). Default: smoke,billing,test. Set to empty or "none" to include all. Excluding "vitalpbx" was dropping a large share of traffic vs the real PBX UI. */
function parseVitalpbxCdrAggregateExcludeNames(): Set<string> {
  const env = process.env.VITALPBX_CDR_AGGREGATE_EXCLUDE_NAMES;
  if (env === undefined || env === null) {
    return new Set(["smoke", "billing", "test"]);
  }
  const raw = env.trim();
  if (raw === "" || raw.toLowerCase() === "none") return new Set<string>();
  return new Set(raw.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean));
}

const _pbxKpiCache = new Map<string, { ts: number; data: any }>();
const _pbxKpiInflight = new Map<string, Promise<any>>();
const _pbxCdrCache: { ts: number; rows: any[]; byTenant: Map<string, any[]> } = { ts: 0, rows: [], byTenant: new Map() };
const PBX_KPI_BG_INTERVAL_MS = 30_000;
let _pbxBgStarted = false;
let _pbxRefreshRunning = false;
let _pbxTickCount = 0;
let _pbxLastEndSec = 0; // Unix sec of the last data point in cache
let _pbxActiveTenantIds: string[] = []; // Tenants with CDRs
let _pbxIdToName = new Map<string, string>();
let _pbxLinks: Array<{ pbxTenantId: string | null; tenantId: string }> = [];
let _pbxGlobalFailCount = 0;
let _pbxGlobalNextAllowedAt = 0;

function classifyRow(r: any): { direction: string; isIncoming: boolean; isMissed: boolean } {
  const ct = Number(r?.calltype ?? r?.callType ?? 0);
  let direction = "unknown";
  let isIncoming = false;
  if (ct === 2) { direction = "incoming"; isIncoming = true; }
  else if (ct === 3) { direction = "outgoing"; }
  else if (ct === 1) { direction = "internal"; }
  else {
    const dir = String(r?.direction || r?.call_type || "").toLowerCase();
    if (dir.includes("in") && !dir.includes("internal")) { direction = "incoming"; isIncoming = true; }
    else if (dir.includes("internal")) { direction = "internal"; }
    else { direction = "outgoing"; }
  }
  const disp = String(r?.disposition || "").toUpperCase();
  const isMissed = disp !== "ANSWERED" && isIncoming;
  return { direction, isIncoming, isMissed };
}


async function refreshPerTenantData(instance: any, auth: any, tz: string, t0: number, deltaOnly = false) {
  const client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret, timeoutMs: deltaOnly ? 30_000 : 60_000 });

  if (!deltaOnly) {
    const tenantList = await client.listTenants();
    _pbxIdToName = new Map<string, string>();
    const allTenantIds: string[] = [];
    for (const t of tenantList) {
      const id = String((t as any).tenant_id ?? (t as any).id ?? "").trim();
      const name = String((t as any).name ?? "").trim();
      if (id && name) { _pbxIdToName.set(id, name); allTenantIds.push(id); }
    }
    _pbxActiveTenantIds = allTenantIds;
    _pbxLinks = (await db.tenantPbxLink.findMany()).map(l => ({ pbxTenantId: l.pbxTenantId, tenantId: l.tenantId }));
  }

  const perTenantCounts = new Map<string, { incoming: number; outgoing: number; internal: number; missed: number; total: number }>();
  const allRows: any[] = [];
  const activeTids: string[] = [];

  for (const tid of _pbxActiveTenantIds) {
    try {
      const tData = await client.getCdrToday(tid, { timezone: tz, chunkSec: 1800 });
      perTenantCounts.set(tid, { incoming: tData.incoming, outgoing: tData.outgoing, internal: tData.internal, missed: tData.missed, total: tData.total });
      if (tData.total > 0) activeTids.push(tid);
      for (const r of tData.allRawRows) {
        if (!r.tenantid && !r.tenant_id && !r.tenant) r.tenantid = tid;
        allRows.push(r);
      }
    } catch { /* skip */ }
  }
  if (activeTids.length > 0) _pbxActiveTenantIds = activeTids;
  _pbxLastEndSec = Math.floor(Date.now() / 1000);

  const now = Date.now();
  const asOf = new Date().toISOString();

  const pbxToConnect = new Map<string, string>();
  for (const l of _pbxLinks) { if (l.pbxTenantId) pbxToConnect.set(l.pbxTenantId.trim(), l.tenantId); }
  const cdrByConnect = new Map<string, any[]>();
  for (const [tid, counts] of perTenantCounts) {
    const tName = _pbxIdToName.get(tid) || tid;
    const tenantData = {
      incomingToday: counts.incoming, outgoingToday: counts.outgoing, internalToday: counts.internal,
      missedToday: counts.missed, cdrRowsTotalAcrossTenants: counts.total,
      scope: "tenant" as const, tenantsQueried: 1, source: "pbx" as const, asOf, _ts: now,
    };
    const connectId = pbxToConnect.get(tid);
    if (connectId) _pbxKpiCache.set(`pbx:${connectId}`, { ts: now, data: tenantData });
    _pbxKpiCache.set(`pbx:vpbx:${normSlug(tName)}`, { ts: now, data: tenantData });
  }
  const rowsByTenant = new Map<string, any[]>();
  for (const r of allRows) {
    const tid = String(r?.tenantid ?? r?.tenant_id ?? r?.tenant ?? "0").trim();
    if (!rowsByTenant.has(tid)) rowsByTenant.set(tid, []);
    rowsByTenant.get(tid)!.push(r);
  }
  for (const [tid, rows] of rowsByTenant) {
    const connectId = pbxToConnect.get(tid);
    if (connectId) cdrByConnect.set(connectId, rows);
    const tName = _pbxIdToName.get(tid) || tid;
    cdrByConnect.set(`vpbx:${normSlug(tName)}`, rows);
  }
  _pbxCdrCache.ts = now;
  _pbxCdrCache.rows = allRows;
  _pbxCdrCache.byTenant = cdrByConnect;
  app.log.info({ elapsedMs: Date.now() - t0, totalRawRows: allRows.length, tenants: perTenantCounts.size, mode: deltaOnly ? "delta-tenant-cache" : "full-tenant-cache" }, "pbx-kpi-bg: refresh ok");
}

/**
 * Fetch KPI stats directly from the VitalPBX admin dashboard page.
 * VitalPBX's dashboard queries SELECT SUM(IF(calltype=N,1,0)) on the
 * global CDR table — no per-tenant scoping. We scrape those exact numbers
 * so Connect shows the exact same values.
 */
async function fetchPbxDashboardStats(baseUrl: string, appKey: string): Promise<{ incoming: number; outgoing: number; internal: number; transit: number } | null> {
  try {
    const dashUrl = `${baseUrl.replace(/\/+$/, "")}/index.php`;
    const res = await fetch(dashUrl, {
      headers: { "app-key": appKey, accept: "text/html,application/xhtml+xml,*/*" },
      signal: AbortSignal.timeout(15_000),
    });
    if (!res.ok) return null;
    const html = await res.text();

    // VitalPBX 4 dashboard embeds "Calls Traffic Today" stats. Try multiple parsing strategies.
    // Strategy 1: look for JSON data object with call counts
    const jsonMatch = html.match(/"?incoming"?\s*[:=]\s*(\d+)[\s\S]*?"?outgoing"?\s*[:=]\s*(\d+)[\s\S]*?"?internal"?\s*[:=]\s*(\d+)/i);
    if (jsonMatch) {
      return { incoming: Number(jsonMatch[1]), outgoing: Number(jsonMatch[2]), internal: Number(jsonMatch[3]), transit: 0 };
    }

    // Strategy 2: look for the pie chart data pattern (common in VitalPBX 4)
    const pieMatch = html.match(/Outgoing[^0-9]*(\d+)[^0-9]*Incoming[^0-9]*(\d+)[^0-9]*Internal[^0-9]*(\d+)/i)
      || html.match(/Incoming[^0-9]*(\d+)[^0-9]*Outgoing[^0-9]*(\d+)[^0-9]*Internal[^0-9]*(\d+)/i);
    if (pieMatch) {
      const labels = html.match(/Outgoing/i) ? ["outgoing", "incoming", "internal"] : ["incoming", "outgoing", "internal"];
      const vals = [Number(pieMatch[1]), Number(pieMatch[2]), Number(pieMatch[3])];
      const obj = { incoming: 0, outgoing: 0, internal: 0, transit: 0 };
      labels.forEach((l, i) => { (obj as any)[l] = vals[i]; });
      return obj;
    }

    // Strategy 3: look for numeric values near "Outgoing", "Incoming", "Internal" labels
    const extract = (label: string) => {
      const re = new RegExp(`${label}[^0-9]{0,40}?(\\d+)`, "i");
      const m = html.match(re);
      return m ? Number(m[1]) : 0;
    };
    const incoming = extract("Incoming");
    const outgoing = extract("Outgoing");
    const internal = extract("Internal");
    if (incoming > 0 || outgoing > 0) {
      return { incoming, outgoing, internal, transit: 0 };
    }

    return null;
  } catch {
    return null;
  }
}

/**
 * Alternative: try calling the CDR API WITHOUT a tenant header.
 * If VitalPBX returns global CDRs in admin mode, this gives exact counts.
 */
async function fetchGlobalCdrCounts(
  baseUrl: string,
  appKey: string,
  secret: string | undefined,
  tz: string
): Promise<{ incoming: number; outgoing: number; internal: number; missed: number; total: number; rows: any[] } | null> {
  try {
    const nowUtc = new Date();
    const todayStr = nowUtc.toLocaleDateString("en-CA", { timeZone: tz });
    const [y, mo, d] = todayStr.split("-").map(Number);
    const noonUtc = Date.UTC(y!, mo! - 1, d!, 12, 0, 0, 0);
    const noonLocal = new Date(noonUtc).toLocaleTimeString("en-US", {
      timeZone: tz, hour: "numeric", minute: "numeric", hour12: false
    });
    const [hStr, mStr] = noonLocal.split(":");
    const offsetMs = ((Number(hStr ?? 0) * 60) + Number(mStr ?? 0)) * 60 * 1000;
    const dayStartUtc = new Date(noonUtc - offsetMs);
    const startSec = Math.floor(dayStartUtc.getTime() / 1000);
    const endSec = Math.floor(nowUtc.getTime() / 1000);

    const client = getVitalPbxClient({
      baseUrl,
      token: appKey,
      secret,
      timeoutMs: 20_000,
    });

    // Single lightweight global CDR read (no tenant header) to avoid PBX CPU overload.
    // We intentionally avoid multi-page scans in the 30s loop.
    const envelope = await client.callEndpoint<any>("cdr.list", {
      query: {
        limit: 1000,
        sort_by: "date",
        sort_order: "desc",
        start_date: startSec,
        end_date: endSec,
      },
    });
    const data = (envelope as any)?.data ?? envelope;
    const rows = Array.isArray(data?.result)
      ? data.result
      : Array.isArray(data?.items)
        ? data.items
        : Array.isArray(data?.rows)
          ? data.rows
          : Array.isArray(data)
            ? data
            : [];
    let candidateRows = rows;
    if (candidateRows.length === 0) {
      // Fallback: some PBX global contexts ignore date range params.
      // Do a single lightweight latest-rows read and filter to "today" locally.
      const envelope2 = await client.callEndpoint<any>("cdr.list", {
        query: {
          limit: 1000,
          sort_by: "date",
          sort_order: "desc",
        },
      });
      const data2 = (envelope2 as any)?.data ?? envelope2;
      const rows2 = Array.isArray(data2?.result)
        ? data2.result
        : Array.isArray(data2?.items)
          ? data2.items
          : Array.isArray(data2?.rows)
            ? data2.rows
            : Array.isArray(data2)
              ? data2
              : [];
      const todayKey = nowUtc.toLocaleDateString("en-CA", { timeZone: tz });
      candidateRows = rows2.filter((r: any) => {
        const raw = String(r?.date ?? r?.start ?? r?.calldate ?? "").trim();
        if (!raw) return false;
        if (/^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 10) === todayKey;
        const parsed = new Date(raw);
        if (Number.isNaN(parsed.getTime())) return false;
        return parsed.toLocaleDateString("en-CA", { timeZone: tz }) === todayKey;
      });
    }
    if (candidateRows.length === 0) return null;

    let incoming = 0, outgoing = 0, internal = 0, missed = 0;
    for (const r of candidateRows) {
      // PBX dashboard excludes rows with empty tenant.
      const tenant = String(r?.tenant ?? r?.tenantid ?? r?.tenant_id ?? "").trim();
      if (!tenant) continue;
      const ct = Number(r?.calltype ?? r?.callType ?? 0);
      if (ct === 2) { incoming++; const disp = String(r?.disposition || "").toUpperCase(); if (disp !== "ANSWERED") missed++; }
      else if (ct === 3) outgoing++;
      else if (ct === 1) internal++;
    }
    return { incoming, outgoing, internal, missed, total: incoming + outgoing + internal, rows: candidateRows };
  } catch {
    return null;
  }
}

async function fetchTenantCdrCounts(
  baseUrl: string,
  appKey: string,
  secret: string | undefined,
  timezone: string,
  pbxTenantId: string,
): Promise<{ incoming: number; outgoing: number; internal: number; missed: number; total: number } | null> {
  try {
    const client = getVitalPbxClient({
      baseUrl,
      token: appKey,
      secret,
      timeoutMs: 20_000,
    });
    const data = await client.getCdrToday(pbxTenantId, { timezone, chunkSec: 1800 });
    return {
      incoming: data.incoming,
      outgoing: data.outgoing,
      internal: data.internal,
      missed: data.missed,
      total: data.total,
    };
  } catch {
    return null;
  }
}

async function resolvePbxTenantScope(scopeTenantId: string): Promise<{ pbxTenantId: string | null; scopeLabel: string | null }> {
  if (!scopeTenantId) return { pbxTenantId: null, scopeLabel: null };
  if (scopeTenantId.startsWith("vpbx:")) {
    const slug = normSlug(scopeTenantId.slice(5));
    const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
    if (!instance) return { pbxTenantId: null, scopeLabel: scopeTenantId };
    const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
    const client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret, timeoutMs: 20_000 });
    const tenants = await client.listTenants();
    const t = tenants.find((x: any) => normSlug(String(x?.name || "")) === slug);
    const id = t ? String((t as any).tenant_id ?? (t as any).id ?? "").trim() : "";
    return { pbxTenantId: id || null, scopeLabel: scopeTenantId };
  }
  const link = await db.tenantPbxLink.findUnique({ where: { tenantId: scopeTenantId }, include: { tenant: true } });
  if (link?.pbxTenantId) return { pbxTenantId: link.pbxTenantId.trim(), scopeLabel: link.tenant?.name ?? scopeTenantId };
  return { pbxTenantId: null, scopeLabel: scopeTenantId };
}

async function fetchLivePbxKpisByScope(params: {
  scopeTenantId: string | null;
  timezone: string;
  asOfIso: string;
}): Promise<any> {
  const { scopeTenantId, timezone, asOfIso } = params;
  const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  if (!instance) throw new Error("PBX_UNAVAILABLE_NO_INSTANCE");
  const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);

  if (!scopeTenantId) {
    const dashStats = await fetchPbxDashboardStats(instance.baseUrl, auth.token);
    if (dashStats && (dashStats.incoming > 0 || dashStats.outgoing > 0 || dashStats.internal > 0)) {
      return {
        incomingToday: dashStats.incoming,
        outgoingToday: dashStats.outgoing,
        internalToday: dashStats.internal,
        missedToday: 0,
        cdrRowsTotalAcrossTenants: dashStats.incoming + dashStats.outgoing + dashStats.internal + dashStats.transit,
        scope: "global" as const,
        tenantsQueried: 0,
        source: "pbx-dashboard",
        asOf: asOfIso,
      };
    }
    const live = await fetchGlobalCdrCounts(instance.baseUrl, auth.token, auth.secret, timezone);
    if (!live || live.total <= 0) throw new Error("PBX_UNAVAILABLE_GLOBAL_FETCH_FAILED");
    return {
      incomingToday: live.incoming,
      outgoingToday: live.outgoing,
      internalToday: live.internal,
      missedToday: live.missed,
      cdrRowsTotalAcrossTenants: live.total,
      scope: "global" as const,
      tenantsQueried: 0,
      source: "pbx-global-cdr",
      asOf: asOfIso,
    };
  }

  const scope = await resolvePbxTenantScope(scopeTenantId);
  if (!scope.pbxTenantId) throw new Error("PBX_UNAVAILABLE_TENANT_MAPPING");
  const live = await fetchTenantCdrCounts(instance.baseUrl, auth.token, auth.secret, timezone, scope.pbxTenantId);
  if (!live) throw new Error("PBX_UNAVAILABLE_TENANT_FETCH_FAILED");
  return {
    incomingToday: live.incoming,
    outgoingToday: live.outgoing,
    internalToday: live.internal,
    missedToday: live.missed,
    cdrRowsTotalAcrossTenants: live.total,
    scope: "tenant" as const,
    tenantId: scopeTenantId,
    tenantsQueried: 1,
    source: "pbx-tenant-cdr",
    asOf: asOfIso,
  };
}

function startPbxKpiBackgroundRefresh() {
  if (_pbxBgStarted) return;
  _pbxBgStarted = true;
  const tz = process.env.PBX_TIMEZONE || "America/New_York";

  const doRefresh = async () => {
    if (_pbxRefreshRunning) return;
    // Failure backoff: if global source is unavailable, avoid hammering PBX every 30s.
    if (Date.now() < _pbxGlobalNextAllowedAt) return;
    _pbxRefreshRunning = true;
    const t0 = Date.now();
    _pbxTickCount++;

    try {
      const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
      if (!instance) { app.log.warn("pbx-kpi-bg: no PBX instance"); return; }
      const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);

      // ── PRIMARY: try getting stats directly from PBX dashboard (exact match) ──
      const dashStats = await fetchPbxDashboardStats(instance.baseUrl, auth.token);
      if (dashStats && (dashStats.incoming > 0 || dashStats.outgoing > 0)) {
        const now = Date.now();
        const asOf = new Date().toISOString();
        _pbxGlobalFailCount = 0;
        _pbxGlobalNextAllowedAt = 0;
        _pbxKpiCache.set("pbx:global", { ts: now, data: {
          incomingToday: dashStats.incoming, outgoingToday: dashStats.outgoing, internalToday: dashStats.internal,
          missedToday: 0, cdrRowsTotalAcrossTenants: dashStats.incoming + dashStats.outgoing + dashStats.internal + dashStats.transit,
          scope: "global", tenantsQueried: 0, source: "pbx-dashboard", asOf, _ts: now,
        }});
        app.log.info({ elapsedMs: Date.now() - t0, incoming: dashStats.incoming, outgoing: dashStats.outgoing, internal: dashStats.internal, mode: "dashboard-scrape" }, "pbx-kpi-bg: refresh ok");

        return;
      }

      // ── SECONDARY: try global CDR query without tenant header ──
      const globalCdr = await fetchGlobalCdrCounts(instance.baseUrl, auth.token, auth.secret, tz);
      if (globalCdr && globalCdr.total > 0) {
        const now = Date.now();
        const asOf = new Date().toISOString();
        _pbxGlobalFailCount = 0;
        _pbxGlobalNextAllowedAt = 0;
        _pbxKpiCache.set("pbx:global", { ts: now, data: {
          incomingToday: globalCdr.incoming, outgoingToday: globalCdr.outgoing, internalToday: globalCdr.internal,
          missedToday: globalCdr.missed, cdrRowsTotalAcrossTenants: globalCdr.total,
          scope: "global", tenantsQueried: 0, source: "pbx-global-cdr", asOf, _ts: now,
        }});
        _pbxCdrCache.ts = now;
        _pbxCdrCache.rows = globalCdr.rows;
        app.log.info({ elapsedMs: Date.now() - t0, incoming: globalCdr.incoming, outgoing: globalCdr.outgoing, internal: globalCdr.internal, total: globalCdr.total, mode: "global-cdr" }, "pbx-kpi-bg: refresh ok");

        return;
      }

      // Keep last-known good PBX global cache; do NOT fall back to Connect-derived totals.
      _pbxGlobalFailCount += 1;
      const backoffMs = Math.min(5 * 60_000, Math.max(30_000, _pbxGlobalFailCount * 30_000));
      _pbxGlobalNextAllowedAt = Date.now() + backoffMs;
      app.log.warn({ elapsedMs: Date.now() - t0 }, "pbx-kpi-bg: global source unavailable, keeping last global KPI cache");
    } catch (err: any) {
      _pbxGlobalFailCount += 1;
      const backoffMs = Math.min(5 * 60_000, Math.max(30_000, _pbxGlobalFailCount * 30_000));
      _pbxGlobalNextAllowedAt = Date.now() + backoffMs;
      app.log.warn({ err: err?.message, elapsedMs: Date.now() - t0 }, "pbx-kpi-bg: refresh failed");
    } finally {
      _pbxRefreshRunning = false;
    }
  };

  registerShutdownTimer(setTimeout(doRefresh, 0));
  registerShutdownTimer(setInterval(doRefresh, PBX_KPI_BG_INTERVAL_MS));
}

/**
 * Diagnostics-only helper — reads from background cache or does a single global query.
 * Used by /admin/diagnostics/pbx-cdr-today-kpis. No per-tenant fan-out.
 */
async function aggregateVitalpbxTodayCallKpis(opts: {
  timezone: string;
  pbxScopeSlug: string | null;
  pbxScopeNumericId: string | null;
  responseTenantId: string | null;
}): Promise<any> {
  // Try cache first
  const cacheKey = opts.responseTenantId
    ? (opts.pbxScopeSlug ? `pbx:vpbx:${normSlug(opts.pbxScopeSlug)}` : `pbx:${opts.responseTenantId}`)
    : "pbx:global";
  const cached = _pbxKpiCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < 120_000) return cached.data;
  const globalCached = _pbxKpiCache.get("pbx:global");
  if (!opts.responseTenantId && globalCached && Date.now() - globalCached.ts < 120_000) return globalCached.data;
  // Fallback: PBX query (global or tenant-scoped)
  const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  if (!instance) throw new Error("NO_PBX_INSTANCE");
  const auth = decryptJson<{ token: string; secret?: string }>(instance.apiAuthEncrypted);
  const client = getVitalPbxClient({ baseUrl: instance.baseUrl, token: auth.token, secret: auth.secret, timeoutMs: 45_000 });
  let pbxTenantId: string | undefined;
  if (opts.pbxScopeNumericId) {
    pbxTenantId = opts.pbxScopeNumericId;
  } else if (opts.pbxScopeSlug) {
    const tenants = await client.listTenants();
    const slug = normSlug(opts.pbxScopeSlug);
    const t = tenants.find((x: any) => normSlug(String(x?.name || "")) === slug);
    const id = t ? String((t as any).tenant_id ?? (t as any).id ?? "").trim() : "";
    if (id) pbxTenantId = id;
  }
  const data = await client.getCdrToday(pbxTenantId, { timezone: opts.timezone, chunkSec: 1800 });
  return {
    incomingToday: data.incoming, outgoingToday: data.outgoing, internalToday: data.internal,
    missedToday: data.missed, cdrRowsTotalAcrossTenants: data.total,
    scope: opts.responseTenantId ? "tenant" : "global",
    ...(opts.responseTenantId ? { tenantId: opts.responseTenantId } : {}),
    tenantsQueried: 1, source: "pbx",
    asOf: new Date().toISOString(),
  };
}

app.get("/dashboard/call-kpis", async (req, reply) => {
  const user = await requirePermission(req, reply, canViewCustomers);
  if (!user) return;

  const query = z.object({
    tenantId: z.string().optional(),
    source: z.enum(["connect", "pbx"]).optional().default("pbx"),
    mode: z.enum(["raw", "canonical"]).optional().default("raw"),
    range: z.enum(["today", "7d", "30d", "custom"]).optional().default("today"),
    from: z.string().optional(),
    to: z.string().optional(),
  }).parse(req.query || {});

  const customFrom = query.range === "custom" && query.from ? new Date(query.from) : null;
  const customTo = query.range === "custom" && query.to ? new Date(query.to) : null;

  const extensionScoped = await isExtensionScopedCallViewerForUser(user);
  const userExtensions = extensionScoped ? await getUserExtensionNumbers(user) : [];
  const wantPbxAggregate = query.source === "pbx" && !extensionScoped;

  const isSuperAdmin = isSuperAdminUser(user);
  // tenantId param is only honoured for super admins; regular users get their own tenant
  const scopeTenantId = isSuperAdmin
    ? (query.tenantId && query.tenantId !== "global" ? query.tenantId : null)
    : user.tenantId ?? null;

  const nowUtc = new Date();
  const { timezone } = computePbxLocalDayRangeUtc(nowUtc);

  if (extensionScoped && userExtensions.length === 0) {
    const emptyActivity = await aggregateDashboardCallActivity({
      tenantFilter: { tenantId: "__no_extensions__" },
      extensionFilter: [],
      range: query.range,
      customFrom,
      customTo,
    });
    return reply.send({
      incomingToday: 0,
      outgoingToday: 0,
      outgoingForwardedToday: 0,
      outgoingDirectToday: 0,
      internalToday: 0,
      missedToday: 0,
      canceledToday: 0,
      callsToday: 0,
      range: query.range,
      timezone: emptyActivity.timezone,
      windowFrom: emptyActivity.timeWhere.gte.toISOString(),
      windowTo: emptyActivity.timeWhere.lt.toISOString(),
      scope: "extension" as const,
      tenantId: user.tenantId ?? null,
      extensions: [],
      asOf: nowUtc.toISOString(),
      source: "connect" as const,
      mode: query.mode,
    });
  }

  if (wantPbxAggregate) {
    const cacheKey = `pbx:${scopeTenantId ?? "global"}`;
    const cached = _pbxKpiCache.get(cacheKey);
    if (cached) {
      const age = Date.now() - cached.ts;
      const stale = age > 30_000;
      if (stale && !_pbxKpiInflight.has(cacheKey)) {
        const refresh = fetchLivePbxKpisByScope({
          scopeTenantId,
          timezone,
          asOfIso: nowUtc.toISOString(),
        })
          .then((payload) => {
            _pbxKpiCache.set(cacheKey, { ts: Date.now(), data: payload });
            return payload;
          })
          .catch((err: any) => {
            app.log.warn({ err: err?.message || String(err), cacheKey }, "dashboard_call_kpis_bg_refresh_failed");
            return null;
          })
          .finally(() => {
            _pbxKpiInflight.delete(cacheKey);
          });
        _pbxKpiInflight.set(cacheKey, refresh);
      }
      const { perTenant: _pt, ...rest } = cached.data;
      return reply.send({
        ...rest,
        cached: true,
        cacheAgeMs: age,
        lastUpdated: cached.data?.asOf || new Date(cached.ts).toISOString(),
        stale,
        refreshInProgress: _pbxKpiInflight.has(cacheKey),
      });
    }
    try {
      let inflight = _pbxKpiInflight.get(cacheKey);
      if (!inflight) {
        inflight = fetchLivePbxKpisByScope({
          scopeTenantId,
          timezone,
          asOfIso: nowUtc.toISOString(),
        });
        _pbxKpiInflight.set(cacheKey, inflight);
      }
      const payload = await inflight;
      _pbxKpiCache.set(cacheKey, { ts: Date.now(), data: payload });
      return reply.send({ ...payload, cached: false, cacheAgeMs: 0, lastUpdated: payload?.asOf || nowUtc.toISOString(), stale: false, refreshInProgress: false });
    } catch {
      // Tenant scope only: PBX fallback path (still PBX, not Connect).
      if (scopeTenantId) {
        try {
          const agg = await aggregateVitalpbxTodayCallKpis({
            timezone,
            pbxScopeSlug: scopeTenantId.startsWith("vpbx:") ? scopeTenantId.slice(5) : null,
            pbxScopeNumericId: !scopeTenantId.startsWith("vpbx:")
              ? (await db.tenantPbxLink.findUnique({ where: { tenantId: scopeTenantId } }))?.pbxTenantId ?? null
              : null,
            responseTenantId: scopeTenantId,
          });
          _pbxKpiCache.set(cacheKey, { ts: Date.now(), data: agg });
          return reply.send({ ...agg, cached: false, cacheAgeMs: 0, fallbackPath: "aggregateVitalpbxTodayCallKpis" });
        } catch {
          // continue to stale/503 behavior below
        }
      }
      const prev = _pbxKpiCache.get(cacheKey);
      if (prev) {
        const { perTenant: _pt, ...rest } = prev.data;
        return reply.send({ ...rest, cached: true, cacheAgeMs: Date.now() - prev.ts, stale: true });
      }
      return reply.code(503).send({ error: "PBX source unavailable (live fetch failed). Retrying automatically." });
    } finally {
      _pbxKpiInflight.delete(cacheKey);
    }
  }

  try {
    // Broaden the tenant filter so we match rows whether they were ingested with
    // the Connect cuid or the "vpbx:{slug}" placeholder form.
    const tenantIdSet = scopeTenantId ? await resolveTenantIdFilterSet(scopeTenantId) : null;
    const tenantClause: Record<string, unknown> = tenantIdSet && tenantIdSet.length > 0
      ? (tenantIdSet.length === 1 ? { tenantId: tenantIdSet[0] } : { tenantId: { in: tenantIdSet } })
      : {};
    const activity = await aggregateDashboardCallActivity({
      tenantFilter: tenantClause,
      extensionFilter: extensionScoped ? userExtensions : null,
      range: query.range,
      customFrom,
      customTo,
      logContext: { endpoint: "call-kpis", tenantId: scopeTenantId, tenantIdSet, role: user.role, range: query.range },
    });

    // Forwarded outbound legs: inbound call auto-forwarded to external number (find-me/follow-me).
    // Kept as supplemental metadata; primary KPI/chart counts come from the shared
    // normalized aggregation above so they cannot drift.
    const outgoingForwardedWhere: any = {
      ...tenantClause,
      startedAt: activity.timeWhere,
      direction: "outgoing",
      isForwarded: true,
    };
    const outgoingForwardedExtensionVisibility = extensionScoped ? buildCdrExtensionVisibilityClause(userExtensions) : null;
    if (outgoingForwardedExtensionVisibility) outgoingForwardedWhere.AND = [outgoingForwardedExtensionVisibility];
    const outgoingForwarded = await db.connectCdr.count({
      where: outgoingForwardedWhere,
    });

    // Canonical mode: direction is authoritative at ingest (callDirectionPolicy + merged dcontexts).
    // No SQL-time reclassification — avoids dashboard drift vs call history.
    let canonicalCounts: { incoming: number; outgoing: number; internal: number; missed: number; canceled: number; total: number; outgoingForwarded: number } | null = null;
    if (query.mode === "canonical") {
      canonicalCounts = {
        incoming: activity.totals.incoming,
        outgoing: activity.totals.outgoing,
        internal: activity.totals.internal,
        missed: activity.totals.missed,
        canceled: activity.totals.canceled,
        total: activity.totals.total,
        outgoingForwarded: Number(outgoingForwarded),
      };
    }

    const base = {
      incomingToday: activity.totals.incoming,
      outgoingToday: activity.totals.outgoing,
      outgoingForwardedToday: outgoingForwarded,
      outgoingDirectToday: activity.totals.outgoing - Number(outgoingForwarded),
      internalToday: activity.totals.internal,
      missedToday: activity.totals.missed,
      canceledToday: activity.totals.canceled,
      callsToday: activity.totals.total,
      range: query.range,
      timezone: activity.timezone,
      windowFrom: activity.timeWhere.gte.toISOString(),
      windowTo: activity.timeWhere.lt.toISOString(),
      scope: extensionScoped ? "extension" as const : (scopeTenantId ? "tenant" as const : "global" as const),
      ...(scopeTenantId ? { tenantId: scopeTenantId } : {}),
      ...(extensionScoped ? { extensions: userExtensions } : {}),
      asOf: nowUtc.toISOString(),
      source: "connect" as const,
      mode: query.mode,
      ...(wantPbxAggregate ? { pbxFallback: true as const } : {}),
    };

    if (canonicalCounts) {
      return reply.send({
        ...base,
        canonical: canonicalCounts,
        // When canonical mode is active, expose corrected values as the primary KPIs
        // so the dashboard can display them directly; raw values remain available.
        raw: {
          incomingToday: activity.totals.incoming,
          outgoingToday: activity.totals.outgoing,
          internalToday: activity.totals.internal,
          missedToday: activity.totals.missed,
        },
        incomingToday: canonicalCounts.incoming,
        outgoingToday: canonicalCounts.outgoing,
        internalToday: canonicalCounts.internal,
        missedToday:   canonicalCounts.missed,
        outgoingForwardedToday: canonicalCounts.outgoingForwarded,
        outgoingDirectToday: canonicalCounts.outgoing - canonicalCounts.outgoingForwarded,
      });
    }

    return reply.send(base);
  } catch (err: any) {
    app.log.error({ err: err?.message }, "call-kpis: db error");
    return reply.code(500).send({ error: "db_error" });
  }
});

// ─── CDR Tenant Mapping Rules (admin) ────────────────────────────────────────
// Lets super-admins configure DID/extension patterns → VitalPBX tenant slug mappings.
// These rules are used by /internal/cdr-ingest to assign tenantId when AMI events
// don't carry enough tenant information.
//
// GET  /admin/cdr/tenant-rules           → list all rules
// POST /admin/cdr/tenant-rules           → create or update a rule (upsert by matchType+matchValue)
// DELETE /admin/cdr/tenant-rules/:id     → delete a rule
// POST /admin/cdr/tenant-rules/backfill  → retroactively apply rules to existing CDR rows with tenantId=null

app.get("/admin/cdr/tenant-rules", async (req, reply) => {
  const admin = await requirePermission(req, reply, (u) => isRole(u, ["SUPER_ADMIN"]));
  if (!admin) return;
  const rules = await db.cdrTenantRule.findMany({ orderBy: { createdAt: "asc" } });
  return { rules };
});

app.post("/admin/cdr/tenant-rules", async (req, reply) => {
  const admin = await requirePermission(req, reply, (u) => isRole(u, ["SUPER_ADMIN"]));
  if (!admin) return;
  const input = z.object({
    matchType:   z.enum(["did", "from_did", "extension_prefix"]),
    matchValue:  z.string().min(1).max(30),
    tenantSlug:  z.string().min(1).max(100),
    description: z.string().max(200).optional(),
  }).parse(req.body || {});

  const rule = await db.cdrTenantRule.upsert({
    where: { matchType_matchValue: { matchType: input.matchType, matchValue: input.matchValue } },
    create: { ...input },
    update: { tenantSlug: input.tenantSlug, description: input.description ?? undefined },
  });
  invalidateCdrRulesCache();
  return { ok: true, rule };
});

app.delete("/admin/cdr/tenant-rules/:id", async (req, reply) => {
  const admin = await requirePermission(req, reply, (u) => isRole(u, ["SUPER_ADMIN"]));
  if (!admin) return;
  const { id } = req.params as { id: string };
  await db.cdrTenantRule.delete({ where: { id } }).catch(() => null);
  invalidateCdrRulesCache();
  return { ok: true };
});

// Retroactively apply current rules to ConnectCdr rows that still have tenantId=null.
// Returns the number of rows updated.
app.post("/admin/cdr/tenant-rules/backfill", async (req, reply) => {
  const admin = await requirePermission(req, reply, (u) => isRole(u, ["SUPER_ADMIN"]));
  if (!admin) return;

  // Pre-fetch VitalPBX tenant map once for the whole backfill
  let tenantMap: Map<string, string>;
  try {
    tenantMap = await getVpbxTenantLookup();
  } catch {
    tenantMap = new Map();
  }

  // Process in batches to avoid loading too many rows at once.
  // Uses all resolution strategies: dcontext, channels, admin rules.
  let updated = 0;
  let cursor: string | undefined;
  while (true) {
    const batch = await db.connectCdr.findMany({
      where: { tenantId: null },
      take: 200,
      skip: cursor ? 1 : 0,
      cursor: cursor ? { id: cursor } : undefined,
      orderBy: { id: "asc" },
      select: { id: true, fromNumber: true, toNumber: true, hangupCause: true },
    });
    if (batch.length === 0) break;
    cursor = batch[batch.length - 1]!.id;

    for (const row of batch) {
      // Admin-configured DID/extension rules only. Does NOT fix direction or totals — use
      // POST /admin/cdr/fix-directions for misclassified ConnectCdr; optional PBX KPI compare: ?source=pbx + CALL_KPIS_USE_VITALPBX_API=true.
      const tenantId = await resolveTenantFromRules(row.fromNumber, row.toNumber);
      if (tenantId) {
        await db.connectCdr.update({ where: { id: row.id }, data: { tenantId } });
        updated++;
      }
    }
  }

  app.log.info({ updated }, "cdr: tenant rules backfill complete");
  return reply.send({ ok: true, updated });
});

// POST /admin/cdr/repair-recent?days=7&dryRun=true — re-run tenant + direction resolution for recent rows.
app.post("/admin/cdr/repair-recent", async (req, reply) => {
  const admin = await requirePermission(req, reply, (u) => isRole(u, ["SUPER_ADMIN"]));
  if (!admin) return;

  const query = z.object({
    days: z.coerce.number().int().min(1).max(30).optional().default(7),
    dryRun: z.enum(["true", "false"]).optional().default("true"),
  }).parse(req.query || {});
  const isDryRun = query.dryRun !== "false";
  const since = new Date(Date.now() - query.days * 86_400_000);

  const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  if (!instance) {
    return reply.send({ ok: false, error: "no_pbx_instance", tenantUpdates: 0, directionUpdates: 0 });
  }

  const rows = await db.connectCdr.findMany({
    where: { startedAt: { gte: since } },
    select: {
      id: true,
      linkedId: true,
      fromNumber: true,
      toNumber: true,
      direction: true,
      dcontext: true,
      dcontextsSeen: true,
      channelsSeen: true,
      tenantId: true,
    },
  });

  let tenantUpdates = 0;
  let directionUpdates = 0;
  const samples: Array<{ linkedId: string; field: string; was: string | null; becomes: string | null }> = [];

  for (const row of rows) {
    const mergedDcx = Array.isArray(row.dcontextsSeen) ? ([...(row.dcontextsSeen as string[])] as string[]) : [];
    const mergedCh = Array.isArray(row.channelsSeen) ? ([...(row.channelsSeen as string[])] as string[]) : [];

    const tenantPack = await resolveCdrTenant(db, instance.id, {
      telephonyTenantId: row.tenantId,
      pbxVitalTenantIdHint: null,
      pbxTenantCodeHint: null,
      dcontexts: mergedDcx,
      channels: mergedCh,
      fromNumber: row.fromNumber,
      toNumber: row.toNumber,
      ruleResolver: () => resolveTenantFromRules(row.fromNumber ?? null, row.toNumber ?? null),
    });

    const newDir = canonicalDirection(row.fromNumber, row.toNumber, row.direction, row.dcontext, {
      dcontexts: mergedDcx,
      channelNames: mergedCh,
      telephonyDirectionHint: row.direction,
    });

    const tenantChanged =
      tenantPack.tenantId != null && tenantPack.tenantId !== row.tenantId;
    const dirChanged = newDir !== row.direction && newDir !== "unknown";

    if (tenantChanged) {
      tenantUpdates++;
      if (samples.length < 15) {
        samples.push({
          linkedId: row.linkedId,
          field: "tenantId",
          was: row.tenantId,
          becomes: tenantPack.tenantId,
        });
      }
    }
    if (dirChanged) {
      directionUpdates++;
      if (samples.length < 20) {
        samples.push({
          linkedId: row.linkedId,
          field: "direction",
          was: row.direction,
          becomes: newDir,
        });
      }
    }

    if (!isDryRun && (tenantChanged || dirChanged)) {
      await db.connectCdr.update({
        where: { id: row.id },
        data: {
          ...(tenantChanged
            ? {
                tenantId: tenantPack.tenantId,
                pbxVitalTenantId: tenantPack.pbxVitalTenantId,
                pbxTenantCode: tenantPack.pbxTenantCode,
                tenantResolutionSource: tenantPack.tenantResolutionSource,
              }
            : {}),
          ...(dirChanged ? { direction: newDir } : {}),
        },
      });
    }
  }

  return reply.send({
    ok: true,
    dryRun: isDryRun,
    days: query.days,
    rowsScanned: rows.length,
    tenantUpdates,
    directionUpdates,
    samples,
  });
});

// ─── Fix CDR directions ───────────────────────────────────────────────────────
// POST /admin/cdr/fix-directions?scope=today|all&dryRun=true
// Re-evaluates direction for every ConnectCdr row using canonicalDirection() rules:
//   • from=extension(2-6), to=external(10+) → outgoing  ← primary bug fix
//   • from=external(10+), to=extension(2-6) → incoming
//   • from=extension(2-6), to=extension(2-6) → internal
// Rows that already have the correct direction are skipped.
// dryRun=true (default) only counts; does not write.
app.post("/admin/cdr/fix-directions", async (req, reply) => {
  const admin = await requirePermission(req, reply, (u) => isRole(u, ["SUPER_ADMIN"]));
  if (!admin) return;

  const query = z.object({
    scope: z.enum(["today", "all"]).optional().default("today"),
    dryRun: z.enum(["true", "false"]).optional().default("true"),
  }).parse(req.query || {});

  const isDryRun = query.dryRun !== "false";

  const whereBase = query.scope === "today" ? (() => {
    const { timeWhere } = computePbxLocalDayRangeUtc();
    return { startedAt: timeWhere };
  })() : {};

  const rows = await db.connectCdr.findMany({
    where: whereBase,
    select: {
      id: true,
      linkedId: true,
      fromNumber: true,
      toNumber: true,
      direction: true,
      dcontext: true,
      dcontextsSeen: true,
      channelsSeen: true,
    },
  });

  const changes: Array<{ id: string; linkedId: string; from: string | null; to: string | null; was: string; becomes: string }> = [];

  for (const row of rows) {
    const dcx = Array.isArray(row.dcontextsSeen) ? (row.dcontextsSeen as string[]) : [];
    const chn = Array.isArray(row.channelsSeen) ? (row.channelsSeen as string[]) : [];
    const becomes = canonicalDirection(row.fromNumber, row.toNumber, row.direction, row.dcontext, {
      dcontexts: dcx,
      channelNames: chn,
      telephonyDirectionHint: row.direction,
    });
    if (becomes !== row.direction) {
      changes.push({ id: row.id, linkedId: row.linkedId, from: row.fromNumber, to: row.toNumber, was: row.direction, becomes });
    }
  }

  let fixed = 0;
  if (!isDryRun) {
    for (const ch of changes) {
      await db.connectCdr.update({ where: { id: ch.id }, data: { direction: ch.becomes } });
      fixed++;
      app.log.info({ linkedId: ch.linkedId, from: ch.from, to: ch.to, was: ch.was, becomes: ch.becomes }, "cdr fix-directions: applied");
    }
    app.log.info({ fixed, scope: query.scope }, "cdr: fix-directions complete");
  }

  const summary = changes.reduce<Record<string, number>>((acc, c) => {
    const k = `${c.was}→${c.becomes}`;
    acc[k] = (acc[k] ?? 0) + 1;
    return acc;
  }, {});

  return reply.send({
    ok: true,
    dryRun: isDryRun,
    scope: query.scope,
    rowsScanned: rows.length,
    wouldFix: changes.length,
    fixed: isDryRun ? 0 : fixed,
    summary,
    samples: changes.slice(0, 20).map((c) => ({ linkedId: c.linkedId, from: c.from, to: c.to, was: c.was, becomes: c.becomes })),
  });
});

/** Synced VitalPBX inbound DIDs from PbxTenantInboundDid (no live PBX calls). */
app.get("/dashboard/tenant-phone-numbers", async (req, reply) => {
  const user = await requirePermission(req, reply, canViewCustomers);
  if (!user) return;

  const query = z.object({ tenantId: z.string().optional() }).parse(req.query || {});
  const isSuperAdmin = String(user.role || "").toUpperCase() === "SUPER_ADMIN";

  const instance = await db.pbxInstance.findFirst({ where: { isEnabled: true }, orderBy: { updatedAt: "desc" } });
  if (!instance) {
    return reply.send({
      scope: isSuperAdmin && !query.tenantId?.trim() ? "global" : "tenant",
      pbxInstanceId: null,
      connectTenantId: null,
      connectTenantName: null,
      phoneNumbers: [] as unknown[],
      message: "No enabled PBX instance — inbound DIDs are not synced.",
    });
  }

  // Super-admin, global dashboard: summary only (no tenantId query).
  if (isSuperAdmin && !query.tenantId?.trim()) {
    const [grouped, unlinkedCount, totalActive] = await Promise.all([
      db.pbxTenantInboundDid.groupBy({
        by: ["connectTenantId"],
        where: { pbxInstanceId: instance.id, active: true, connectTenantId: { not: null } },
        _count: { _all: true },
      }),
      db.pbxTenantInboundDid.count({
        where: { pbxInstanceId: instance.id, active: true, connectTenantId: null },
      }),
      db.pbxTenantInboundDid.count({ where: { pbxInstanceId: instance.id, active: true } }),
    ]);
    const ids = grouped.map((g) => g.connectTenantId).filter((id): id is string => !!id);
    const tenants =
      ids.length > 0 ? await db.tenant.findMany({ where: { id: { in: ids } }, select: { id: true, name: true } }) : [];
    const nameById = new Map(tenants.map((t) => [t.id, t.name]));
    const tenantsWithNumbers = grouped
      .filter((g) => g.connectTenantId)
      .map((g) => ({
        connectTenantId: g.connectTenantId!,
        connectTenantName: nameById.get(g.connectTenantId!) ?? "Unknown tenant",
        activeNumberCount: g._count._all,
      }))
      .sort((a, b) => a.connectTenantName.localeCompare(b.connectTenantName));

    return reply.send({
      scope: "global" as const,
      pbxInstanceId: instance.id,
      message:
        "Select tenant scope in the header and pick a tenant to see all phone numbers synced for that workspace. Numbers come from the last PBX tenant refresh (admin), not live API calls.",
      totalActiveNumbers: totalActive,
      unlinkedActiveNumberCount: unlinkedCount,
      tenantsWithNumbers,
    });
  }

  const targetTenantId = isSuperAdmin ? query.tenantId!.trim() : user.tenantId;
  if (!targetTenantId) {
    return reply.status(400).send({ error: "tenant_required", message: "tenantId is required for this user." });
  }
  if (!isSuperAdmin && targetTenantId !== user.tenantId) {
    return reply.status(403).send({ error: "forbidden" });
  }

  const [tenantRow, rows] = await Promise.all([
    db.tenant.findUnique({ where: { id: targetTenantId }, select: { id: true, name: true } }),
    db.pbxTenantInboundDid.findMany({
      where: { pbxInstanceId: instance.id, connectTenantId: targetTenantId, active: true },
      orderBy: [{ e164: "asc" }],
    }),
  ]);

  return reply.send({
    scope: "tenant" as const,
    pbxInstanceId: instance.id,
    connectTenantId: targetTenantId,
    connectTenantName: tenantRow?.name ?? null,
    phoneNumbers: rows.map((r) => ({
      e164: r.e164,
      rawNumber: r.rawNumber,
      pbxTenantId: r.vitalTenantId,
      pbxTenantCode: r.pbxTenantCode,
      pbxTenantSlug: r.pbxTenantSlug,
      active: r.active,
    })),
  });
});

app.get("/dashboard/call-traffic", async (req, reply) => {
  const user = await requirePermission(req, reply, canViewCustomers);
  if (!user) return;
  const query = z.object({
    scope: z.enum(["GLOBAL", "TENANT"]).optional(),
    range: z.enum(["today", "7d", "30d", "custom"]).optional().default("today"),
    from: z.string().optional(),
    to: z.string().optional(),
    windowMinutes: z.coerce.number().int().min(15).max(1440).optional(),
    // Super-admin may pass tenantId to scope a tenant view (mirrors call-kpis behaviour).
    tenantId: z.string().optional(),
  }).parse(req.query || {});

  const customFrom = query.range === "custom" && query.from ? new Date(query.from) : null;
  const customTo = query.range === "custom" && query.to ? new Date(query.to) : null;

  const isSuperAdmin = isSuperAdminUser(user);
  const extensionScoped = await isExtensionScopedCallViewerForUser(user);
  const userExtensions = extensionScoped ? await getUserExtensionNumbers(user) : [];
  const scope = query.scope === "GLOBAL" && isSuperAdmin ? "GLOBAL" : "TENANT";

  // Resolve the effective tenant: super-admin can pass an explicit tenantId param;
  // regular users always use their own tenant from the JWT.
  const scopeTenantId: string | null = isSuperAdmin
    ? (query.tenantId && query.tenantId !== "global" ? query.tenantId : null)
    : (user.tenantId ?? null);

  const nowMs = Date.now();

  if (extensionScoped && userExtensions.length === 0) {
    const emptyActivity = await aggregateDashboardCallActivity({
      tenantFilter: { tenantId: "__no_extensions__" },
      extensionFilter: [],
      range: query.range,
      customFrom,
      customTo,
      logContext: { endpoint: "call-traffic", scope, tenantId: scopeTenantId, role: user.role, range: query.range, noExtensions: true },
    });
    const windowMs = emptyActivity.timeWhere.lt.getTime() - emptyActivity.timeWhere.gte.getTime();
    return {
      scope,
      visibility: "extension" as const,
      extensions: [],
      range: emptyActivity.range,
      timezone: emptyActivity.timezone,
      windowMinutes: Math.round(windowMs / 60_000),
      windowFrom: emptyActivity.timeWhere.gte.toISOString(),
      windowTo: emptyActivity.timeWhere.lt.toISOString(),
      bucketMinutes: emptyActivity.bucketMinutes,
      totals: emptyActivity.totals,
      points: emptyActivity.points,
      updatedAt: new Date(nowMs).toISOString(),
      cached: false,
      lastUpdated: new Date(nowMs).toISOString(),
      stale: false,
      refreshInProgress: false,
      cacheAgeMs: 0,
    };
  }

  // Cache key includes the resolved tenantId + custom range bounds so different scoped views don't bleed into each other.
  const customSuffix = query.range === "custom" ? `:${query.from ?? ""}:${query.to ?? ""}` : "";
  const extensionCacheSuffix = extensionScoped ? `:ext:${userExtensions.join(",")}` : "";
  const cacheKey = `${scope}:${scopeTenantId ?? "all"}:${query.range}${customSuffix}${extensionCacheSuffix}`;
  const cached = DASHBOARD_CALL_TRAFFIC_CACHE.get(cacheKey);
  // Custom ranges are not cached (the bounds are user-controlled).
  if (cached && nowMs - cached.at < 120_000 && query.range !== "custom") {
    return {
      ...cached.payload,
      cached: true,
      lastUpdated: cached.payload?.updatedAt ?? new Date(cached.at).toISOString(),
      stale: false,
      refreshInProgress: false,
      cacheAgeMs: nowMs - cached.at,
    };
  }

  // For global super-admin scope: no tenant filter. Otherwise filter to BOTH the
  // Connect cuid and the "vpbx:{slug}" placeholder form so rows ingested under
  // either label are matched.
  let tenantFilter: Record<string, unknown> = {};
  let tenantIdSet: string[] | null = null;
  if (!((scope === "GLOBAL" && isSuperAdmin) || !scopeTenantId)) {
    tenantIdSet = await resolveTenantIdFilterSet(scopeTenantId);
    if (tenantIdSet && tenantIdSet.length > 0) {
      tenantFilter = tenantIdSet.length === 1 ? { tenantId: tenantIdSet[0] } : { tenantId: { in: tenantIdSet } };
    }
  }

  let activity: DashboardCallActivityAggregate;
  try {
    activity = await aggregateDashboardCallActivity({
      tenantFilter,
      extensionFilter: extensionScoped ? userExtensions : null,
      range: query.range,
      customFrom,
      customTo,
      logContext: { endpoint: "call-traffic", scope, tenantId: scopeTenantId, tenantIdSet, role: user.role, range: query.range },
    });
  } catch (err: any) {
    app.log.error({ err: err?.message, cacheKey }, "dashboard_call_traffic: db query failed");
    // Return stale cache rather than a broken empty response.
    const stale = DASHBOARD_CALL_TRAFFIC_CACHE.get(cacheKey);
    if (stale) {
      return {
        ...stale.payload,
        cached: true,
        lastUpdated: stale.payload?.updatedAt ?? new Date(stale.at).toISOString(),
        stale: true,
        refreshInProgress: false,
        cacheAgeMs: nowMs - stale.at,
      };
    }
    return reply.code(500).send({ error: "db_error" });
  }

  const windowMs = activity.timeWhere.lt.getTime() - activity.timeWhere.gte.getTime();
  const payload = {
    scope,
    ...(extensionScoped ? { visibility: "extension" as const, extensions: userExtensions } : {}),
    range: activity.range,
    timezone: activity.timezone,
    windowMinutes: Math.round(windowMs / 60_000),
    windowFrom: activity.timeWhere.gte.toISOString(),
    windowTo: activity.timeWhere.lt.toISOString(),
    bucketMinutes: activity.bucketMinutes,
    totals: activity.totals,
    points: activity.points,
    updatedAt: new Date(nowMs).toISOString(),
    cached: false,
    lastUpdated: new Date(nowMs).toISOString(),
    stale: false,
    refreshInProgress: false,
    cacheAgeMs: 0,
  };

  app.log.info(
    {
      scope,
      role: user.role,
      tenantId: scopeTenantId,
      range: activity.range,
      connectCdrSourceRows: activity.sourceRows.connectCdr,
      legacyCallRecordRows: activity.sourceRows.legacyCallRecord,
      rowCount: activity.totals.total,
      totals: payload.totals,
    },
    "dashboard_call_traffic",
  );

  // Don't cache empty results longer than 30 s — a 0-row result is likely transient
  // (ingest lag, cold start) and should not persist in the cache for the full 2 min TTL.
  const cacheTtlMs = activity.totals.total === 0 ? 30_000 : 120_000;
  DASHBOARD_CALL_TRAFFIC_CACHE.set(cacheKey, { at: nowMs - (120_000 - cacheTtlMs), payload });
  return payload;
});

// ─── Dashboard: Communications (voicemail + chat) for the signed-in user ────
// Returns unread voicemail count + latest 5 voicemails (own extension's mailbox)
// and unread chat count + latest 5 thread previews (threads the user participates in).
app.get("/dashboard/communications", async (req, reply) => {
  const authUser = await requirePermission(req, reply, () => true);
  if (!authUser) return;
  const userId = authUser.sub;
  const userTenantId = authUser.tenantId ?? null;

  // ── Voicemails ──
  let voicemailUnread = 0;
  let voicemailRecent: Array<{ id: string; callerName: string | null; callerNumber: string | null; durationSec: number; receivedAt: string; read: boolean }> = [];
  try {
    const ext = await db.extension.findFirst({
      where: { ownerUserId: userId, ...(userTenantId ? { tenantId: userTenantId } : {}) },
      select: { extNumber: true, tenantId: true },
    });
    if (ext?.extNumber) {
      // Voicemails may carry either a Connect cuid or the "vpbx:{slug}" form for the
      // same tenant — match both so we don't miss rows ingested under either label.
      const tenantIdSet = ext.tenantId ? await resolveTenantIdFilterSet(ext.tenantId) : null;
      const vmWhere: Record<string, unknown> = {
        extension: ext.extNumber,
        deletedAt: null,
        folder: "inbox",
      };
      if (tenantIdSet && tenantIdSet.length > 0) {
        vmWhere.tenantId = tenantIdSet.length === 1 ? tenantIdSet[0] : { in: tenantIdSet };
      }
      const [unreadCount, recent] = await Promise.all([
        db.voicemail.count({ where: { ...vmWhere, readAt: null } }),
        db.voicemail.findMany({
          where: vmWhere,
          orderBy: { receivedAt: "desc" },
          take: 5,
          select: { id: true, callerName: true, callerNumber: true, durationSec: true, receivedAt: true, readAt: true },
        }),
      ]);
      voicemailUnread = unreadCount;
      voicemailRecent = recent.map((vm) => ({
        id: vm.id,
        callerName: vm.callerName ?? null,
        callerNumber: vm.callerNumber ?? null,
        durationSec: vm.durationSec ?? 0,
        receivedAt: vm.receivedAt.toISOString(),
        read: vm.readAt !== null,
      }));
    }
  } catch (err: any) {
    app.log.warn({ err: err?.message }, "dashboard_communications: voicemail query failed");
  }

  // ── Chat messages ──
  let messageUnread = 0;
  let messageRecent: Array<{ threadId: string; preview: string; counterpartyLabel: string; createdAt: string; unread: boolean }> = [];
  try {
    const participants = await (db as any).connectChatParticipant.findMany({
      where: { userId, leftAt: null, archivedForUser: false },
      select: { threadId: true, lastReadAt: true },
    });
    if (Array.isArray(participants) && participants.length > 0) {
      const threadIds = participants.map((p: any) => p.threadId);
      const lastReadByThread = new Map<string, Date | null>(
        participants.map((p: any) => [p.threadId, p.lastReadAt ?? null]),
      );

      const recentMessages = await (db as any).connectChatMessage.findMany({
        where: {
          threadId: { in: threadIds },
          deletedForEveryoneAt: null,
        },
        orderBy: { createdAt: "desc" },
        take: 50,
        select: {
          id: true, threadId: true, body: true, createdAt: true, direction: true, senderUserId: true, type: true,
        },
      });

      // Pick the latest message per thread for the preview list.
      const seenThreads = new Set<string>();
      const previews: typeof messageRecent = [];
      for (const m of recentMessages) {
        if (seenThreads.has(m.threadId)) continue;
        seenThreads.add(m.threadId);
        const lastRead = lastReadByThread.get(m.threadId) ?? null;
        const isUnread = m.direction === "INBOUND" && (!lastRead || m.createdAt > lastRead) && m.senderUserId !== userId;
        previews.push({
          threadId: m.threadId,
          preview: (m.body || (m.type !== "TEXT" ? `[${String(m.type).toLowerCase()}]` : "")).slice(0, 120),
          counterpartyLabel: "",
          createdAt: m.createdAt.toISOString(),
          unread: isUnread,
        });
        if (previews.length >= 5) break;
      }
      messageRecent = previews;

      // Resolve counterparty labels by looking up the thread title fallback.
      const threadRows = await (db as any).connectChatThread.findMany({
        where: { id: { in: previews.map((p) => p.threadId) } },
        select: { id: true, title: true, type: true, externalSmsE164: true },
      });
      const threadById = new Map<string, any>(threadRows.map((t: any) => [t.id, t]));
      for (const p of messageRecent) {
        const t = threadById.get(p.threadId);
        if (!t) continue;
        p.counterpartyLabel = t.title || t.externalSmsE164 || (t.type ? String(t.type).toLowerCase() : "Conversation");
      }

      // Total unread = sum of inbound messages newer than lastReadAt across all my threads.
      let total = 0;
      for (const part of participants) {
        const lastRead = part.lastReadAt as Date | null | undefined;
        const where: Record<string, unknown> = {
          threadId: part.threadId,
          direction: "INBOUND",
          deletedForEveryoneAt: null,
          senderUserId: { not: userId },
        };
        if (lastRead) (where as any).createdAt = { gt: lastRead };
        total += await (db as any).connectChatMessage.count({ where });
      }
      messageUnread = total;
    }
  } catch (err: any) {
    app.log.warn({ err: err?.message }, "dashboard_communications: chat query failed");
  }

  return reply.send({
    voicemails: { unread: voicemailUnread, recent: voicemailRecent },
    messages: { unread: messageUnread, recent: messageRecent },
    asOf: new Date().toISOString(),
  });
});

// ─── Dashboard: IVR analytics (admin only) ───────────────────────────────────
// Aggregates PbxCallEvent rows with eventType in (ivr_option_pressed, ivr_invalid,
// ivr_timeout, ivr_direct_dial, ivr_fallback_invalid, ivr_fallback_timeout) for the
// requested date range. Returns total IVR calls, top option digits, drop-off counts.
app.get("/dashboard/ivr-analytics", async (req, reply) => {
  const user = await requirePermission(req, reply, canViewCustomers);
  if (!user) return;

  const query = z.object({
    range: z.enum(["today", "7d", "30d", "custom"]).optional().default("today"),
    from: z.string().optional(),
    to: z.string().optional(),
    tenantId: z.string().optional(),
  }).parse(req.query || {});

  const isSuperAdmin = String(user.role || "").toUpperCase() === "SUPER_ADMIN";
  const scopeTenantId: string | null = isSuperAdmin
    ? (query.tenantId && query.tenantId !== "global" ? query.tenantId : null)
    : (user.tenantId ?? null);

  const customFrom = query.range === "custom" && query.from ? new Date(query.from) : null;
  const customTo = query.range === "custom" && query.to ? new Date(query.to) : null;
  const { timeWhere } = resolveDashboardCallRange(query.range, new Date(), customFrom, customTo);

  const where: Record<string, unknown> = {
    createdAt: timeWhere,
    eventType: {
      in: [
        "ivr_option_pressed",
        "ivr_invalid",
        "ivr_timeout",
        "ivr_direct_dial",
        "ivr_fallback_invalid",
        "ivr_fallback_timeout",
      ],
    },
  };
  // PbxCallEvent.tenantId is FK-bound to Connect cuid, but resolveTenantIdFilterSet
  // accepts either a cuid or a "vpbx:{slug}" input and returns the matching cuid +
  // slug form — using { in: [...] } here is a safe no-op for the slug rows.
  const tenantIdSet = scopeTenantId ? await resolveTenantIdFilterSet(scopeTenantId) : null;
  if (tenantIdSet && tenantIdSet.length > 0) {
    where.tenantId = tenantIdSet.length === 1 ? tenantIdSet[0] : { in: tenantIdSet };
  }

  let events: Array<{ id: string; eventType: string; callId: string | null; payload: any; createdAt: Date }> = [];
  try {
    events = await (db as any).pbxCallEvent.findMany({
      where,
      orderBy: { createdAt: "desc" },
      take: 5000,
      select: { id: true, eventType: true, callId: true, payload: true, createdAt: true },
    });
  } catch (err: any) {
    app.log.warn({ err: err?.message }, "dashboard_ivr_analytics: query failed");
  }

  const callIdsSeen = new Set<string>();
  const optionCounts = new Map<string, number>();
  let pressed = 0, invalid = 0, timeout = 0, directDial = 0;
  for (const ev of events) {
    if (ev.callId) callIdsSeen.add(ev.callId);
    if (ev.eventType === "ivr_option_pressed") {
      pressed++;
      const digit = String((ev.payload as any)?.digit ?? "").trim();
      if (digit) optionCounts.set(digit, (optionCounts.get(digit) ?? 0) + 1);
    } else if (ev.eventType === "ivr_invalid" || ev.eventType === "ivr_fallback_invalid") invalid++;
    else if (ev.eventType === "ivr_timeout" || ev.eventType === "ivr_fallback_timeout") timeout++;
    else if (ev.eventType === "ivr_direct_dial") directDial++;
  }

  const topOptions = Array.from(optionCounts.entries())
    .map(([digit, count]) => ({ digit, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 6);

  // Resolve labels via the active IvrOptionRoute config (digit → label).
  // IvrRouteProfile.tenantId is the Connect cuid only — pick that form from the set.
  const labelByDigit = new Map<string, string>();
  const ivrProfileTenantId = (tenantIdSet ?? []).find((id) => !id.startsWith("vpbx:")) ?? null;
  if (ivrProfileTenantId) {
    try {
      const profile = await db.ivrRouteProfile.findFirst({
        where: { tenantId: ivrProfileTenantId },
        orderBy: { updatedAt: "desc" },
        select: { id: true },
      });
      if (profile) {
        const routes = await db.ivrOptionRoute.findMany({
          where: { profileId: profile.id, enabled: true },
          select: { optionDigit: true, label: true, destinationType: true },
        });
        for (const r of routes) {
          labelByDigit.set(r.optionDigit, r.label || `${r.destinationType.replace(/_/g, " ")}`);
        }
      }
    } catch { /* non-fatal */ }
  }

  return reply.send({
    range: query.range,
    windowFrom: timeWhere.gte.toISOString(),
    windowTo: timeWhere.lt.toISOString(),
    scope: scopeTenantId ? "tenant" : "global",
    ...(scopeTenantId ? { tenantId: scopeTenantId } : {}),
    totals: {
      ivrCalls: callIdsSeen.size,
      optionsPressed: pressed,
      timeouts: timeout,
      invalidEntries: invalid,
      directDials: directDial,
      dropOffs: timeout + invalid,
    },
    topOptions: topOptions.map((o) => ({ ...o, label: labelByDigit.get(o.digit) ?? null })),
    asOf: new Date().toISOString(),
  });
});

app.get("/dashboard/summary", async (req, reply) => {
  const admin = await requirePermission(req, reply, canViewCustomers);
  if (!admin) return;
  const query = z.object({ range: z.enum(["24h", "7d", "30d"]).optional() }).parse(req.query || {});
  const { key: range, since } = resolveDashboardRange(query.range);

  try {
  const [
    invoicesAll,
    invoicesPaidInRange,
    paymentFailures,
    smsCampaignsSent,
    whatsAppInbound,
    whatsAppOutbound,
    emailFailed,
    emailQueued,
    overdueByCustomer,
    blockedCampaigns,
    failedEmailJobs,
    inboundFollowupThreads
  ] = await Promise.all([
    db.invoice.findMany({ where: { tenantId: admin.tenantId }, select: { id: true, status: true, customerId: true, amountCents: true } }),
    db.invoice.count({ where: { tenantId: admin.tenantId, status: "PAID", paidAt: { gte: since } } }),
    db.paymentEvent.findMany({
      where: { tenantId: admin.tenantId, status: "FAILED", receivedAt: { gte: since } },
      orderBy: { receivedAt: "desc" },
      take: 20,
      select: { id: true, type: true, receivedAt: true, amountCents: true, currency: true }
    }),
    db.smsCampaign.count({ where: { tenantId: admin.tenantId, status: "SENT", createdAt: { gte: since } } }),
    db.whatsAppMessage.count({ where: { tenantId: admin.tenantId, direction: "INBOUND", createdAt: { gte: since } } }),
    db.whatsAppMessage.count({ where: { tenantId: admin.tenantId, direction: "OUTBOUND", createdAt: { gte: since } } }),
    db.emailJob.count({ where: { tenantId: admin.tenantId, status: "FAILED", createdAt: { gte: since } } }),
    db.emailJob.count({ where: { tenantId: admin.tenantId, status: "QUEUED", createdAt: { gte: since } } }),
    db.invoice.groupBy({
      by: ["customerId"],
      where: { tenantId: admin.tenantId, status: "OVERDUE", customerId: { not: null } },
      _count: { _all: true },
      _sum: { amountCents: true }
    }),
    db.smsCampaign.findMany({
      where: { tenantId: admin.tenantId, OR: [{ status: "PAUSED" }, { status: "FAILED" }, { status: "NEEDS_APPROVAL" }, { holdReason: { not: null } }] },
      orderBy: { createdAt: "desc" },
      take: 10,
      select: { id: true, name: true, status: true, holdReason: true, createdAt: true }
    }),
    db.emailJob.findMany({
      where: { tenantId: admin.tenantId, status: "FAILED" },
      orderBy: { createdAt: "desc" },
      take: 10,
      select: { id: true, type: true, toEmail: true, lastErrorCode: true, createdAt: true }
    }),
    db.whatsAppThread.findMany({
      where: { tenantId: admin.tenantId, lastDirection: "INBOUND", lastMessageAt: { gte: since } },
      orderBy: { lastMessageAt: "desc" },
      take: 10,
      select: { id: true, customerId: true, contactName: true, contactNumber: true, lastMessageAt: true, lastStatus: true }
    })
  ]);

  const unpaidInvoicesCount = invoicesAll.filter((r) => r.status === "DRAFT" || r.status === "SENT" || r.status === "OVERDUE").length;
  const overdueInvoicesCount = invoicesAll.filter((r) => r.status === "OVERDUE").length;
  const customerIds = overdueByCustomer.map((r) => r.customerId).filter(Boolean) as string[];
  const overdueCustomers = customerIds.length
    ? await db.customer.findMany({ where: { tenantId: admin.tenantId, id: { in: customerIds } }, select: { id: true, displayName: true, primaryEmail: true } })
    : [];
  const overdueCustomerMap = new Map(overdueCustomers.map((c) => [c.id, c]));

  return {
    range,
    invoiceSummary: {
      unpaidCount: unpaidInvoicesCount,
      overdueCount: overdueInvoicesCount,
      paidInRangeCount: invoicesPaidInRange
    },
    paymentSummary: {
      recentFailureCount: paymentFailures.length,
      recentFailures: paymentFailures.map((f) => ({
        id: f.id,
        type: f.type,
        amountCents: f.amountCents,
        currency: f.currency,
        createdAt: f.receivedAt
      }))
    },
    messagingSummary: {
      smsCampaignsSentInRange: smsCampaignsSent,
      blockedOrSuspendedCampaigns: blockedCampaigns.length
    },
    whatsappSummary: {
      inboundCount: whatsAppInbound,
      outboundCount: whatsAppOutbound
    },
    emailSummary: {
      failedCount: emailFailed,
      queuedCount: emailQueued
    },
    customerAttentionSummary: {
      overdueCustomerCount: overdueByCustomer.length
    },
    attention: {
      overdueCustomers: overdueByCustomer.map((row) => {
        const customer = overdueCustomerMap.get(row.customerId || "");
        return {
          customerId: row.customerId,
          displayName: customer?.displayName || "Unknown customer",
          primaryEmail: customer?.primaryEmail || null,
          overdueInvoiceCount: row._count._all,
          overdueAmountCents: row._sum.amountCents || 0
        };
      }),
      failedEmailJobs: failedEmailJobs.map((e) => ({
        id: e.id,
        type: e.type,
        toEmailMasked: maskValue(e.toEmail, 2, 8),
        lastErrorCode: e.lastErrorCode || null,
        createdAt: e.createdAt
      })),
      blockedCampaigns: blockedCampaigns.map((c) => ({
        id: c.id,
        name: c.name,
        status: c.status,
        holdReason: c.holdReason || null,
        createdAt: c.createdAt
      })),
      whatsappInboundNeedsFollowup: inboundFollowupThreads.map((t) => ({
        threadId: t.id,
        customerId: t.customerId || null,
        contactName: t.contactName || null,
        contactNumberMasked: maskValue(t.contactNumber, 3, 2),
        lastStatus: t.lastStatus || null,
        lastMessageAt: t.lastMessageAt
      }))
    }
  };
  } catch (err: any) {
    app.log.warn({ err: err?.message || err, tenantId: admin.tenantId }, "dashboard/summary failed");
    return reply.status(200).send({
      range: "24h",
      invoiceSummary: { unpaidCount: 0, overdueCount: 0, paidInRangeCount: 0 },
      paymentSummary: { recentFailureCount: 0, recentFailures: [] },
      messagingSummary: { smsCampaignsSentInRange: 0, blockedOrSuspendedCampaigns: 0 },
      whatsappSummary: { inboundCount: 0, outboundCount: 0 },
      emailSummary: { failedCount: 0, queuedCount: 0 },
      customerAttentionSummary: { overdueCustomerCount: 0 },
      attention: { overdueCustomers: [], failedEmailJobs: [], blockedCampaigns: [], whatsappInboundNeedsFollowup: [] }
    });
  }
});

app.get("/dashboard/activity", async (req, reply) => {
  const admin = await requirePermission(req, reply, canViewCustomers);
  if (!admin) return;
  const query = z.object({ range: z.enum(["24h", "7d", "30d"]).optional() }).parse(req.query || {});
  const { key: range, since } = resolveDashboardRange(query.range);

  const [invoiceEvents, paymentFailures, smsCampaigns, waInbound, emailFailures, customers] = await Promise.all([
    db.invoiceEvent.findMany({
      where: { tenantId: admin.tenantId, createdAt: { gte: since }, type: { in: ["CREATED", "PAID"] } },
      orderBy: { createdAt: "desc" },
      take: 60,
      select: { invoiceId: true, type: true, createdAt: true }
    }),
    db.paymentEvent.findMany({
      where: { tenantId: admin.tenantId, status: "FAILED", receivedAt: { gte: since } },
      orderBy: { receivedAt: "desc" },
      take: 40,
      select: { id: true, receivedAt: true, amountCents: true, currency: true, subscriptionId: true }
    }),
    db.smsCampaign.findMany({
      where: { tenantId: admin.tenantId, status: "SENT", createdAt: { gte: since } },
      orderBy: { createdAt: "desc" },
      take: 40,
      select: { id: true, name: true, createdAt: true }
    }),
    db.whatsAppMessage.findMany({
      where: { tenantId: admin.tenantId, direction: "INBOUND", createdAt: { gte: since } },
      orderBy: { createdAt: "desc" },
      take: 40,
      select: { id: true, threadId: true, createdAt: true }
    }),
    db.emailJob.findMany({
      where: { tenantId: admin.tenantId, status: "FAILED", createdAt: { gte: since } },
      orderBy: { createdAt: "desc" },
      take: 40,
      select: { id: true, type: true, createdAt: true }
    }),
    db.customer.findMany({
      where: { tenantId: admin.tenantId, createdAt: { gte: since } },
      orderBy: { createdAt: "desc" },
      take: 40,
      select: { id: true, displayName: true, createdAt: true }
    })
  ]);

  const items: Array<{ type: string; timestamp: Date; label: string; link: string }> = [];
  for (const e of invoiceEvents) {
    if (e.type === "CREATED") {
      items.push({ type: "INVOICE_CREATED", timestamp: e.createdAt, label: `Invoice created`, link: `/dashboard/billing/invoices/${e.invoiceId}` });
    } else if (e.type === "PAID") {
      items.push({ type: "INVOICE_PAID", timestamp: e.createdAt, label: `Invoice paid`, link: `/dashboard/billing/invoices/${e.invoiceId}` });
    }
  }
  for (const e of paymentFailures) {
    items.push({
      type: "PAYMENT_FAILED",
      timestamp: e.receivedAt,
      label: `Payment failed${e.amountCents ? ` ($${(Number(e.amountCents) / 100).toFixed(2)})` : ""}`,
      link: e.subscriptionId ? `/dashboard/billing/invoices/${e.subscriptionId}` : "/dashboard/billing/invoices"
    });
  }
  for (const s of smsCampaigns) items.push({ type: "SMS_CAMPAIGN_SENT", timestamp: s.createdAt, label: `SMS campaign sent: ${s.name}`, link: `/dashboard/sms/campaigns/${s.id}` });
  for (const w of waInbound) items.push({ type: "WHATSAPP_INBOUND", timestamp: w.createdAt, label: "WhatsApp inbound message", link: `/dashboard/whatsapp/${w.threadId}` });
  for (const e of emailFailures) items.push({ type: "EMAIL_FAILED", timestamp: e.createdAt, label: `Email failed: ${e.type}`, link: "/dashboard/settings/email" });
  for (const c of customers) items.push({ type: "CUSTOMER_CREATED", timestamp: c.createdAt, label: `Customer created: ${c.displayName}`, link: `/dashboard/customers/${c.id}` });

  items.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
  return {
    range,
    items: items.slice(0, 120).map((i) => ({
      type: i.type,
      timestamp: i.timestamp,
      label: i.label,
      link: i.link
    }))
  };
});

app.get("/search/global", async (req, reply) => {
  const user = await requirePermission(req, reply, canViewCustomers);
  if (!user) return;
  const query = z.object({ q: z.string().min(2) }).parse(req.query || {});
  const q = query.q.trim();

  const [customers, invoices, extensions, numbers] = await Promise.all([
    db.customer.findMany({
      where: {
        tenantId: user.tenantId,
        OR: [
          { displayName: { contains: q, mode: "insensitive" } },
          { primaryEmail: { contains: q, mode: "insensitive" } },
          { primaryPhone: { contains: q, mode: "insensitive" } },
          { whatsappNumber: { contains: q, mode: "insensitive" } }
        ]
      },
      take: 20
    }),
    db.invoice.findMany({
      where: {
        tenantId: user.tenantId,
        OR: [
          { id: { contains: q, mode: "insensitive" } },
          { customerEmail: { contains: q, mode: "insensitive" } },
          { customerPhone: { contains: q, mode: "insensitive" } }
        ]
      },
      take: 20
    }),
    db.extension.findMany({
      where: {
        tenantId: user.tenantId,
        OR: [
          { extNumber: { contains: q, mode: "insensitive" } },
          { displayName: { contains: q, mode: "insensitive" } }
        ]
      },
      take: 20
    }),
    db.phoneNumber.findMany({
      where: {
        tenantId: user.tenantId,
        OR: [
          { phoneNumber: { contains: q, mode: "insensitive" } },
          { friendlyName: { contains: q, mode: "insensitive" } }
        ]
      },
      take: 20
    })
  ]);

  return {
    q,
    customers: customers.map((r) => ({ id: r.id, displayName: r.displayName, primaryPhone: maskValue(r.primaryPhone, 3, 2), link: `/dashboard/customers/${r.id}` })),
    invoices: invoices.map((r) => ({ id: r.id, status: r.status, amountCents: r.amountCents, link: `/dashboard/billing/invoices/${r.id}` })),
    extensions: extensions.map((r) => ({ id: r.id, ext: r.extNumber, label: r.displayName, link: `/dashboard/extensions` })),
    numbers: numbers.map((r) => ({ id: r.id, phoneNumber: maskValue(r.phoneNumber, 3, 2), link: `/dashboard/numbers` }))
  };
});

app.get("/billing/invoices", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageBilling);
  if (!admin) return;
  const rows = await db.invoice.findMany({
    where: { tenantId: admin.tenantId },
    include: { customer: { select: { id: true, displayName: true } } },
    orderBy: { createdAt: "desc" }
  });
  return rows.map((r) => ({
    ...r,
    customer: r.customer ? { id: r.customer.id, displayName: r.customer.displayName } : null
  }));
});

app.get("/billing/invoices/summary", async (req, reply) => {
  const admin = await requirePermission(req, reply, canManageBilling);
  if (!admin) return;
  const rows = await db.invoice.findMany({ where: { tenantId: admin.tenantId } });
  const byStatus: Record<string, number> = { DRAFT: 0, SENT: 0, OVERDUE: 0, PAID: 0, VOID: 0 };
  let totalCents = 0;
  let paidCents = 0;
  let outstandingCents = 0;
  for (const r of rows) {
    byStatus[r.status] = (byStatus[r.status] || 0) + 1;
    totalCents += r.amountCents || 0;
    if (r.status === "PAID") paidCents += r.amountCents || 0;
    if (r.status === "SENT" || r.status === "OVERDUE") outstandingCents += r.amountCents || 0;
  }
  return {
    totalInvoices: rows.length,
    byStatus,
    totals: { totalCents, paidCents, outstandingCents }
  };
});

